#ifndef PRISMIO_EMBEDDED_SOURCES_H
#define PRISMIO_EMBEDDED_SOURCES_H

#define PRISMIO_EMBEDDED_SOURCE_AVAILABLE 1

static const char prismio_embedded_prismio_platform_h[] =
"#ifndef PRISMIO_PLATFORM_H\n"
"#define PRISMIO_PLATFORM_H\n"
"\n"
"// Platform includes plus the few macros that paper over the differences between\n"
"// the Win32 and POSIX APIs the toolchain uses.\n"
"//\n"
"// Shared by both halves of the former driver.c -- program_support.c (linked into\n"
"// every compiled Prismio program) and build_driver.c (linked only into the\n"
"// compiler) -- so the two translation units cannot drift apart on things like the\n"
"// path separator.\n"
"\n"
"// <stdint.h> is here for the uint32_t that _NSGetExecutablePath() takes on macOS.\n"
"// Windows headers drag it in transitively, which is why its absence went unnoticed;\n"
"// on Apple platforms nothing else includes it and program_support.c fails to build.\n"
"#include <stdint.h>\n"
"#include <stdio.h>\n"
"#include <stdlib.h>\n"
"#include <string.h>\n"
"\n"
"#ifdef _WIN32\n"
"#include <direct.h>\n"
"#include <process.h>\n"
"#include <windows.h>\n"
"#define PRISMIO_GETPID _getpid\n"
"#define PRISMIO_MKDIR(path) _mkdir(path)\n"
"#define PRISMIO_RMDIR(path) _rmdir(path)\n"
"#define PRISMIO_PATH_SEP '\\\\'\n"
"#else\n"
"#include <dirent.h>\n"
"#include <sys/stat.h>\n"
"#include <unistd.h>\n"
"#ifdef __APPLE__\n"
"#include <mach-o/dyld.h>\n"
"#endif\n"
"#define PRISMIO_GETPID getpid\n"
"#define PRISMIO_MKDIR(path) mkdir(path, 0777)\n"
"#define PRISMIO_RMDIR(path) rmdir(path)\n"
"#define PRISMIO_PATH_SEP '/'\n"
"#endif\n"
"\n"
"#endif\n"
;

static const char prismio_embedded_prismio_runtime_h[] =
"#ifndef PRISMIO_RUNTIME_H\n"
"#define PRISMIO_RUNTIME_H\n"
"\n"
"// Program support: the half of the old driver.c that a *compiled Prismio program*\n"
"// can legitimately call at its own runtime. Implemented in program_support.c and\n"
"// destined for runtime.lib / runtime.a.\n"
"//\n"
"// The dividing line is \"would a user's program ever call this?\". Command-line\n"
"// access and plain file/path helpers: yes -- tests/test_19_runtime_split.psm\n"
"// already externs executable_directory, join_path, command_quote_arg and\n"
"// file_exists, and src/main.psm externs read_file, get_directory and delete_file.\n"
"// Driving llc/clang to produce an executable: no, that is the compiler's job and\n"
"// lives in build_driver.c (backend.lib).\n"
"//\n"
"// build_driver.c includes this header because the build orchestration reuses these\n"
"// helpers; the dependency runs backend -> runtime and never the other way.\n"
"\n"
"// --- file and path helpers ---\n"
"int file_exists(const char* path);\n"
"char* read_file(const char* path);\n"
"char* get_directory(const char* path);\n"
"char* join_path(const char* directory, const char* filename);\n"
"int delete_file(const char* path);\n"
"char* list_modules(const char* directory);\n"
"\n"
"// Directory containing the running executable. executable_directory() falls back\n"
"// to \".\" so callers always get a usable string; prismio_executable_directory()\n"
"// returns NULL when the location genuinely cannot be determined, which the\n"
"// toolchain-source search in build_driver.c needs in order to try its next\n"
"// candidate. Both return malloc'd memory.\n"
"char* executable_directory(void);\n"
"char* prismio_executable_directory(void);\n"
"\n"
"// --- command helpers ---\n"
"char* command_quote_arg(const char* arg);\n"
"int execute_command(const char* command);\n"
"\n"
"// --- command line, as seen by the compiled program ---\n"
"// Backed by the prismio_argc / prismio_argv globals that generated code defines\n"
"// and fills from main's real argc/argv (see generate_module / generate_function in\n"
"// src/ir.psm), which is what makes these work identically on every platform.\n"
"int cli_arg_count(void);\n"
"char* cli_arg(int index);\n"
"\n"
"#endif\n"
;

static const char prismio_embedded_lang_runtime_c[] =
"// AIF Level 4. Strings and lists are affine now, so codegen emits a release for\n"
"// them -- and the allocation at the other end of that pairing is in *this* file,\n"
"// not behind ir_alloc_object. Both ends have to swap together or a verify build\n"
"// reports every string release as a pointer that was never live.\n"
"//\n"
"// The build driver compiles this file with -DPRISMIO_AIF_VERIFY for `--verify`,\n"
"// which is why verify mode still changes no codegen: the swap happens when the\n"
"// runtime is compiled, not when the program is generated.\n"
"#ifdef PRISMIO_AIF_VERIFY\n"
"#include <stddef.h>\n"
"void* aif_verify_alloc(size_t size);\n"
"void  aif_verify_release(void* p);\n"
"void  aif_verify_arm(void);\n"
"#define rt_base_alloc(n) aif_verify_alloc(n)\n"
"#define rt_free(p)       aif_verify_release(p)\n"
"#else\n"
"#define rt_base_alloc(n) malloc(n)\n"
"#define rt_free(p)       free(p)\n"
"#endif\n"
"\n"
"#ifdef PRISMIO_WASM\n"
"\n"
"typedef unsigned int size_t;\n"
"#define NULL ((void*)0)\n"
"\n"
"extern unsigned char __heap_base;\n"
"\n"
"__attribute__((import_module(\"env\"), import_name(\"print\")))\n"
"void wasm_host_print(const char* str);\n"
"__attribute__((import_module(\"env\"), import_name(\"println\")))\n"
"void wasm_host_println(const char* str);\n"
"__attribute__((import_module(\"env\"), import_name(\"print_float\")))\n"
"void wasm_host_print_float(double value);\n"
"__attribute__((import_module(\"env\"), import_name(\"println_float\")))\n"
"void wasm_host_println_float(double value);\n"
"\n"
"static unsigned int wasm_heap_ptr = 0;\n"
"\n"
"static unsigned int wasm_align8(unsigned int value) {\n"
"    return (value + 7u) & ~7u;\n"
"}\n"
"\n"
"void* memcpy(void* dest, const void* src, size_t count) {\n"
"    unsigned char* d = (unsigned char*)dest;\n"
"    const unsigned char* s = (const unsigned char*)src;\n"
"    for (size_t i = 0; i < count; i++) {\n"
"        d[i] = s[i];\n"
"    }\n"
"    return dest;\n"
"}\n"
"\n"
"void* malloc(size_t size) {\n"
"    if (wasm_heap_ptr == 0) {\n"
"        wasm_heap_ptr = wasm_align8((unsigned int)&__heap_base);\n"
"    }\n"
"\n"
"    unsigned int raw = wasm_heap_ptr;\n"
"    unsigned int total = wasm_align8((unsigned int)size + 4u);\n"
"    wasm_heap_ptr += total;\n"
"    *((unsigned int*)raw) = (unsigned int)size;\n"
"    return (void*)(raw + 4u);\n"
"}\n"
"\n"
"void free(void* ptr) {\n"
"    (void)ptr;\n"
"}\n"
"\n"
"// Reset the bump allocator to the base \342\200\224 a cheap per-frame arena. String/data\n"
"// literals live below __heap_base and are unaffected.\n"
"void heap_reset(void) {\n"
"    wasm_heap_ptr = 0;\n"
"}\n"
"\n"
"// wasm has no `region` runtime -- arena_push and friends are native-only -- so\n"
"// the hint is a no-op here and every allocation goes to the bump allocator,\n"
"// which is what a region would have been anyway. The symbols exist because\n"
"// codegen may emit calls to them.\n"
"#define rt_alloc(n) rt_base_alloc(n)\n"
"void rt_arena_hint_push(void) {}\n"
"void rt_arena_hint_pop(void) {}\n"
"\n"
"void* realloc(void* ptr, size_t size) {\n"
"    if (!ptr) {\n"
"        return malloc(size);\n"
"    }\n"
"\n"
"    unsigned int old_size = *(((unsigned int*)ptr) - 1);\n"
"    void* next = malloc(size);\n"
"    if (next) {\n"
"        unsigned int copy_size = old_size < (unsigned int)size ? old_size : (unsigned int)size;\n"
"        memcpy(next, ptr, copy_size);\n"
"    }\n"
"    return next;\n"
"}\n"
"\n"
"size_t strlen(const char* s) {\n"
"    size_t len = 0;\n"
"    while (s[len] != '\\0') {\n"
"        len++;\n"
"    }\n"
"    return len;\n"
"}\n"
"\n"
"char* strcpy(char* dest, const char* src) {\n"
"    size_t i = 0;\n"
"    while (src[i] != '\\0') {\n"
"        dest[i] = src[i];\n"
"        i++;\n"
"    }\n"
"    dest[i] = '\\0';\n"
"    return dest;\n"
"}\n"
"\n"
"char* strncpy(char* dest, const char* src, size_t count) {\n"
"    size_t i = 0;\n"
"    while (i < count && src[i] != '\\0') {\n"
"        dest[i] = src[i];\n"
"        i++;\n"
"    }\n"
"    while (i < count) {\n"
"        dest[i] = '\\0';\n"
"        i++;\n"
"    }\n"
"    return dest;\n"
"}\n"
"\n"
"char* strcat(char* dest, const char* src) {\n"
"    size_t offset = strlen(dest);\n"
"    size_t i = 0;\n"
"    while (src[i] != '\\0') {\n"
"        dest[offset + i] = src[i];\n"
"        i++;\n"
"    }\n"
"    dest[offset + i] = '\\0';\n"
"    return dest;\n"
"}\n"
"\n"
"int strcmp(const char* a, const char* b) {\n"
"    size_t i = 0;\n"
"    while (a[i] != '\\0' && b[i] != '\\0') {\n"
"        if (a[i] != b[i]) {\n"
"            return ((unsigned char)a[i]) - ((unsigned char)b[i]);\n"
"        }\n"
"        i++;\n"
"    }\n"
"    return ((unsigned char)a[i]) - ((unsigned char)b[i]);\n"
"}\n"
"\n"
"int strncmp(const char* a, const char* b, size_t count) {\n"
"    for (size_t i = 0; i < count; i++) {\n"
"        if (a[i] != b[i] || a[i] == '\\0' || b[i] == '\\0') {\n"
"            return ((unsigned char)a[i]) - ((unsigned char)b[i]);\n"
"        }\n"
"    }\n"
"    return 0;\n"
"}\n"
"\n"
"char* strstr(const char* haystack, const char* needle) {\n"
"    size_t needle_len = strlen(needle);\n"
"    if (needle_len == 0) {\n"
"        return (char*)haystack;\n"
"    }\n"
"\n"
"    for (size_t i = 0; haystack[i] != '\\0'; i++) {\n"
"        if (strncmp(haystack + i, needle, needle_len) == 0) {\n"
"            return (char*)(haystack + i);\n"
"        }\n"
"    }\n"
"    return NULL;\n"
"}\n"
"\n"
"static char* int_to_str_buffer(int n, char* result) {\n"
"    unsigned int value;\n"
"    int negative = 0;\n"
"    if (n < 0) {\n"
"        negative = 1;\n"
"        value = (unsigned int)(0 - n);\n"
"    } else {\n"
"        value = (unsigned int)n;\n"
"    }\n"
"\n"
"    char temp[16];\n"
"    int len = 0;\n"
"    do {\n"
"        temp[len] = (char)('0' + (value % 10u));\n"
"        value = value / 10u;\n"
"        len++;\n"
"    } while (value > 0u);\n"
"\n"
"    int out = 0;\n"
"    if (negative) {\n"
"        result[out++] = '-';\n"
"    }\n"
"    while (len > 0) {\n"
"        result[out++] = temp[--len];\n"
"    }\n"
"    result[out] = '\\0';\n"
"    return result;\n"
"}\n"
"\n"
"// Println function - prints a string and adds a newline\n"
"void println(const char* str) {\n"
"    wasm_host_println(str);\n"
"}\n"
"\n"
"// Print function - prints a string without newline\n"
"void print(const char* str) {\n"
"    wasm_host_print(str);\n"
"}\n"
"\n"
"// Print integer\n"
"void print_int(int value) {\n"
"    char buffer[32];\n"
"    wasm_host_print(int_to_str_buffer(value, buffer));\n"
"}\n"
"\n"
"// Print integer with newline\n"
"void println_int(int value) {\n"
"    char buffer[32];\n"
"    wasm_host_println(int_to_str_buffer(value, buffer));\n"
"}\n"
"\n"
"// Print float\n"
"void print_float(double value) {\n"
"    wasm_host_print_float(value);\n"
"}\n"
"\n"
"// Print float with newline\n"
"void println_float(double value) {\n"
"    wasm_host_println_float(value);\n"
"}\n"
"\n"
"// Print boolean\n"
"void print_bool(int value) {\n"
"    wasm_host_print(value ? \"true\" : \"false\");\n"
"}\n"
"\n"
"// Print boolean with newline\n"
"void println_bool(int value) {\n"
"    wasm_host_println(value ? \"true\" : \"false\");\n"
"}\n"
"\n"
"// Print character\n"
"void print_char(char c) {\n"
"    char buffer[2];\n"
"    buffer[0] = c;\n"
"    buffer[1] = '\\0';\n"
"    wasm_host_print(buffer);\n"
"}\n"
"\n"
"// Print character with newline\n"
"void println_char(char c) {\n"
"    char buffer[2];\n"
"    buffer[0] = c;\n"
"    buffer[1] = '\\0';\n"
"    wasm_host_println(buffer);\n"
"}\n"
"\n"
"int str_equals(const char* s1, const char* s2) {\n"
"    return strcmp(s1, s2) == 0 ? 1 : 0;\n"
"}\n"
"\n"
"int str_compare(const char* s1, const char* s2) {\n"
"    return strcmp(s1, s2);\n"
"}\n"
"\n"
"int str_length(const char* s) {\n"
"    return (int)strlen(s);\n"
"}\n"
"\n"
"char* str_concat(const char* s1, const char* s2) {\n"
"    int len1 = (int)strlen(s1);\n"
"    int len2 = (int)strlen(s2);\n"
"    char* result = (char*)rt_alloc(len1 + len2 + 1);\n"
"\n"
"    strcpy(result, s1);\n"
"    strcat(result, s2);\n"
"\n"
"    return result;\n"
"}\n"
"\n"
"char* str_substring(const char* s, int start, int length) {\n"
"    int str_len = (int)strlen(s);\n"
"\n"
"    // Owned empty string rather than the literal \"\" -- see the native branch.\n"
"    if (start < 0 || start >= str_len) {\n"
"        start = str_len;\n"
"        length = 0;\n"
"    }\n"
"\n"
"    if (start + length > str_len) {\n"
"        length = str_len - start;\n"
"    }\n"
"\n"
"    char* result = (char*)rt_alloc(length + 1);\n"
"    strncpy(result, s + start, (size_t)length);\n"
"    result[length] = '\\0';\n"
"\n"
"    return result;\n"
"}\n"
"\n"
"char str_char_at(const char* s, int index) {\n"
"    int len = (int)strlen(s);\n"
"\n"
"    if (index < 0 || index >= len) {\n"
"        return '\\0';\n"
"    }\n"
"\n"
"    return s[index];\n"
"}\n"
"\n"
"// Unchecked-length read, for a caller that already knows the string's length.\n"
"//\n"
"// str_char_at() measures the whole string on every call, so the lexer -- which\n"
"// reads one character at a time -- spent O(n) per character and was therefore\n"
"// O(n^2) over a file. Scanning the 155 KB compiler meant several gigabytes of\n"
"// strlen traffic and was most of its compile time.\n"
"//\n"
"// The contract is 0 <= index <= str_length(s). index == length is deliberately\n"
"// allowed and returns the NUL terminator, because one-character lookahead at the\n"
"// end of input is normal and the buffer is always NUL-terminated. The lexer\n"
"// holds the length in the Lexer struct and checks against it, so the bound is\n"
"// still enforced -- just not re-measured on every character.\n"
"char str_byte_at(const char* s, int index) {\n"
"    if (index < 0) return '\\0';\n"
"    return s[index];\n"
"}\n"
"\n"
"int str_contains(const char* haystack, const char* needle) {\n"
"    return strstr(haystack, needle) != NULL ? 1 : 0;\n"
"}\n"
"\n"
"int str_starts_with(const char* s, const char* prefix) {\n"
"    int s_len = (int)strlen(s);\n"
"    int prefix_len = (int)strlen(prefix);\n"
"\n"
"    if (prefix_len > s_len) {\n"
"        return 0;\n"
"    }\n"
"\n"
"    return strncmp(s, prefix, (size_t)prefix_len) == 0 ? 1 : 0;\n"
"}\n"
"\n"
"int str_ends_with(const char* s, const char* suffix) {\n"
"    int s_len = (int)strlen(s);\n"
"    int suffix_len = (int)strlen(suffix);\n"
"\n"
"    if (suffix_len > s_len) {\n"
"        return 0;\n"
"    }\n"
"\n"
"    return strcmp(s + (s_len - suffix_len), suffix) == 0 ? 1 : 0;\n"
"}\n"
"\n"
"int str_index_of(const char* haystack, const char* needle) {\n"
"    const char* pos = strstr(haystack, needle);\n"
"\n"
"    if (pos == NULL) {\n"
"        return -1;\n"
"    }\n"
"\n"
"    return (int)(pos - haystack);\n"
"}\n"
"\n"
"char* str_replace(const char* s, const char* old_str, const char* new_str) {\n"
"    const char* pos = strstr(s, old_str);\n"
"\n"
"    if (pos == NULL) {\n"
"        char* result = (char*)rt_alloc(strlen(s) + 1);\n"
"        strcpy(result, s);\n"
"        return result;\n"
"    }\n"
"\n"
"    int old_len = (int)strlen(old_str);\n"
"    int new_len = (int)strlen(new_str);\n"
"    int prefix_len = (int)(pos - s);\n"
"    int suffix_len = (int)strlen(pos + old_len);\n"
"\n"
"    char* result = (char*)rt_alloc(prefix_len + new_len + suffix_len + 1);\n"
"    strncpy(result, s, (size_t)prefix_len);\n"
"    result[prefix_len] = '\\0';\n"
"    strcat(result, new_str);\n"
"    strcat(result, pos + old_len);\n"
"\n"
"    return result;\n"
"}\n"
"\n"
"int str_to_int(const char* s) {\n"
"    int sign = 1;\n"
"    int value = 0;\n"
"    if (*s == '-') {\n"
"        sign = -1;\n"
"        s++;\n"
"    }\n"
"    while (*s >= '0' && *s <= '9') {\n"
"        value = value * 10 + (*s - '0');\n"
"        s++;\n"
"    }\n"
"    return value * sign;\n"
"}\n"
"\n"
"char* int_to_str(int n) {\n"
"    char* result = (char*)rt_alloc(32);\n"
"    return int_to_str_buffer(n, result);\n"
"}\n"
"\n"
"char* str_clone(const char* s) {\n"
"    int len = (int)strlen(s);\n"
"    char* result = (char*)rt_alloc(len + 1);\n"
"    strcpy(result, s);\n"
"    return result;\n"
"}\n"
"\n"
"// One-character string. The lexer assembles a decoded string literal a character\n"
"// at a time and there is no other way to turn a Char into a String -- the\n"
"// language has no string builder and no char-to-string conversion.\n"
"char* str_from_char(char c) {\n"
"    char* result = (char*)rt_alloc(2);\n"
"    result[0] = c;\n"
"    result[1] = '\\0';\n"
"    return result;\n"
"}\n"
"\n"
"char* str_trim(const char* s) {\n"
"    while (*s == ' ' || *s == '\\t' || *s == '\\n' || *s == '\\r') {\n"
"        s++;\n"
"    }\n"
"\n"
"    // All-whitespace falls through to a one-byte allocation -- see the native branch.\n"
"\n"
"    const char* end = s + strlen(s) - 1;\n"
"    while (end > s && (*end == ' ' || *end == '\\t' || *end == '\\n' || *end == '\\r')) {\n"
"        end--;\n"
"    }\n"
"\n"
"    int len = (int)(end - s + 1);\n"
"    char* result = (char*)rt_alloc(len + 1);\n"
"    strncpy(result, s, (size_t)len);\n"
"    result[len] = '\\0';\n"
"\n"
"    return result;\n"
"}\n"
"\n"
"typedef struct {\n"
"    char** parts;\n"
"    int count;\n"
"} StringArray;\n"
"\n"
"StringArray* str_split(const char* s, char delimiter) {\n"
"    int count = 1;\n"
"    for (const char* p = s; *p; p++) {\n"
"        if (*p == delimiter) count++;\n"
"    }\n"
"\n"
"    StringArray* result = (StringArray*)malloc(sizeof(StringArray));\n"
"    result->parts = (char**)malloc(count * sizeof(char*));\n"
"    result->count = count;\n"
"\n"
"    int part_index = 0;\n"
"    const char* start = s;\n"
"    const char* p = s;\n"
"\n"
"    while (1) {\n"
"        if (*p == delimiter || *p == '\\0') {\n"
"            int len = (int)(p - start);\n"
"            result->parts[part_index] = (char*)malloc(len + 1);\n"
"            strncpy(result->parts[part_index], start, (size_t)len);\n"
"            result->parts[part_index][len] = '\\0';\n"
"            part_index++;\n"
"\n"
"            if (*p == '\\0') break;\n"
"            start = p + 1;\n"
"        }\n"
"        p++;\n"
"    }\n"
"\n"
"    return result;\n"
"}\n"
"\n"
"void str_split_free(StringArray* arr) {\n"
"    for (int i = 0; i < arr->count; i++) {\n"
"        free(arr->parts[i]);\n"
"    }\n"
"    free(arr->parts);\n"
"    free(arr);\n"
"}\n"
"\n"
"void* ptr_to_node(void* ptr) { return ptr; }\n"
"void* node_to_ptr(void* ptr) { return ptr; }\n"
"void* ptr_to_token(void* ptr) { return ptr; }\n"
"void* token_to_ptr(void* ptr) { return ptr; }\n"
"void* ptr_to_type(void* ptr) { return ptr; }\n"
"void* type_to_ptr(void* ptr) { return ptr; }\n"
"\n"
"#else\n"
"\n"
"#include <stdio.h>\n"
"#include <stdint.h>\n"
"#include <stdlib.h>\n"
"#include <string.h>\n"
"\n"
"// AIF Level 4, second half: `region` absorbs collections too.\n"
"//\n"
"// COMPILER-AUDIT scheduled Level 4 after Level 3 so that regions would already\n"
"// exist to take the string traffic -- but the arena is reached through\n"
"// ir_alloc_region, and only a struct literal goes through that. A string is\n"
"// allocated in this file, by str_concat, which has no idea where it is being\n"
"// called from.\n"
"//\n"
"// So the *call site* says. Codegen brackets a producing runtime call whose value\n"
"// aif_arena_at_node accepted with rt_arena_hint_push/pop, and the allocation\n"
"// inside bumps from the arena instead of the heap. The bracket goes around the\n"
"// call only -- arguments are already evaluated by then -- so a nested allocation\n"
"// that was not accepted does not inherit the hint.\n"
"//\n"
"// The hint is a depth, not a flag, because a producing call can be an argument\n"
"// to another one. It is never pushed outside a region: aif_arena_at_node needs an\n"
"// enclosing one before it says yes.\n"
"void* arena_alloc(size_t size);\n"
"\n"
"static int rt_arena_hint = 0;\n"
"\n"
"void rt_arena_hint_push(void) { rt_arena_hint++; }\n"
"void rt_arena_hint_pop(void)  { if (rt_arena_hint > 0) rt_arena_hint--; }\n"
"\n"
"static void* rt_alloc(size_t size) {\n"
"    if (rt_arena_hint > 0) return arena_alloc(size);\n"
"    return rt_base_alloc(size);\n"
"}\n"
"\n"
"// Println function - prints a string and adds a newline\n"
"void println(const char* str) {\n"
"    printf(\"%s\\n\", str);\n"
"    fflush(stdout);\n"
"}\n"
"\n"
"// Print function - prints a string without newline\n"
"void print(const char* str) {\n"
"    printf(\"%s\", str);\n"
"    fflush(stdout);\n"
"}\n"
"\n"
"// Print integer\n"
"void print_int(int value) {\n"
"    printf(\"%d\", value);\n"
"    fflush(stdout);\n"
"}\n"
"\n"
"// Print integer with newline\n"
"void println_int(int value) {\n"
"    printf(\"%d\\n\", value);\n"
"    fflush(stdout);\n"
"}\n"
"\n"
"// Print float\n"
"void print_float(double value) {\n"
"    printf(\"%g\", value);\n"
"    fflush(stdout);\n"
"}\n"
"\n"
"// Print float with newline\n"
"void println_float(double value) {\n"
"    printf(\"%g\\n\", value);\n"
"    fflush(stdout);\n"
"}\n"
"\n"
"// Print boolean\n"
"void print_bool(int value) {\n"
"    printf(\"%s\", value ? \"true\" : \"false\");\n"
"    fflush(stdout);\n"
"}\n"
"\n"
"// Print boolean with newline\n"
"void println_bool(int value) {\n"
"    printf(\"%s\\n\", value ? \"true\" : \"false\");\n"
"    fflush(stdout);\n"
"}\n"
"\n"
"// Print character\n"
"void print_char(char c) {\n"
"    printf(\"%c\", c);\n"
"    fflush(stdout);\n"
"}\n"
"\n"
"// Print character with newline\n"
"void println_char(char c) {\n"
"    printf(\"%c\\n\", c);\n"
"    fflush(stdout);\n"
"}\n"
"\n"
"// ============================================\n"
"// String Comparison\n"
"// ============================================\n"
"\n"
"int str_equals(const char* s1, const char* s2) {\n"
"    return strcmp(s1, s2) == 0 ? 1 : 0;\n"
"}\n"
"\n"
"int str_compare(const char* s1, const char* s2) {\n"
"    return strcmp(s1, s2);\n"
"}\n"
"\n"
"// ============================================\n"
"// String Length\n"
"// ============================================\n"
"\n"
"int str_length(const char* s) {\n"
"    return strlen(s);\n"
"}\n"
"\n"
"// ============================================\n"
"// String Concatenation\n"
"// ============================================\n"
"\n"
"char* str_concat(const char* s1, const char* s2) {\n"
"    int len1 = strlen(s1);\n"
"    int len2 = strlen(s2);\n"
"    char* result = (char*)rt_alloc(len1 + len2 + 1);\n"
"\n"
"    strcpy(result, s1);\n"
"    strcat(result, s2);\n"
"\n"
"    return result;\n"
"}\n"
"\n"
"// ============================================\n"
"// String Substring\n"
"// ============================================\n"
"\n"
"char* str_substring(const char* s, int start, int length) {\n"
"    int str_len = strlen(s);\n"
"\n"
"    // The out-of-range answer is an empty string the caller *owns*. It used to be\n"
"    // the literal \"\", which was fine while nothing freed a string and is a free\n"
"    // of a .rodata pointer now that they are affine (AIF Level 4). Anything\n"
"    // declared to return String hands back something a release can take.\n"
"    if (start < 0 || start >= str_len) {\n"
"        start = str_len;\n"
"        length = 0;\n"
"    }\n"
"\n"
"    if (start + length > str_len) {\n"
"        length = str_len - start;\n"
"    }\n"
"\n"
"    char* result = (char*)rt_alloc(length + 1);\n"
"    strncpy(result, s + start, length);\n"
"    result[length] = '\\0';\n"
"\n"
"    return result;\n"
"}\n"
"\n"
"// ============================================\n"
"// String Character At\n"
"// ============================================\n"
"\n"
"char str_char_at(const char* s, int index) {\n"
"    int len = strlen(s);\n"
"\n"
"    if (index < 0 || index >= len) {\n"
"        return '\\0';\n"
"    }\n"
"\n"
"    return s[index];\n"
"}\n"
"\n"
"// See the native definition for why this exists.\n"
"char str_byte_at(const char* s, int index) {\n"
"    if (index < 0) return '\\0';\n"
"    return s[index];\n"
"}\n"
"\n"
"// ============================================\n"
"// String Contains\n"
"// ============================================\n"
"\n"
"int str_contains(const char* haystack, const char* needle) {\n"
"    return strstr(haystack, needle) != NULL ? 1 : 0;\n"
"}\n"
"\n"
"// ============================================\n"
"// String Starts With\n"
"// ============================================\n"
"\n"
"int str_starts_with(const char* s, const char* prefix) {\n"
"    int s_len = strlen(s);\n"
"    int prefix_len = strlen(prefix);\n"
"\n"
"    if (prefix_len > s_len) {\n"
"        return 0;\n"
"    }\n"
"\n"
"    return strncmp(s, prefix, prefix_len) == 0 ? 1 : 0;\n"
"}\n"
"\n"
"// ============================================\n"
"// String Ends With\n"
"// ============================================\n"
"\n"
"int str_ends_with(const char* s, const char* suffix) {\n"
"    int s_len = strlen(s);\n"
"    int suffix_len = strlen(suffix);\n"
"\n"
"    if (suffix_len > s_len) {\n"
"        return 0;\n"
"    }\n"
"\n"
"    return strcmp(s + (s_len - suffix_len), suffix) == 0 ? 1 : 0;\n"
"}\n"
"\n"
"// ============================================\n"
"// String Index Of\n"
"// ============================================\n"
"\n"
"int str_index_of(const char* haystack, const char* needle) {\n"
"    const char* pos = strstr(haystack, needle);\n"
"\n"
"    if (pos == NULL) {\n"
"        return -1;\n"
"    }\n"
"\n"
"    return pos - haystack;\n"
"}\n"
"\n"
"// ============================================\n"
"// String Replace (first occurrence)\n"
"// ============================================\n"
"\n"
"char* str_replace(const char* s, const char* old_str, const char* new_str) {\n"
"    const char* pos = strstr(s, old_str);\n"
"\n"
"    if (pos == NULL) {\n"
"        // No match, return copy\n"
"        char* result = (char*)rt_alloc(strlen(s) + 1);\n"
"        strcpy(result, s);\n"
"        return result;\n"
"    }\n"
"\n"
"    int old_len = strlen(old_str);\n"
"    int new_len = strlen(new_str);\n"
"    int prefix_len = pos - s;\n"
"    int suffix_len = strlen(pos + old_len);\n"
"\n"
"    char* result = (char*)rt_alloc(prefix_len + new_len + suffix_len + 1);\n"
"\n"
"    // Copy prefix\n"
"    strncpy(result, s, prefix_len);\n"
"    result[prefix_len] = '\\0';\n"
"\n"
"    // Copy new string\n"
"    strcat(result, new_str);\n"
"\n"
"    // Copy suffix\n"
"    strcat(result, pos + old_len);\n"
"\n"
"    return result;\n"
"}\n"
"\n"
"// ============================================\n"
"// String To Integer\n"
"// ============================================\n"
"\n"
"int str_to_int(const char* s) {\n"
"    return atoi(s);\n"
"}\n"
"\n"
"// ============================================\n"
"// Integer To String\n"
"// ============================================\n"
"\n"
"char* int_to_str(int n) {\n"
"    char* result = (char*)rt_alloc(32);  // enough for any int\n"
"    sprintf(result, \"%d\", n);\n"
"    return result;\n"
"}\n"
"\n"
"// ============================================\n"
"// String Clone/Copy\n"
"// ============================================\n"
"\n"
"char* str_clone(const char* s) {\n"
"    int len = strlen(s);\n"
"    char* result = (char*)rt_alloc(len + 1);\n"
"    strcpy(result, s);\n"
"    return result;\n"
"}\n"
"\n"
"// One-character string. The lexer assembles a decoded string literal a character\n"
"// at a time and there is no other way to turn a Char into a String -- the\n"
"// language has no string builder and no char-to-string conversion.\n"
"char* str_from_char(char c) {\n"
"    char* result = (char*)rt_alloc(2);\n"
"    result[0] = c;\n"
"    result[1] = '\\0';\n"
"    return result;\n"
"}\n"
"\n"
"// ============================================\n"
"// String Trim (whitespace)\n"
"// ============================================\n"
"\n"
"char* str_trim(const char* s) {\n"
"    // Find start (skip leading whitespace)\n"
"    while (*s == ' ' || *s == '\\t' || *s == '\\n' || *s == '\\r') {\n"
"        s++;\n"
"    }\n"
"\n"
"    // An all-whitespace input falls through to a one-byte allocation rather than\n"
"    // returning the literal \"\" -- see str_substring for why a String return is\n"
"    // always something the caller can release.\n"
"\n"
"    // Find end (skip trailing whitespace)\n"
"    const char* end = s + strlen(s) - 1;\n"
"    while (end > s && (*end == ' ' || *end == '\\t' || *end == '\\n' || *end == '\\r')) {\n"
"        end--;\n"
"    }\n"
"\n"
"    int len = end - s + 1;\n"
"    char* result = (char*)rt_alloc(len + 1);\n"
"    strncpy(result, s, len);\n"
"    result[len] = '\\0';\n"
"\n"
"    return result;\n"
"}\n"
"\n"
"// ============================================\n"
"// String Split (simplified - single delimiter)\n"
"// ============================================\n"
"\n"
"typedef struct {\n"
"    char** parts;\n"
"    int count;\n"
"} StringArray;\n"
"\n"
"StringArray* str_split(const char* s, char delimiter) {\n"
"    // Count delimiters\n"
"    int count = 1;\n"
"    for (const char* p = s; *p; p++) {\n"
"        if (*p == delimiter) count++;\n"
"    }\n"
"\n"
"    StringArray* result = (StringArray*)malloc(sizeof(StringArray));\n"
"    result->parts = (char**)malloc(count * sizeof(char*));\n"
"    result->count = count;\n"
"\n"
"    int part_index = 0;\n"
"    const char* start = s;\n"
"    const char* p = s;\n"
"\n"
"    while (1) {\n"
"        if (*p == delimiter || *p == '\\0') {\n"
"            int len = p - start;\n"
"            result->parts[part_index] = (char*)malloc(len + 1);\n"
"            strncpy(result->parts[part_index], start, len);\n"
"            result->parts[part_index][len] = '\\0';\n"
"            part_index++;\n"
"\n"
"            if (*p == '\\0') break;\n"
"            start = p + 1;\n"
"        }\n"
"        p++;\n"
"    }\n"
"\n"
"    return result;\n"
"}\n"
"\n"
"void str_split_free(StringArray* arr) {\n"
"    for (int i = 0; i < arr->count; i++) {\n"
"        free(arr->parts[i]);\n"
"    }\n"
"    free(arr->parts);\n"
"    free(arr);\n"
"}\n"
"\n"
"// Helpers for type punning ASTNode pointers in Prismio\n"
"void* ptr_to_node(void* ptr) { return ptr; }\n"
"void* node_to_ptr(void* ptr) { return ptr; }\n"
"void* ptr_to_token(void* ptr) { return ptr; }\n"
"void* token_to_ptr(void* ptr) { return ptr; }\n"
"void* ptr_to_type(void* ptr) { return ptr; }\n"
"void* type_to_ptr(void* ptr) { return ptr; }\n"
"\n"
"// A note on how the frontend spells \"this slot is empty\", because it is not\n"
"// what it looks like and getting it wrong is a segfault rather than a warning.\n"
"//\n"
"// An absent child is the **empty string**, not a null pointer -- create_node()\n"
"// initialises every pointer slot to \"\". So `str_equals(p, \"\")` is the right\n"
"// question and a null test is not: a null test says \"present\" for an empty slot\n"
"// and the caller then dereferences it.\n"
"//\n"
"// What makes `str_equals(p, \"\")` fragile is the other direction. A punned\n"
"// pointer is a `char*`, so strcmp reads the *bytes of the pointed-to struct*,\n"
"// and a struct beginning with a zero-valued enum begins with a NUL byte -- so\n"
"// it compares equal to \"\" and a live node reads as an empty slot. src/ast.psm\n"
"// states the invariant that keeps this from firing and enforces it at the two\n"
"// enums that matter.\n"
"\n"
"// Native builds use libc malloc; the per-frame arena reset is a no-op here.\n"
"void heap_reset(void) { }\n"
"\n"
"// ============================================================================\n"
"// Arenas (AIF Level 3, SPEC 5.2)\n"
"//\n"
"// A stack of bump allocators. `region r { ... }` pushes one on entry and pops it\n"
"// on every exit; an allocation the analysis proved cannot outlive that region\n"
"// comes from the top of the stack, and the whole block goes back at once.\n"
"//\n"
"// COMPILER-AUDIT 3 expected the arena handle to be *threaded* to each allocation\n"
"// site as a second argument. It is dynamically scoped instead, which keeps\n"
"// ir_alloc_region a `fn(size) -> ptr` like the other two hooks and needs no new\n"
"// frontend plumbing. The cost of that choice is that a callee cannot be given a\n"
"// different arena from its caller's -- which does not arise, because only sites\n"
"// lexically inside the block are routed here (SPEC 5.2's own wording), and the\n"
"// analysis has already proved each of those dies no later than this region.\n"
"//\n"
"// Chunks are a linked list so a region that outgrows its first block keeps\n"
"// going rather than falling back to the heap; pointers already handed out stay\n"
"// valid because earlier chunks are not moved.\n"
"// ============================================================================\n"
"\n"
"#define ARENA_CHUNK_MIN 8192\n"
"#define ARENA_MAX_DEPTH 64\n"
"\n"
"typedef struct ArenaChunk {\n"
"    struct ArenaChunk* next;\n"
"    size_t used, cap;\n"
"    unsigned char* base;\n"
"} ArenaChunk;\n"
"\n"
"static ArenaChunk* arena_stack[ARENA_MAX_DEPTH];\n"
"static int arena_depth = 0;\n"
"\n"
"// Reported by arena_stats so a test can assert an allocation came from a region\n"
"// rather than from malloc -- the two are indistinguishable from the value.\n"
"static long arena_bytes_served, arena_objects_served, arena_regions_entered;\n"
"\n"
"// Chunks are pooled rather than returned to libc, and that is what makes\n"
"// LAYOUT 4's `arenaSetupCost` of ~40 cycles a real number instead of an\n"
"// aspiration. Without the pool a region that serves one allocation pays a malloc\n"
"// for its chunk and a free at the pop -- 180 cycles, more than the 87 an arena\n"
"// saves per allocation -- so the cost model would have to decline every small\n"
"// scope and automatic placement (LAYOUT 7.1) could never fire. With it, entering\n"
"// a region is a depth increment and a pointer swap.\n"
"//\n"
"// Only default-sized chunks are pooled. An oversized one was cut for a single\n"
"// large allocation and holding it would keep an arbitrary amount of memory live\n"
"// for the rest of the program.\n"
"static ArenaChunk* arena_pool;\n"
"\n"
"static ArenaChunk* arena_chunk_new(size_t need) {\n"
"    if (need <= ARENA_CHUNK_MIN && arena_pool) {\n"
"        ArenaChunk* c = arena_pool;\n"
"        arena_pool = c->next;\n"
"        c->used = 0;\n"
"        c->next = NULL;\n"
"        return c;\n"
"    }\n"
"\n"
"    size_t cap = need > ARENA_CHUNK_MIN ? need : ARENA_CHUNK_MIN;\n"
"    ArenaChunk* c = (ArenaChunk*)malloc(sizeof(ArenaChunk));\n"
"    if (!c) return NULL;\n"
"    c->base = (unsigned char*)malloc(cap);\n"
"    if (!c->base) { free(c); return NULL; }\n"
"    c->used = 0;\n"
"    c->cap = cap;\n"
"    c->next = NULL;\n"
"    return c;\n"
"}\n"
"\n"
"void arena_push(void) {\n"
"#ifdef PRISMIO_AIF_VERIFY\n"
"    aif_verify_arm();\n"
"#endif\n"
"    if (arena_depth >= ARENA_MAX_DEPTH) {\n"
"        fprintf(stderr, \"internal error: regions nested more than %d deep\\n\", ARENA_MAX_DEPTH);\n"
"        exit(1);\n"
"    }\n"
"    arena_stack[arena_depth++] = NULL;   // chunks are taken on first use\n"
"    arena_regions_entered++;\n"
"}\n"
"\n"
"void arena_pop(void) {\n"
"    if (arena_depth <= 0) return;\n"
"    ArenaChunk* c = arena_stack[--arena_depth];\n"
"    while (c) {\n"
"        ArenaChunk* next = c->next;\n"
"        if (c->cap == ARENA_CHUNK_MIN) {\n"
"            c->next = arena_pool;\n"
"            arena_pool = c;\n"
"        } else {\n"
"            free(c->base);\n"
"            free(c);\n"
"        }\n"
"        c = next;\n"
"    }\n"
"    arena_stack[arena_depth] = NULL;\n"
"}\n"
"\n"
"void* arena_alloc(size_t size) {\n"
"    // No region active. Codegen only routes a site here when one is, so this is\n"
"    // a corrupted arena stack rather than an ordinary case -- but falling back\n"
"    // to the ordinary allocator keeps SPEC 1's invariant (never wrong, only\n"
"    // slower) instead of returning NULL into code that will not check it. Through\n"
"    // rt_base_alloc rather than malloc so a verify build still accounts for it.\n"
"    if (arena_depth <= 0) return rt_base_alloc(size);\n"
"\n"
"    size_t need = (size + 15u) & ~(size_t)15u;   // 16-byte aligned, as malloc is\n"
"    ArenaChunk* c = arena_stack[arena_depth - 1];\n"
"    if (!c || c->used + need > c->cap) {\n"
"        ArenaChunk* fresh = arena_chunk_new(need);\n"
"        if (!fresh) return rt_base_alloc(size);\n"
"        fresh->next = c;\n"
"        arena_stack[arena_depth - 1] = fresh;\n"
"        c = fresh;\n"
"    }\n"
"\n"
"    void* p = c->base + c->used;\n"
"    c->used += need;\n"
"    arena_bytes_served += (long)need;\n"
"    arena_objects_served++;\n"
"    return p;\n"
"}\n"
"\n"
"long arena_objects(void) { return arena_objects_served; }\n"
"long arena_bytes(void)   { return arena_bytes_served; }\n"
"long arena_regions(void) { return arena_regions_entered; }\n"
"\n"
"// ============================================================================\n"
"// AIF `verify` mode (SPEC 7.3)\n"
"//\n"
"// A verify build swaps the allocator and deallocator names through\n"
"// ir_set_alloc_function / ir_set_free_function and changes nothing else -- the\n"
"// same seam COMPILER-AUDIT 3 describes for T2, used here for its first real\n"
"// purpose. Codegen is identical to a release build.\n"
"//\n"
"// What this covers, of SPEC 7.3's table:\n"
"//\n"
"//   Tier T0/T1, \"no access after frame or region exit\" -- partially. Released\n"
"//   memory is poisoned before it goes back to the allocator, so a read that\n"
"//   should not have happened returns a recognisable pattern rather than data\n"
"//   that is merely stale-but-plausible. Reads are not instrumented, so this\n"
"//   makes such a bug loud rather than impossible.\n"
"//\n"
"//   The balance itself, which is not in the table and should be: every object\n"
"//   released exactly once, and none left over. That is what catches a missed\n"
"//   drop path (leak) and a doubled one (release of something not live), which\n"
"//   are the two ways Level 2 can be wrong.\n"
"//\n"
"// What it does not cover, and why:\n"
"//\n"
"//   A = Unique / A <= Borrowed  need a count word in the object header, which\n"
"//                               is the same layout change T3 needs.\n"
"//   E = Region(r)               needs arenas; Level 3.\n"
"//   E <= Caller                 needs static-root reachability at return.\n"
"//   T = Isolated / Transferred  vacuous -- the language has no tasks.\n"
"//   C = Acyclic                 needs a periodic heap walk.\n"
"// ============================================================================\n"
"\n"
"#define AIF_VERIFY_BUCKETS 4096\n"
"#define AIF_VERIFY_POISON  0xDD\n"
"\n"
"typedef struct AifLive {\n"
"    struct AifLive* next;\n"
"    void* p;\n"
"    size_t size;\n"
"    long serial;        // allocation order, so a leak report names something\n"
"} AifLive;\n"
"\n"
"static AifLive* aif_live[AIF_VERIFY_BUCKETS];\n"
"static long aif_allocs, aif_releases, aif_violations;\n"
"static int aif_report_armed;\n"
"\n"
"static unsigned aif_live_hash(const void* p) {\n"
"    uintptr_t v = (uintptr_t)p;\n"
"    v ^= v >> 33;\n"
"    v *= 0xff51afd7ed558ccdull;\n"
"    v ^= v >> 29;\n"
"    return (unsigned)v & (AIF_VERIFY_BUCKETS - 1);\n"
"}\n"
"\n"
"void aif_verify_report(void) {\n"
"    long leaked = 0;\n"
"    for (int i = 0; i < AIF_VERIFY_BUCKETS; i++) {\n"
"        for (AifLive* n = aif_live[i]; n; n = n->next) {\n"
"            // The serial is the allocation's order in the run, which is the only\n"
"            // handle a leak report can offer without debug info: \"the 116th\n"
"            // object\" is enough to find the site by counting sites.\n"
"            if (leaked < 20) {\n"
"                fprintf(stderr, \"aif-verify: leaked #%ld (%lu bytes)\\n\",\n"
"                        n->serial, (unsigned long)n->size);\n"
"            }\n"
"            leaked++;\n"
"        }\n"
"    }\n"
"    fprintf(stderr, \"aif-verify: %ld allocated, %ld released, %ld leaked, %ld violation(s)\\n\",\n"
"            aif_allocs, aif_releases, leaked, aif_violations);\n"
"    if (leaked || aif_violations) {\n"
"        fprintf(stderr, \"aif-verify: FAILED -- an inferred fact did not hold at run time\\n\");\n"
"    }\n"
"}\n"
"\n"
"// Armed by the first allocation *or* the first region entry. Once LAYOUT 7.1\n"
"// places arenas automatically, a program can run to completion without a single\n"
"// call through the seam -- every allocation served from a bump block -- and\n"
"// arming only there would print no report at all, which reads as \"the seam was\n"
"// not redirected\" rather than as \"nothing needed accounting\".\n"
"void aif_verify_arm(void) {\n"
"    if (!aif_report_armed) {\n"
"        aif_report_armed = 1;\n"
"        atexit(aif_verify_report);\n"
"    }\n"
"}\n"
"\n"
"void* aif_verify_alloc(size_t size) {\n"
"    aif_verify_arm();\n"
"    void* p = malloc(size);\n"
"    if (!p) return NULL;\n"
"\n"
"    aif_allocs++;\n"
"    AifLive* n = (AifLive*)malloc(sizeof(AifLive));\n"
"    if (n) {\n"
"        n->p = p;\n"
"        n->size = size;\n"
"        n->serial = aif_allocs;\n"
"        unsigned b = aif_live_hash(p);\n"
"        n->next = aif_live[b];\n"
"        aif_live[b] = n;\n"
"    }\n"
"    return p;\n"
"}\n"
"\n"
"void aif_verify_release(void* p) {\n"
"    if (!p) return;\n"
"\n"
"    unsigned b = aif_live_hash(p);\n"
"    AifLive** link = &aif_live[b];\n"
"    while (*link && (*link)->p != p) link = &(*link)->next;\n"
"\n"
"    if (!*link) {\n"
"        // Either released twice, or never came from here. Both mean a fact was\n"
"        // wrong: the value was freed on a path the analysis did not account for.\n"
"        fprintf(stderr, \"aif-verify: release of a pointer that is not live (%p)\\n\", p);\n"
"        aif_violations++;\n"
"        return;\n"
"    }\n"
"\n"
"    AifLive* n = *link;\n"
"    *link = n->next;\n"
"    memset(p, AIF_VERIFY_POISON, n->size);\n"
"    free(n);\n"
"    free(p);\n"
"    aif_releases++;\n"
"}\n"
"\n"
"#endif\n"
"\n"
"// ============================================\n"
"// Growable list (List<T> for reference elements) \342\200\224 backs Prismio's List<T>.\n"
"// Stores pointer-sized elements; works on native and wasm32.\n"
"// ============================================\n"
"// ============================================\n"
"// AIF Level 5 -- T3, non-atomic reference counting (SPEC 3, T3).\n"
"//\n"
"// The count lives in a **prefix header**: rc_alloc returns base + RC_HDR, and the\n"
"// count is the word immediately in front of the pointer the program holds. That\n"
"// choice is what keeps the seam a fourth allocator name and nothing else.\n"
"// COMPILER-AUDIT 3's table says T3 is only \"partly\" expressible because \"the\n"
"// header word changes struct layout, which named_struct and every\n"
"// ir_struct_field_ptr index would have to account for\" -- true of a header word\n"
"// inside the object, and avoided entirely by putting it in front. The struct type\n"
"// LLVM sees is unchanged and every field index still means what it meant.\n"
"//\n"
"// **The count starts at zero, not one**, and that is the whole design rather than\n"
"// an off-by-one. What is counted here is *container edges*, because they are the\n"
"// only holder class this compiler both tracks and releases: a T3 value's escape is\n"
"// Caller or Global by definition of the tier, so aif_frees_at_scope_node can never\n"
"// admit its binding, and a struct field has no teardown yet. A value in no\n"
"// container is therefore held by nothing that will ever release, and counting the\n"
"// creating expression would put every such value permanently at one. At zero it\n"
"// simply leaks, which is exactly what it did before this existed.\n"
"//\n"
"// So: one container is one count, the teardown decrements, and the value dies with\n"
"// the last container that held it. A release without a matching retain cannot\n"
"// happen -- only a container retains, and only the same container releases.\n"
"//\n"
"// **An OPAQUE site is never refcounted.** The pointer came back from a function\n"
"// this compilation cannot see, so there is no header in front of it and reading\n"
"// one is reading whatever the allocator put there. That excludes all 37 of the\n"
"// compiler's own T3 sites, which is why the self-host exercises none of this.\n"
"// ============================================\n"
"\n"
"#define RC_HDR 16       // >= sizeof(size_t), and keeps the payload 16-byte aligned\n"
"\n"
"static size_t* rc_slot(void* p) {\n"
"    return &((size_t*)p)[-1];\n"
"}\n"
"\n"
"void* rc_alloc(size_t size) {\n"
"    unsigned char* base = (unsigned char*)rt_base_alloc(size + RC_HDR);\n"
"    if (!base) return 0;\n"
"    void* payload = base + RC_HDR;\n"
"    *rc_slot(payload) = 0;\n"
"    return payload;\n"
"}\n"
"\n"
"void rc_retain(void* p) {\n"
"    if (p) (*rc_slot(p))++;\n"
"}\n"
"\n"
"void rc_release(void* p) {\n"
"    if (!p) return;\n"
"    size_t* c = rc_slot(p);\n"
"    if (*c == 0) return;            // never retained: nothing holds it, nothing frees it\n"
"    if (--(*c) == 0) {\n"
"        rt_free((unsigned char*)p - RC_HDR);\n"
"    }\n"
"}\n"
"\n"
"// ============================================\n"
"// AIF T4b -- the cycle collector (CYCLES 3)\n"
"//\n"
"// Trial deletion (Bacon-Rajan), scoped to the T4b residue, traversing **only\n"
"// cyclic edges** (CYCLES 4). That restriction is the design's own contribution\n"
"// and it is available because the compiler owns the type graph: every edge of a\n"
"// value-level cycle connects two types in one SCC, so traversing only fields\n"
"// whose type is in the owner's SCC finds every cycle and never leaves the\n"
"// skeleton. A Node with two child pointers and six fields of strings and spans\n"
"// is walked through two edges, not eight, and the collector never descends into\n"
"// the string graph at all.\n"
"//\n"
"// **A T4b object is told what its cyclic children are.** `cyc_set_type` stamps a\n"
"// per-type function generated by codegen, for the same reason `list_set_elem_owner`\n"
"// exists: reading a header in front of a pointer to find out would be reading\n"
"// memory this compilation did not allocate.\n"
"//\n"
"// The count is container edges, exactly as at Level 5 -- a T4b value's escape is\n"
"// Caller or Global by the tier's definition, so no binding ever releases it.\n"
"// What T4b adds over T3 is the case Level 5 cannot handle: a decrement that does\n"
"// *not* reach zero is the only way a cycle can become garbage, so that is when a\n"
"// candidate root is buffered.\n"
"// ============================================\n"
"\n"
"#define CYC_BLACK  0\n"
"#define CYC_GREY   1\n"
"#define CYC_WHITE  2\n"
"#define CYC_PURPLE 3\n"
"\n"
"typedef void (*CycVisitor)(void*);\n"
"\n"
"typedef struct {\n"
"    size_t rc;\n"
"    unsigned char colour;\n"
"    unsigned char buffered;\n"
"    void (*children)(void*, CycVisitor);\n"
"    void (*release)(void*);\n"
"} CycHeader;\n"
"\n"
"// Rounded so the payload stays 16-byte aligned, like RC_HDR above.\n"
"#define CYC_HDR ((sizeof(CycHeader) + 15u) & ~(size_t)15u)\n"
"\n"
"static CycHeader* cyc_hdr(void* p) {\n"
"    return (CycHeader*)((unsigned char*)p - CYC_HDR);\n"
"}\n"
"\n"
"// CYCLES 6.1: collection is triggered by candidate-buffer occupancy, never by a\n"
"// timer -- a timer would make a program's pause profile a function of how fast\n"
"// the machine is, which is exactly the unpredictability SPEC's latency claim\n"
"// rejects. CYCLES 10 lists both of these as tuning constants needing\n"
"// measurement; they are the document's defaults and are not measured here.\n"
"#define CYC_THETA_BUFFER 4096\n"
"#define CYC_K_ROOTS      256\n"
"\n"
"static void** cyc_candidates;\n"
"static int cyc_cand_count, cyc_cand_cap;\n"
"\n"
"// The traversal's child window. Recursion uses a slice of this rather than a\n"
"// local array, so a wide object does not put its whole fan-out on the C stack.\n"
"static void** cyc_walk;\n"
"static int cyc_walk_len, cyc_walk_cap;\n"
"\n"
"static long long cyc_allocated, cyc_collected, cyc_collections;\n"
"\n"
"static void cyc_walk_push(void* p) {\n"
"    if (cyc_walk_len == cyc_walk_cap) {\n"
"        int grow = cyc_walk_cap ? cyc_walk_cap * 2 : 64;\n"
"        cyc_walk = (void**)realloc(cyc_walk, (size_t)grow * sizeof(void*));\n"
"        cyc_walk_cap = grow;\n"
"    }\n"
"    cyc_walk[cyc_walk_len++] = p;\n"
"}\n"
"\n"
"static void cyc_buffer(void* p) {\n"
"    if (cyc_cand_count == cyc_cand_cap) {\n"
"        int grow = cyc_cand_cap ? cyc_cand_cap * 2 : 256;\n"
"        cyc_candidates = (void**)realloc(cyc_candidates, (size_t)grow * sizeof(void*));\n"
"        cyc_cand_cap = grow;\n"
"    }\n"
"    cyc_candidates[cyc_cand_count++] = p;\n"
"}\n"
"\n"
"static void cyc_free_object(void* p) {\n"
"    CycHeader* h = cyc_hdr(p);\n"
"    cyc_collected++;\n"
"    // The generated release reclaims the object's *non*-cyclic owned fields and\n"
"    // the storage. Struct-field ownership declines a cyclic field precisely so\n"
"    // that it is the collector, not a recursive release, that follows it.\n"
"    if (h->release) {\n"
"        h->release(p);\n"
"    } else {\n"
"        rt_free((unsigned char*)p - CYC_HDR);\n"
"    }\n"
"}\n"
"\n"
"static void cyc_mark_grey(void* x) {\n"
"    CycHeader* h = cyc_hdr(x);\n"
"    if (h->colour == CYC_GREY) return;\n"
"    h->colour = CYC_GREY;\n"
"    if (!h->children) return;\n"
"\n"
"    int base = cyc_walk_len;\n"
"    h->children(x, cyc_walk_push);\n"
"    int end = cyc_walk_len;\n"
"    for (int i = base; i < end; i++) {\n"
"        void* y = cyc_walk[i];\n"
"        if (!y) continue;\n"
"        // Trial deletion of an internal reference. What survives with a non-zero\n"
"        // count is what something outside the candidate subgraph still holds.\n"
"        CycHeader* yh = cyc_hdr(y);\n"
"        if (yh->rc > 0) yh->rc--;\n"
"        cyc_mark_grey(y);\n"
"    }\n"
"    cyc_walk_len = base;\n"
"}\n"
"\n"
"static void cyc_scan_black(void* x) {\n"
"    CycHeader* h = cyc_hdr(x);\n"
"    h->colour = CYC_BLACK;\n"
"    if (!h->children) return;\n"
"\n"
"    int base = cyc_walk_len;\n"
"    h->children(x, cyc_walk_push);\n"
"    int end = cyc_walk_len;\n"
"    for (int i = base; i < end; i++) {\n"
"        void* y = cyc_walk[i];\n"
"        if (!y) continue;\n"
"        cyc_hdr(y)->rc++;\n"
"        if (cyc_hdr(y)->colour != CYC_BLACK) cyc_scan_black(y);\n"
"    }\n"
"    cyc_walk_len = base;\n"
"}\n"
"\n"
"static void cyc_scan(void* x) {\n"
"    CycHeader* h = cyc_hdr(x);\n"
"    if (h->colour != CYC_GREY) return;\n"
"    if (h->rc > 0) {\n"
"        cyc_scan_black(x);         // reachable from outside; the cycle is live\n"
"        return;\n"
"    }\n"
"    h->colour = CYC_WHITE;\n"
"    if (!h->children) return;\n"
"\n"
"    int base = cyc_walk_len;\n"
"    h->children(x, cyc_walk_push);\n"
"    int end = cyc_walk_len;\n"
"    for (int i = base; i < end; i++) {\n"
"        if (cyc_walk[i]) cyc_scan(cyc_walk[i]);\n"
"    }\n"
"    cyc_walk_len = base;\n"
"}\n"
"\n"
"static void cyc_collect_white(void* x) {\n"
"    CycHeader* h = cyc_hdr(x);\n"
"    if (h->colour != CYC_WHITE || h->buffered) return;\n"
"    h->colour = CYC_BLACK;\n"
"\n"
"    // Children are gathered *before* the object is freed: cyc_free_object hands\n"
"    // the storage back, and reading the field afterwards is a use-after-free.\n"
"    int base = cyc_walk_len;\n"
"    if (h->children) h->children(x, cyc_walk_push);\n"
"    int end = cyc_walk_len;\n"
"\n"
"    int n = end - base;\n"
"    void** kids = NULL;\n"
"    if (n > 0) {\n"
"        kids = (void**)malloc((size_t)n * sizeof(void*));\n"
"        for (int i = 0; i < n; i++) kids[i] = cyc_walk[base + i];\n"
"    }\n"
"    cyc_walk_len = base;\n"
"\n"
"    cyc_free_object(x);\n"
"\n"
"    for (int i = 0; i < n; i++) {\n"
"        if (kids[i]) cyc_collect_white(kids[i]);\n"
"    }\n"
"    free(kids);\n"
"}\n"
"\n"
"// CYCLES 6.2: at most K roots per collection, and the rest stay buffered.\n"
"// Bounding by roots rather than by traversal steps is what removes the need for\n"
"// an abort path in the common case -- the walk from K roots through cyclic edges\n"
"// only is bounded by the cyclic skeleton reachable from them.\n"
"static void cyc_collect(int all) {\n"
"    int take = all ? cyc_cand_count : (cyc_cand_count < CYC_K_ROOTS ? cyc_cand_count : CYC_K_ROOTS);\n"
"    if (take <= 0) return;\n"
"    cyc_collections++;\n"
"\n"
"    void** roots = (void**)malloc((size_t)take * sizeof(void*));\n"
"    for (int i = 0; i < take; i++) roots[i] = cyc_candidates[i];\n"
"    for (int i = take; i < cyc_cand_count; i++) cyc_candidates[i - take] = cyc_candidates[i];\n"
"    cyc_cand_count -= take;\n"
"\n"
"    // Unbuffered before the walk, so CollectWhite is allowed to reclaim a root:\n"
"    // its own `buffered` flag is what would otherwise stop it.\n"
"    for (int i = 0; i < take; i++) cyc_hdr(roots[i])->buffered = 0;\n"
"\n"
"    for (int i = 0; i < take; i++) cyc_mark_grey(roots[i]);\n"
"    for (int i = 0; i < take; i++) cyc_scan(roots[i]);\n"
"    for (int i = 0; i < take; i++) cyc_collect_white(roots[i]);\n"
"\n"
"    free(roots);\n"
"}\n"
"\n"
"// A final pass at exit, which is CYCLES 6.1's \"explicit request\". Without it a\n"
"// short program never reaches Theta_buffer and the collector never runs, so a\n"
"// fixture could not tell an implemented collector from an absent one.\n"
"static int cyc_exit_registered;\n"
"\n"
"static void cyc_final(void) {\n"
"    while (cyc_cand_count > 0) cyc_collect(1);\n"
"}\n"
"\n"
"void* cyc_alloc(size_t size) {\n"
"    if (!cyc_exit_registered) {\n"
"        cyc_exit_registered = 1;\n"
"        atexit(cyc_final);\n"
"    }\n"
"    unsigned char* base = (unsigned char*)rt_base_alloc(size + CYC_HDR);\n"
"    if (!base) return 0;\n"
"    void* payload = base + CYC_HDR;\n"
"    CycHeader* h = cyc_hdr(payload);\n"
"    h->rc = 0;\n"
"    h->colour = CYC_BLACK;\n"
"    h->buffered = 0;\n"
"    h->children = 0;\n"
"    h->release = 0;\n"
"    cyc_allocated++;\n"
"    return payload;\n"
"}\n"
"\n"
"void cyc_set_type(void* p, void (*children)(void*, CycVisitor), void (*release)(void*)) {\n"
"    if (!p) return;\n"
"    CycHeader* h = cyc_hdr(p);\n"
"    h->children = children;\n"
"    h->release = release;\n"
"}\n"
"\n"
"void cyc_retain(void* p) {\n"
"    if (p) cyc_hdr(p)->rc++;\n"
"}\n"
"\n"
"void cyc_release(void* p) {\n"
"    if (!p) return;\n"
"    CycHeader* h = cyc_hdr(p);\n"
"    if (h->rc == 0) return;         // never retained: nothing holds it, nothing frees it\n"
"    if (--h->rc == 0) {\n"
"        cyc_free_object(p);\n"
"        return;\n"
"    }\n"
"    // CYCLES 3.2. A count that dropped without reaching zero is the only way a\n"
"    // cycle can become garbage, so this is the one place a candidate is born.\n"
"    if (!h->buffered) {\n"
"        h->colour = CYC_PURPLE;\n"
"        h->buffered = 1;\n"
"        cyc_buffer(p);\n"
"        if (cyc_cand_count >= CYC_THETA_BUFFER) cyc_collect(0);\n"
"    }\n"
"}\n"
"\n"
"// CYCLES 6.1's third trigger, \"or on explicit request\". Exposed because the\n"
"// other two -- buffer occupancy and allocation failure -- are both unreachable\n"
"// in a fixture small enough to reason about, and a collector that only ever runs\n"
"// at exit cannot be shown to restore counts on a *live* cycle.\n"
"void cyc_collect_now(void) { cyc_collect(1); }\n"
"\n"
"long long cyc_objects(void)     { return cyc_allocated; }\n"
"long long cyc_reclaimed(void)   { return cyc_collected; }\n"
"long long cyc_collections_run(void) { return cyc_collections; }\n"
"\n"
"// AIF item 3. `elem_own` is what the container was told about its elements at\n"
"// construction, and being told is the only way it can know: the elements are\n"
"// plain pointers, and reading a header in front of one to find out would be\n"
"// reading memory this program may not have allocated.\n"
"//\n"
"// Set once, by codegen, from aif_elem_owner_at_node -- which answers NONE unless\n"
"// every element site agrees, so a list that reaches here with a mode is a list\n"
"// whose elements are uniformly reclaimable.\n"
"#define XEFY_ELEM_NONE   0\n"
"#define XEFY_ELEM_OBJECT 1\n"
"#define XEFY_ELEM_LIST   2\n"
"#define XEFY_ELEM_RC     3   // Level 5: a decrement, and the last holder frees\n"
"#define XEFY_ELEM_TYPED  4   // struct-field ownership: the element type's own release\n"
"#define XEFY_ELEM_CYCLE  5   // T4b: a decrement, and a non-zero result is a candidate root\n"
"\n"
"typedef struct {\n"
"    void** data;\n"
"    int len;\n"
"    int cap;\n"
"    int elem_own;\n"
"    // Struct-field ownership. Under XEFY_ELEM_TYPED the release differs per\n"
"    // element *type*, and an int cannot name a type -- so the container is told\n"
"    // the function. Same rule as elem_own, one step less abstract: the container\n"
"    // is told what to do because it has no way to ask.\n"
"    void (*elem_release)(void*);\n"
"} XefyList;\n"
"\n"
"void* list_new(void) {\n"
"    XefyList* l = (XefyList*)rt_alloc(sizeof(XefyList));\n"
"    l->len = 0;\n"
"    l->cap = 4;\n"
"    l->elem_own = XEFY_ELEM_NONE;\n"
"    l->elem_release = 0;\n"
"    l->data = (void**)rt_alloc(sizeof(void*) * 4);\n"
"    return l;\n"
"}\n"
"\n"
"void list_set_elem_owner(void* lp, int mode) {\n"
"    if (lp) ((XefyList*)lp)->elem_own = mode;\n"
"}\n"
"\n"
"void list_set_elem_releaser(void* lp, void (*fn)(void*)) {\n"
"    if (lp) ((XefyList*)lp)->elem_release = fn;\n"
"}\n"
"\n"
"// REQUIREMENTS 4. The checked unwrap behind `expect(x)`.\n"
"//\n"
"// A function rather than a branch in codegen, and returning its argument rather\n"
"// than being void, so the whole thing is one ordinary call expression -- no new\n"
"// blocks, no new backend surface, and the failure is loud instead of a null\n"
"// dereference somewhere downstream.\n"
"void* prismio_expect(void* p) {\n"
"    if (!p) {\n"
"        fprintf(stderr, \"runtime error: expect() called on a `none` value\\n\");\n"
"        exit(1);\n"
"    }\n"
"    return p;\n"
"}\n"
"\n"
"void list_push(void* lp, void* value) {\n"
"    XefyList* l = (XefyList*)lp;\n"
"    // AIF Level 5. The retain and the release are the same container's, driven by\n"
"    // the same stamped mode, so they cannot disagree about whether an element is\n"
"    // counted -- which is the failure a per-element answer would invite.\n"
"    if (l->elem_own == XEFY_ELEM_RC) rc_retain(value);\n"
"    if (l->elem_own == XEFY_ELEM_CYCLE) cyc_retain(value);\n"
"    if (l->len >= l->cap) {\n"
"        int nc = l->cap * 2;\n"
"        void** nd = (void**)rt_alloc(sizeof(void*) * nc);\n"
"        for (int i = 0; i < l->len; i++) nd[i] = l->data[i];\n"
"        rt_free(l->data);\n"
"        l->data = nd;\n"
"        l->cap = nc;\n"
"    }\n"
"    l->data[l->len] = value;\n"
"    l->len = l->len + 1;\n"
"}\n"
"\n"
"// AIF Level 4. A list is two allocations -- the handle and the element block --\n"
"// so the deallocator seam, which takes one pointer and frees it, cannot reclaim\n"
"// it: `free(list)` leaks the block. Codegen calls this instead for a droppable\n"
"// List binding, which is why the drop list carries a kind and not just a slot.\n"
"//\n"
"// AIF item 3: the elements go too, when the container was told it owns them.\n"
"// That reverses Level 4's rule, and the reason the old one was right then is the\n"
"// reason it is wrong now. It read `list_push` as `retain_in(0)` -- the element's\n"
"// escape becomes the list's -- and concluded that whoever owns the element owns\n"
"// it at its own binding. Nobody does: an element's escape is the container's, so\n"
"// aif_frees_at_scope_node declines the binding, and until something released\n"
"// here every element of every list leaked. One owner, and it is this one.\n"
"//\n"
"// Reverse order, as everywhere else a scope unwinds: an element may hold a\n"
"// reference to one pushed before it, never after.\n"
"void list_release(void* lp) {\n"
"    if (!lp) return;\n"
"    XefyList* l = (XefyList*)lp;\n"
"    if (l->elem_own != XEFY_ELEM_NONE) {\n"
"        for (int i = l->len - 1; i >= 0; i--) {\n"
"            void* e = l->data[i];\n"
"            if (!e) continue;\n"
"            if (l->elem_own == XEFY_ELEM_LIST)    list_release(e);\n"
"            else if (l->elem_own == XEFY_ELEM_RC) rc_release(e);\n"
"            else if (l->elem_own == XEFY_ELEM_CYCLE) cyc_release(e);\n"
"            else if (l->elem_own == XEFY_ELEM_TYPED) {\n"
"                // Struct-field ownership. The element owns fields of its own, so\n"
"                // rt_free(e) here would reclaim the object and leak everything\n"
"                // hanging off it -- which is exactly what g3_scene_graph did with\n"
"                // 1365 Nodes and three owned fields each.\n"
"                if (l->elem_release) l->elem_release(e);\n"
"            }\n"
"            else                                  rt_free(e);\n"
"        }\n"
"    }\n"
"    rt_free(l->data);\n"
"    rt_free(l);\n"
"}\n"
"\n"
"void* list_get(void* lp, int index) {\n"
"    XefyList* l = (XefyList*)lp;\n"
"    if (index < 0 || index >= l->len) return 0;\n"
"    return l->data[index];\n"
"}\n"
"\n"
"// The overwritten element is released only under RC, where the container's own\n"
"// count says whether anything else still holds it. Under OBJECT it leaks: the\n"
"// container owns it, but so might the binding the value came from, and a free\n"
"// here would be the double free the whole ownership rule exists to prevent.\n"
"void list_set(void* lp, int index, void* value) {\n"
"    XefyList* l = (XefyList*)lp;\n"
"    if (index < 0 || index >= l->len) return;\n"
"    if (l->elem_own == XEFY_ELEM_RC) {\n"
"        rc_retain(value);\n"
"        rc_release(l->data[index]);\n"
"    }\n"
"    l->data[index] = value;\n"
"}\n"
"\n"
"int list_len(void* lp) {\n"
"    XefyList* l = (XefyList*)lp;\n"
"    return l->len;\n"
"}\n"
;

static const char prismio_embedded_program_support_c[] =
"// Program support -- the runtime half of the former driver.c.\n"
"//\n"
"// Everything here is callable by a compiled Prismio program and belongs in\n"
"// runtime.lib / runtime.a. It must not depend on llc, clang, or anything else to\n"
"// do with *producing* a program; that all lives in build_driver.c (backend.lib).\n"
"\n"
"#include \"prismio_platform.h\"\n"
"#include \"prismio_runtime.h\"\n"
"\n"
"// Defined by generated code, not by this file: generate_module() in src/ir.psm\n"
"// emits them as module-level globals and generate_function() stores main's real\n"
"// argc/argv into them in the entry prologue. Reading them here is what makes\n"
"// cli_arg()/cli_arg_count() behave the same on Windows, Linux and macOS -- the\n"
"// previous version read the Windows-only CRT globals __argc/__argv and returned\n"
"// nothing at all anywhere else.\n"
"extern int prismio_argc;\n"
"extern char** prismio_argv;\n"
"\n"
"// ============================================\n"
"// File I/O\n"
"// ============================================\n"
"\n"
"int file_exists(const char* path) {\n"
"    FILE* file = fopen(path, \"r\");\n"
"    if (file) {\n"
"        fclose(file);\n"
"        return 1;\n"
"    }\n"
"    return 0;\n"
"}\n"
"\n"
"// Returns an empty string on failure, never NULL. Prismio has no null String, so\n"
"// every caller checks the result with str_equals(content, \"\") -- and handing them a\n"
"// NULL turned \"file not found\" into strcmp(NULL, \"\") and an access violation. That\n"
"// made `prismio build missing.psm`, and any `import` naming a file that is not\n"
"// there, crash silently instead of reporting the error the code already had ready.\n"
"char* read_file(const char* path) {\n"
"    FILE* file = fopen(path, \"rb\");\n"
"    if (!file) {\n"
"        char* empty = (char*)malloc(1);\n"
"        empty[0] = '\\0';\n"
"        return empty;\n"
"    }\n"
"\n"
"    fseek(file, 0, SEEK_END);\n"
"    long size = ftell(file);\n"
"    fseek(file, 0, SEEK_SET);\n"
"\n"
"    char* buffer = (char*)malloc(size + 1);\n"
"    if (!buffer) {\n"
"        fclose(file);\n"
"        char* empty = (char*)malloc(1);\n"
"        empty[0] = '\\0';\n"
"        return empty;\n"
"    }\n"
"\n"
"    size_t read = fread(buffer, 1, size, file);\n"
"    buffer[read] = '\\0';\n"
"\n"
"    fclose(file);\n"
"    return buffer;\n"
"}\n"
"\n"
"int delete_file(const char* path) {\n"
"    if (!path || path[0] == '\\0') return 0;\n"
"    return remove(path) == 0 ? 0 : 1;\n"
"}\n"
"\n"
"// ============================================\n"
"// Paths\n"
"// ============================================\n"
"\n"
"char* get_directory(const char* path) {\n"
"    const char* last_slash = strrchr(path, '/');\n"
"    const char* last_backslash = strrchr(path, '\\\\');\n"
"\n"
"    const char* separator = last_slash > last_backslash ? last_slash : last_backslash;\n"
"\n"
"    if (!separator) {\n"
"        char* result = (char*)malloc(2);\n"
"        strcpy(result, \".\");\n"
"        return result;\n"
"    }\n"
"\n"
"    int len = separator - path;\n"
"    char* result = (char*)malloc(len + 1);\n"
"    strncpy(result, path, len);\n"
"    result[len] = '\\0';\n"
"\n"
"    return result;\n"
"}\n"
"\n"
"// Separators in the result are normalised to the host's, including any the\n"
"// caller had already embedded in `filename`. That matters for module paths: a\n"
"// dotted import (`import ir.expr`) becomes \"ir/expr.psm\" in the frontend, which\n"
"// knows nothing about the host, and the joined path is then what every\n"
"// diagnostic about that module prints. Both separators open a file on Windows,\n"
"// so this is about how the path reads, not whether it resolves.\n"
"char* join_path(const char* directory, const char* filename) {\n"
"    int len = (int)strlen(directory) + 1 + (int)strlen(filename) + 1;\n"
"    char* result = (char*)malloc(len);\n"
"    sprintf(result, \"%s%c%s\", directory, PRISMIO_PATH_SEP, filename);\n"
"\n"
"    for (char* c = result; *c; c++) {\n"
"        if (*c == '/' || *c == '\\\\') *c = PRISMIO_PATH_SEP;\n"
"    }\n"
"    return result;\n"
"}\n"
"\n"
"// ============================================\n"
"// Listing a module directory\n"
"// ============================================\n"
"\n"
"static int compare_names(const void* a, const void* b) {\n"
"    return strcmp(*(const char* const*)a, *(const char* const*)b);\n"
"}\n"
"\n"
"// Records `filename` as a module name, minus its .psm suffix; ignores anything\n"
"// else. The suffix is re-checked here rather than trusted to the Win32 search\n"
"// pattern, which also matches 8.3 short names and would let through a file whose\n"
"// real extension is longer.\n"
"static void append_module_name(char*** names, int* count, int* capacity,\n"
"                               const char* filename) {\n"
"    size_t len = strlen(filename);\n"
"    if (len <= 4 || strcmp(filename + len - 4, \".psm\") != 0) return;\n"
"\n"
"    if (*count == *capacity) {\n"
"        *capacity = *capacity ? *capacity * 2 : 16;\n"
"        *names = (char**)realloc(*names, (size_t)*capacity * sizeof(char*));\n"
"        if (!*names) {\n"
"            fprintf(stderr, \"prismio: out of memory listing modules\\n\");\n"
"            exit(1);\n"
"        }\n"
"    }\n"
"\n"
"    char* stem = (char*)malloc(len - 3);\n"
"    memcpy(stem, filename, len - 4);\n"
"    stem[len - 4] = '\\0';\n"
"    (*names)[(*count)++] = stem;\n"
"}\n"
"\n"
"// The module names in `directory`, newline-separated, without the .psm suffix.\n"
"// Empty string when the directory does not exist or holds no modules -- the\n"
"// frontend reports that, because only it knows which `import` asked.\n"
"//\n"
"// **Sorted, and that is load-bearing.** This backs `import pkg.*`, so the order\n"
"// here becomes the order those modules are merged into the AST, which becomes\n"
"// the order their functions are emitted into the IR. Readdir order is a\n"
"// filesystem artefact that differs between machines and between a fresh checkout\n"
"// and a rebuilt one; taking it raw would mean two hosts building byte-different\n"
"// compilers from identical sources, breaking the fixpoint check and the seed.\n"
"char* list_modules(const char* directory) {\n"
"    char** names = NULL;\n"
"    int count = 0;\n"
"    int capacity = 0;\n"
"\n"
"#ifdef _WIN32\n"
"    char pattern[1024];\n"
"    snprintf(pattern, sizeof(pattern), \"%s%c*.psm\", directory, PRISMIO_PATH_SEP);\n"
"\n"
"    WIN32_FIND_DATAA entry;\n"
"    HANDLE search = FindFirstFileA(pattern, &entry);\n"
"    if (search != INVALID_HANDLE_VALUE) {\n"
"        do {\n"
"            if (entry.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY) continue;\n"
"            append_module_name(&names, &count, &capacity, entry.cFileName);\n"
"        } while (FindNextFileA(search, &entry));\n"
"        FindClose(search);\n"
"    }\n"
"#else\n"
"    DIR* dir = opendir(directory);\n"
"    if (dir) {\n"
"        struct dirent* entry;\n"
"        while ((entry = readdir(dir)) != NULL) {\n"
"            append_module_name(&names, &count, &capacity, entry->d_name);\n"
"        }\n"
"        closedir(dir);\n"
"    }\n"
"#endif\n"
"\n"
"    if (count > 1) qsort(names, count, sizeof(char*), compare_names);\n"
"\n"
"    size_t total = 1;\n"
"    for (int i = 0; i < count; i++) total += strlen(names[i]) + 1;\n"
"\n"
"    char* result = (char*)malloc(total);\n"
"    result[0] = '\\0';\n"
"    for (int i = 0; i < count; i++) {\n"
"        if (i > 0) strcat(result, \"\\n\");\n"
"        strcat(result, names[i]);\n"
"        free(names[i]);\n"
"    }\n"
"    free(names);\n"
"    return result;\n"
"}\n"
"\n"
"// ============================================\n"
"// Locating the running executable\n"
"// ============================================\n"
"\n"
"char* prismio_executable_directory(void) {\n"
"#ifdef _WIN32\n"
"    char exe_path[1024];\n"
"    DWORD len = GetModuleFileNameA(NULL, exe_path, sizeof(exe_path));\n"
"    if (len > 0 && len < sizeof(exe_path)) {\n"
"        return get_directory(exe_path);\n"
"    }\n"
"\n"
"    if (__argc > 0 && __argv[0] && __argv[0][0] != '\\0') {\n"
"        return get_directory(__argv[0]);\n"
"    }\n"
"#elif defined(__APPLE__)\n"
"    // macOS has no /proc, so the Linux branch below silently fails there.\n"
"    char raw_path[1024];\n"
"    uint32_t size = sizeof(raw_path);\n"
"    if (_NSGetExecutablePath(raw_path, &size) == 0) {\n"
"        char resolved_path[1024];\n"
"        if (realpath(raw_path, resolved_path) != NULL) {\n"
"            return get_directory(resolved_path);\n"
"        }\n"
"        return get_directory(raw_path);\n"
"    }\n"
"#else\n"
"    char exe_path[1024];\n"
"    ssize_t len = readlink(\"/proc/self/exe\", exe_path, sizeof(exe_path) - 1);\n"
"    if (len > 0) {\n"
"        exe_path[len] = '\\0';\n"
"        return get_directory(exe_path);\n"
"    }\n"
"#endif\n"
"    return NULL;\n"
"}\n"
"\n"
"char* executable_directory(void) {\n"
"    char* directory = prismio_executable_directory();\n"
"    if (directory) {\n"
"        return directory;\n"
"    }\n"
"\n"
"    char* fallback = (char*)malloc(2);\n"
"    strcpy(fallback, \".\");\n"
"    return fallback;\n"
"}\n"
"\n"
"// ============================================\n"
"// Commands\n"
"// ============================================\n"
"\n"
"char* command_quote_arg(const char* arg) {\n"
"    int len = strlen(arg);\n"
"    char* result = (char*)malloc((len * 2) + 3);\n"
"    int out = 0;\n"
"    result[out++] = '\"';\n"
"    for (int i = 0; i < len; i++) {\n"
"        if (arg[i] == '\"') {\n"
"            result[out++] = '\\\\';\n"
"        }\n"
"        result[out++] = arg[i];\n"
"    }\n"
"    result[out++] = '\"';\n"
"    result[out] = '\\0';\n"
"    return result;\n"
"}\n"
"\n"
"int execute_command(const char* command) {\n"
"#ifdef _WIN32\n"
"    int command_len = (int)strlen(command) + 16;\n"
"    char* wrapped = (char*)malloc(command_len);\n"
"    snprintf(wrapped, command_len, \"cmd /S /C \\\"%s\\\"\", command);\n"
"    int result = system(wrapped);\n"
"    free(wrapped);\n"
"    return result == 0 ? 0 : 1;\n"
"#else\n"
"    return system(command) == 0 ? 0 : 1;\n"
"#endif\n"
"}\n"
"\n"
"// ============================================\n"
"// Command line\n"
"// ============================================\n"
"\n"
"int cli_arg_count(void) {\n"
"    return prismio_argc;\n"
"}\n"
"\n"
"char* cli_arg(int index) {\n"
"    if (index < 0 || index >= prismio_argc || prismio_argv == NULL) {\n"
"        return \"\";\n"
"    }\n"
"    return prismio_argv[index];\n"
"}\n"
;

static const char prismio_embedded_build_driver_c[] =
"// Build orchestration -- the compiler half of the former driver.c.\n"
"//\n"
"// Everything here exists to *produce* an executable: locating the toolchain\n"
"// sources, naming temporary files, and driving llc and clang. A compiled Prismio\n"
"// program never calls any of it, so this translation unit belongs in\n"
"// backend.lib / backend.a alongside llvm-api-backend.c, and never in runtime.lib.\n"
"//\n"
"// It does depend on the runtime half (prismio_runtime.h) for plain file and path\n"
"// helpers. That direction is deliberate and one-way: backend -> runtime.\n"
"\n"
"#include \"prismio_platform.h\"\n"
"#include \"prismio_runtime.h\"\n"
"\n"
"#ifndef PRISMIO_EMBEDDED_SOURCES_HEADER\n"
"#define PRISMIO_EMBEDDED_SOURCES_HEADER \"embedded_sources.h\"\n"
"#endif\n"
"#include PRISMIO_EMBEDDED_SOURCES_HEADER\n"
"\n"
"// ============================================\n"
"// The toolchain source set\n"
"// ============================================\n"
"\n"
"// The C sources a compiled program is linked against, plus the headers they need\n"
"// available beside them when they are unpacked from the embedded copies. Keeping\n"
"// this as one table means the filesystem search, the embedded unpacking and the\n"
"// compile/link steps can never disagree about which files make up the toolchain.\n"
"typedef struct {\n"
"    const char* name;\n"
"    int compiled;  // 1 = compile to an object and link it; 0 = header, unpack only\n"
"    const char* role;\n"
"    // 1 = part of runtime.lib, needed by every compiled program.\n"
"    // 0 = part of backend.lib, needed only when building the compiler itself.\n"
"    int runtime;\n"
"} PrismioToolchainFile;\n"
"\n"
"static const PrismioToolchainFile prismio_toolchain_files[] = {\n"
"    { \"prismio_platform.h\", 0, NULL,              1 },\n"
"    { \"prismio_runtime.h\",  0, NULL,              1 },\n"
"    { \"lang_runtime.c\",     1, \"lang_runtime\",    1 },\n"
"    { \"program_support.c\",  1, \"program_support\", 1 },\n"
"    { \"build_driver.c\",     1, \"build_driver\",    0 },\n"
"    { \"ir_symbols.c\",       1, \"ir_symbols\",      0 },\n"
"    { \"aif_support.c\",      1, \"aif_support\",     0 },\n"
"    { \"diagnostics.c\",      1, \"diagnostics\",     0 },\n"
"    { \"llvm-api-backend.c\", 1, \"backend\",         0 },\n"
"};\n"
"\n"
"#define PRISMIO_TOOLCHAIN_FILE_COUNT \\\n"
"    ((int)(sizeof(prismio_toolchain_files) / sizeof(prismio_toolchain_files[0])))\n"
"\n"
"#ifdef PRISMIO_EMBEDDED_SOURCE_AVAILABLE\n"
"// Same order as prismio_toolchain_files. Generated by\n"
"// runtime/generate_embedded_sources.py, and checked against this table by\n"
"// tools/check_source_lists.py.\n"
"static const char* prismio_embedded_text(int index) {\n"
"    switch (index) {\n"
"        case 0: return prismio_embedded_prismio_platform_h;\n"
"        case 1: return prismio_embedded_prismio_runtime_h;\n"
"        case 2: return prismio_embedded_lang_runtime_c;\n"
"        case 3: return prismio_embedded_program_support_c;\n"
"        case 4: return prismio_embedded_build_driver_c;\n"
"        case 5: return prismio_embedded_ir_symbols_c;\n"
"        case 6: return prismio_embedded_aif_support_c;\n"
"        case 7: return prismio_embedded_diagnostics_c;\n"
"        case 8: return prismio_embedded_llvm_api_backend_c;\n"
"        default: return NULL;\n"
"    }\n"
"}\n"
"#endif\n"
"\n"
"// ============================================\n"
"// Path helpers (compiler-side only)\n"
"// ============================================\n"
"\n"
"static const char* path_file_name(const char* path) {\n"
"    const char* last_slash = strrchr(path, '/');\n"
"    const char* last_backslash = strrchr(path, '\\\\');\n"
"    const char* separator = last_slash > last_backslash ? last_slash : last_backslash;\n"
"    return separator ? separator + 1 : path;\n"
"}\n"
"\n"
"static char* path_without_extension(const char* path) {\n"
"    const char* filename = path_file_name(path);\n"
"    const char* dot = strrchr(filename, '.');\n"
"    int len = dot ? (int)(dot - path) : (int)strlen(path);\n"
"    char* result = (char*)malloc(len + 1);\n"
"    strncpy(result, path, len);\n"
"    result[len] = '\\0';\n"
"    return result;\n"
"}\n"
"\n"
"char* compiler_default_exe_path(const char* source_path) {\n"
"    char* stem = path_without_extension(source_path);\n"
"#ifdef _WIN32\n"
"    char* result = (char*)malloc(strlen(stem) + 5);\n"
"    sprintf(result, \"%s.exe\", stem);\n"
"#else\n"
"    char* result = (char*)malloc(strlen(stem) + 1);\n"
"    sprintf(result, \"%s\", stem);\n"
"#endif\n"
"    free(stem);\n"
"    return result;\n"
"}\n"
"\n"
"// Builds \"<dir><sep>.prismio-<stem>-<suffix>\", or the same without the directory\n"
"// prefix when the path has none. Shared by the temporary .ll, .obj and unpacked\n"
"// source directory names, which previously repeated this logic three times.\n"
"static char* compiler_temp_path(const char* base_path, const char* suffix) {\n"
"    char* directory = get_directory(base_path);\n"
"    const char* filename = path_file_name(base_path);\n"
"    const char* dot = strrchr(filename, '.');\n"
"    int stem_len = dot ? (int)(dot - filename) : (int)strlen(filename);\n"
"\n"
"    int has_directory = strcmp(directory, \".\") != 0;\n"
"    int result_len = (has_directory ? (int)strlen(directory) + 1 : 0) +\n"
"                     (int)strlen(\".prismio-\") + stem_len + 1 +\n"
"                     (int)strlen(suffix) + 1;\n"
"    char* result = (char*)malloc(result_len);\n"
"\n"
"    if (has_directory) {\n"
"        sprintf(result, \"%s%c.prismio-%.*s-%s\", directory, PRISMIO_PATH_SEP,\n"
"                stem_len, filename, suffix);\n"
"    } else {\n"
"        sprintf(result, \".prismio-%.*s-%s\", stem_len, filename, suffix);\n"
"    }\n"
"\n"
"    free(directory);\n"
"    return result;\n"
"}\n"
"\n"
"char* compiler_temp_ir_path(const char* source_path) {\n"
"    char suffix[32];\n"
"    snprintf(suffix, sizeof(suffix), \"%d.ll\", PRISMIO_GETPID());\n"
"    return compiler_temp_path(source_path, suffix);\n"
"}\n"
"\n"
"static char* compiler_temp_obj_path(const char* exe_file, const char* role) {\n"
"    char suffix[96];\n"
"    snprintf(suffix, sizeof(suffix), \"%s-%d.obj\", role, PRISMIO_GETPID());\n"
"    return compiler_temp_path(exe_file, suffix);\n"
"}\n"
"\n"
"static char* compiler_temp_source_dir(const char* exe_file) {\n"
"    char suffix[64];\n"
"    snprintf(suffix, sizeof(suffix), \"sources-%d\", PRISMIO_GETPID());\n"
"    return compiler_temp_path(exe_file, suffix);\n"
"}\n"
"\n"
"// ============================================\n"
"// Directories\n"
"// ============================================\n"
"\n"
"static int ensure_directory_exists(const char* directory) {\n"
"    if (!directory || directory[0] == '\\0' || strcmp(directory, \".\") == 0) {\n"
"        return 0;\n"
"    }\n"
"\n"
"    char* path = (char*)malloc(strlen(directory) + 1);\n"
"    strcpy(path, directory);\n"
"\n"
"    int start = 0;\n"
"#ifdef _WIN32\n"
"    if (strlen(path) > 2 && path[1] == ':') {\n"
"        start = 3;\n"
"    }\n"
"#endif\n"
"\n"
"    for (int i = start; path[i] != '\\0'; i++) {\n"
"        if (path[i] == '/' || path[i] == '\\\\') {\n"
"            char saved = path[i];\n"
"            path[i] = '\\0';\n"
"            if (strlen(path) > 0) {\n"
"                PRISMIO_MKDIR(path);\n"
"            }\n"
"            path[i] = saved;\n"
"        }\n"
"    }\n"
"\n"
"    PRISMIO_MKDIR(path);\n"
"    free(path);\n"
"    return 0;\n"
"}\n"
"\n"
"int compiler_prepare_output_path(const char* output_path) {\n"
"    char* directory = get_directory(output_path);\n"
"    int result = ensure_directory_exists(directory);\n"
"    free(directory);\n"
"    return result;\n"
"}\n"
"\n"
"// ============================================\n"
"// Locating toolchain sources on disk\n"
"// ============================================\n"
"\n"
"static int accept_if_exists(char* out, int out_size, const char* candidate) {\n"
"    if (!file_exists(candidate)) {\n"
"        return 0;\n"
"    }\n"
"    strncpy(out, candidate, out_size - 1);\n"
"    out[out_size - 1] = '\\0';\n"
"    return 1;\n"
"}\n"
"\n"
"// Looks for runtime/<filename>, first relative to the compiler executable (so an\n"
"// installed toolchain works from any working directory) and then relative to the\n"
"// current directory (so an in-repo build works).\n"
"static int find_toolchain_source(char* out, int out_size, const char* filename) {\n"
"    char candidate[1024];\n"
"\n"
"    char* compiler_dir = prismio_executable_directory();\n"
"    if (compiler_dir) {\n"
"        snprintf(candidate, sizeof(candidate), \"%s%c..%cruntime%c%s\",\n"
"                 compiler_dir, PRISMIO_PATH_SEP, PRISMIO_PATH_SEP, PRISMIO_PATH_SEP, filename);\n"
"        if (accept_if_exists(out, out_size, candidate)) {\n"
"            free(compiler_dir);\n"
"            return 1;\n"
"        }\n"
"\n"
"        snprintf(candidate, sizeof(candidate), \"%s%cruntime%c%s\",\n"
"                 compiler_dir, PRISMIO_PATH_SEP, PRISMIO_PATH_SEP, filename);\n"
"        if (accept_if_exists(out, out_size, candidate)) {\n"
"            free(compiler_dir);\n"
"            return 1;\n"
"        }\n"
"\n"
"        free(compiler_dir);\n"
"    }\n"
"\n"
"    static const char* prefixes[] = {\n"
"        \"runtime\\\\\", \"runtime/\",\n"
"        \"..\\\\runtime\\\\\", \"../runtime/\",\n"
"        \"..\\\\..\\\\runtime\\\\\", \"../../runtime/\",\n"
"        NULL\n"
"    };\n"
"    for (int i = 0; prefixes[i] != NULL; i++) {\n"
"        snprintf(candidate, sizeof(candidate), \"%s%s\", prefixes[i], filename);\n"
"        if (accept_if_exists(out, out_size, candidate)) {\n"
"            return 1;\n"
"        }\n"
"    }\n"
"\n"
"    return 0;\n"
"}\n"
"\n"
"// ============================================\n"
"// Embedded source unpacking\n"
"// ============================================\n"
"\n"
"static int write_text_file(const char* path, const char* content) {\n"
"    FILE* file = fopen(path, \"wb\");\n"
"    if (!file) {\n"
"        return 1;\n"
"    }\n"
"    fputs(content, file);\n"
"    fclose(file);\n"
"    return 0;\n"
"}\n"
"\n"
"#ifdef PRISMIO_EMBEDDED_SOURCE_AVAILABLE\n"
"static void write_c_string_literal(FILE* file, const char* name, const char* value) {\n"
"    fprintf(file, \"static const char %s[] =\\n\\\"\", name);\n"
"    int column = 0;\n"
"\n"
"    for (const unsigned char* p = (const unsigned char*)value; *p; p++) {\n"
"        unsigned char c = *p;\n"
"\n"
"        if (c == '\\n') {\n"
"            fputs(\"\\\\n\\\"\\n\\\"\", file);\n"
"            column = 0;\n"
"            continue;\n"
"        }\n"
"\n"
"        if (column > 96) {\n"
"            fputs(\"\\\"\\n\\\"\", file);\n"
"            column = 0;\n"
"        }\n"
"\n"
"        if (c == '\\\\') {\n"
"            fputs(\"\\\\\\\\\", file);\n"
"            column += 2;\n"
"        } else if (c == '\"') {\n"
"            fputs(\"\\\\\\\"\", file);\n"
"            column += 2;\n"
"        } else if (c == '\\r') {\n"
"            fputs(\"\\\\r\", file);\n"
"            column += 2;\n"
"        } else if (c == '\\t') {\n"
"            fputs(\"\\\\t\", file);\n"
"            column += 2;\n"
"        } else if (c < 32 || c > 126) {\n"
"            // Octal, because that is what C's \\nnn escape means.\n"
"            fprintf(file, \"\\\\%03o\", c);\n"
"            column += 4;\n"
"        } else {\n"
"            fputc(c, file);\n"
"            column += 1;\n"
"        }\n"
"    }\n"
"\n"
"    fputs(\"\\\";\\n\\n\", file);\n"
"}\n"
"\n"
"// The unpacked build_driver.c includes embedded_sources.h, so the temp directory\n"
"// needs its own copy carrying the same payload.\n"
"static int write_embedded_sources_header(const char* path) {\n"
"    FILE* file = fopen(path, \"wb\");\n"
"    if (!file) {\n"
"        return 1;\n"
"    }\n"
"\n"
"    fputs(\"#ifndef PRISMIO_EMBEDDED_SOURCES_H\\n\", file);\n"
"    fputs(\"#define PRISMIO_EMBEDDED_SOURCES_H\\n\\n\", file);\n"
"    fputs(\"#define PRISMIO_EMBEDDED_SOURCE_AVAILABLE 1\\n\\n\", file);\n"
"    write_c_string_literal(file, \"prismio_embedded_prismio_platform_h\", prismio_embedded_prismio_platform_h);\n"
"    write_c_string_literal(file, \"prismio_embedded_prismio_runtime_h\", prismio_embedded_prismio_runtime_h);\n"
"    write_c_string_literal(file, \"prismio_embedded_lang_runtime_c\", prismio_embedded_lang_runtime_c);\n"
"    write_c_string_literal(file, \"prismio_embedded_program_support_c\", prismio_embedded_program_support_c);\n"
"    write_c_string_literal(file, \"prismio_embedded_build_driver_c\", prismio_embedded_build_driver_c);\n"
"    write_c_string_literal(file, \"prismio_embedded_ir_symbols_c\", prismio_embedded_ir_symbols_c);\n"
"    write_c_string_literal(file, \"prismio_embedded_llvm_api_backend_c\", prismio_embedded_llvm_api_backend_c);\n"
"    fputs(\"#endif\\n\", file);\n"
"\n"
"    fclose(file);\n"
"    return 0;\n"
"}\n"
"#endif\n"
"\n"
"// ============================================\n"
"// Installed toolchain discovery\n"
"// ============================================\n"
"\n"
"// An installed toolchain looks like\n"
"//\n"
"//     <prefix>/bin/prismio(.exe)\n"
"//     <prefix>/lib/runtime.{lib,a}     linked into every compiled program\n"
"//     <prefix>/lib/backend.{lib,a}     linked into the compiler only\n"
"//     <prefix>/stdlib/\n"
"//\n"
"// and is located purely relative to the running executable: no hardcoded prefixes,\n"
"// no environment variables, no runtime sources shipped, nothing extracted from the\n"
"// binary. Also accepts lib/ sitting directly beside the executable, which is what a\n"
"// plain unpacked build tree looks like.\n"
"static int find_in_lib_dir(char* out, int out_size, const char* filename) {\n"
"    static const char* relative_dirs[] = { \"..\", \".\", NULL };\n"
"\n"
"    char* compiler_dir = prismio_executable_directory();\n"
"    if (!compiler_dir) {\n"
"        return 0;\n"
"    }\n"
"\n"
"    char candidate[1024];\n"
"    for (int d = 0; relative_dirs[d] != NULL; d++) {\n"
"        snprintf(candidate, sizeof(candidate), \"%s%c%s%clib%c%s\",\n"
"                 compiler_dir, PRISMIO_PATH_SEP, relative_dirs[d],\n"
"                 PRISMIO_PATH_SEP, PRISMIO_PATH_SEP, filename);\n"
"        if (accept_if_exists(out, out_size, candidate)) {\n"
"            free(compiler_dir);\n"
"            return 1;\n"
"        }\n"
"    }\n"
"\n"
"    free(compiler_dir);\n"
"    return 0;\n"
"}\n"
"\n"
"// Accepts either archive flavour, preferring the platform-native one, so a\n"
"// toolchain packaged on one platform still resolves if copied to another.\n"
"static int find_toolchain_library(char* out, int out_size, const char* stem) {\n"
"    static const char* extensions[] = {\n"
"#ifdef _WIN32\n"
"        \".lib\", \".a\",\n"
"#else\n"
"        \".a\", \".lib\",\n"
"#endif\n"
"        NULL\n"
"    };\n"
"\n"
"    char filename[256];\n"
"    for (int e = 0; extensions[e] != NULL; e++) {\n"
"        snprintf(filename, sizeof(filename), \"%s%s\", stem, extensions[e]);\n"
"        if (find_in_lib_dir(out, out_size, filename)) {\n"
"            return 1;\n"
"        }\n"
"    }\n"
"    return 0;\n"
"}\n"
"\n"
"// ============================================\n"
"// Runtime freshness (FNV-1a over the runtime sources)\n"
"// ============================================\n"
"\n"
"// Content hashing, not timestamps: a checkout, a copy or a touch all move mtimes\n"
"// without changing code, and mtime comparison across machines is unreliable.\n"
"// FNV-1a is implemented here rather than shelling out to shasum/certutil so the\n"
"// check has no external dependency and gives identical results on every platform.\n"
"#define PRISMIO_FNV_OFFSET 1469598103934665603ULL\n"
"#define PRISMIO_FNV_PRIME  1099511628211ULL\n"
"\n"
"static unsigned long long fnv1a_bytes(unsigned long long hash, const unsigned char* data) {\n"
"    for (const unsigned char* p = data; *p; p++) {\n"
"        // Normalize line endings so a CRLF checkout hashes the same as an LF one.\n"
"        if (*p == '\\r') continue;\n"
"        hash ^= (unsigned long long)(*p);\n"
"        hash *= PRISMIO_FNV_PRIME;\n"
"    }\n"
"    return hash;\n"
"}\n"
"\n"
"// Hash of the sources that make up runtime.lib, in table order. Returns a malloc'd\n"
"// 16-digit hex string, or an empty string when the sources are not on disk (a\n"
"// normal installed toolchain, where there is nothing to compare against).\n"
"char* compiler_runtime_source_hash(void) {\n"
"    unsigned long long hash = PRISMIO_FNV_OFFSET;\n"
"    char path[1024];\n"
"    int hashed = 0;\n"
"\n"
"    for (int i = 0; i < PRISMIO_TOOLCHAIN_FILE_COUNT; i++) {\n"
"        if (!prismio_toolchain_files[i].runtime) continue;\n"
"\n"
"        if (!find_toolchain_source(path, sizeof(path), prismio_toolchain_files[i].name)) {\n"
"            char* empty = (char*)malloc(1);\n"
"            empty[0] = '\\0';\n"
"            return empty;\n"
"        }\n"
"\n"
"        char* text = read_file(path);\n"
"        if (!text) {\n"
"            char* empty = (char*)malloc(1);\n"
"            empty[0] = '\\0';\n"
"            return empty;\n"
"        }\n"
"\n"
"        // Fold the file name in too, so moving code between files is detected.\n"
"        hash = fnv1a_bytes(hash, (const unsigned char*)prismio_toolchain_files[i].name);\n"
"        hash = fnv1a_bytes(hash, (const unsigned char*)text);\n"
"        free(text);\n"
"        hashed++;\n"
"    }\n"
"\n"
"    char* result = (char*)malloc(32);\n"
"    if (hashed == 0) {\n"
"        result[0] = '\\0';\n"
"    } else {\n"
"        snprintf(result, 32, \"%016llx\", hash);\n"
"    }\n"
"    return result;\n"
"}\n"
"\n"
"// The hash recorded beside the installed libraries when they were packaged.\n"
"// Empty when there is no installed toolchain or it predates hash recording.\n"
"char* compiler_installed_runtime_hash(void) {\n"
"    char path[1024];\n"
"    if (!find_in_lib_dir(path, sizeof(path), \"runtime.hash\")) {\n"
"        char* empty = (char*)malloc(1);\n"
"        empty[0] = '\\0';\n"
"        return empty;\n"
"    }\n"
"\n"
"    char* text = read_file(path);\n"
"    if (!text) {\n"
"        char* empty = (char*)malloc(1);\n"
"        empty[0] = '\\0';\n"
"        return empty;\n"
"    }\n"
"\n"
"    // Trim trailing whitespace the sidecar may have picked up.\n"
"    for (int i = (int)strlen(text) - 1; i >= 0; i--) {\n"
"        if (text[i] == '\\n' || text[i] == '\\r' || text[i] == ' ' || text[i] == '\\t') {\n"
"            text[i] = '\\0';\n"
"        } else {\n"
"            break;\n"
"        }\n"
"    }\n"
"    return text;\n"
"}\n"
"\n"
"// ============================================\n"
"// Build orchestration\n"
"// ============================================\n"
"\n"
"static int run_build_command(const char* command) {\n"
"    int result = system(command);\n"
"    return result == 0 ? 0 : 1;\n"
"}\n"
"\n"
"// SPEC 7.3's `--verify`, as seen from the build.\n"
"//\n"
"// Codegen swaps the allocator and deallocator *names* and changes nothing else.\n"
"// That covers everything ir_alloc_object handed out and nothing else -- but AIF\n"
"// Level 4 made strings and lists affine, and those are allocated inside\n"
"// lang_runtime.c, past the seam. Their release would then be a pointer the\n"
"// accounting never saw, which reads as a violation on every string a program\n"
"// drops.\n"
"//\n"
"// So a verify build compiles the runtime from source with PRISMIO_AIF_VERIFY\n"
"// defined, which points its own allocator at the same shims. That keeps both\n"
"// ends of every pairing on the same side of the swap, and it keeps the property\n"
"// worth having: the *generated code* is byte-identical either way.\n"
"static int g_verify_mode = 0;\n"
"\n"
"void compiler_set_verify_mode(int on) { g_verify_mode = on ? 1 : 0; }\n"
"\n"
"static int compile_ir_to_object(const char* ir_file, const char* program_obj) {\n"
"    char* q_ir = command_quote_arg(ir_file);\n"
"    char* q_obj = command_quote_arg(program_obj);\n"
"    int len = (int)(strlen(q_ir) + strlen(q_obj) + 64);\n"
"    char* command = (char*)malloc(len);\n"
"\n"
"    snprintf(command, len, \"llc %s -filetype=obj -o %s\", q_ir, q_obj);\n"
"    int result = run_build_command(command);\n"
"\n"
"    free(command);\n"
"    free(q_ir);\n"
"    free(q_obj);\n"
"    return result;\n"
"}\n"
"\n"
"// Normal user mode: link the program against the runtime library and nothing else.\n"
"// backend.lib -- the LLVM C API backend, the symbol tables, the diagnostics\n"
"// engine and this file -- exists only so the compiler can\n"
"// generate code and must never end up in a user's binary.\n"
"static int link_against_runtime_library(const char* program_obj,\n"
"                                        const char* runtime_lib,\n"
"                                        const char* exe_file) {\n"
"    char* q_obj = command_quote_arg(program_obj);\n"
"    char* q_lib = command_quote_arg(runtime_lib);\n"
"    char* q_exe = command_quote_arg(exe_file);\n"
"    int len = (int)(strlen(q_obj) + strlen(q_lib) + strlen(q_exe) + 64);\n"
"    char* command = (char*)malloc(len);\n"
"\n"
"    snprintf(command, len, \"clang %s %s -o %s\", q_obj, q_lib, q_exe);\n"
"    int result = run_build_command(command);\n"
"\n"
"    free(command);\n"
"    free(q_obj);\n"
"    free(q_lib);\n"
"    free(q_exe);\n"
"    return result;\n"
"}\n"
"\n"
"// Compile the toolchain from source and link it with the program.\n"
"//\n"
"// `include_backend` selects the build mode:\n"
"//   0 -- normal user build with no installed libraries beside the compiler. Only\n"
"//        the runtime half is compiled, so the result matches what linking\n"
"//        runtime.lib would have produced and the backend still cannot leak in.\n"
"//   1 -- bootstrap. The program being built *is* the compiler, so it needs the\n"
"//        backend's ir_* functions and the build orchestration in this file.\n"
"//\n"
"// `force_filesystem` refuses the copies embedded in this binary and insists on\n"
"// runtime/ on disk. Bootstrap requires it: the embedded copies were frozen when the\n"
"// *bootstrapping* compiler was built, so using them would silently link the previous\n"
"// generation's runtime into the new one and make edits to runtime/*.c invisible --\n"
"// the exact staleness chain this refactor exists to break.\n"
"static int build_from_toolchain_sources(const char* program_obj, const char* exe_file,\n"
"                                        int include_backend, int force_filesystem) {\n"
"    char source_paths[PRISMIO_TOOLCHAIN_FILE_COUNT][1024];\n"
"    char* unpacked_paths[PRISMIO_TOOLCHAIN_FILE_COUNT];\n"
"    for (int i = 0; i < PRISMIO_TOOLCHAIN_FILE_COUNT; i++) {\n"
"        source_paths[i][0] = '\\0';\n"
"        unpacked_paths[i] = NULL;\n"
"    }\n"
"\n"
"    int using_embedded_sources = 0;\n"
"    char* embedded_dir = NULL;\n"
"    char* embedded_header = NULL;\n"
"\n"
"#ifdef PRISMIO_EMBEDDED_SOURCE_AVAILABLE\n"
"    if (!force_filesystem) {\n"
"    embedded_dir = compiler_temp_source_dir(exe_file);\n"
"    if (ensure_directory_exists(embedded_dir) == 0) {\n"
"        using_embedded_sources = 1;\n"
"\n"
"        for (int i = 0; i < PRISMIO_TOOLCHAIN_FILE_COUNT && using_embedded_sources; i++) {\n"
"            if (!prismio_toolchain_files[i].runtime && !include_backend) continue;\n"
"\n"
"            unpacked_paths[i] = join_path(embedded_dir, prismio_toolchain_files[i].name);\n"
"            if (write_text_file(unpacked_paths[i], prismio_embedded_text(i)) != 0) {\n"
"                using_embedded_sources = 0;\n"
"                break;\n"
"            }\n"
"            strncpy(source_paths[i], unpacked_paths[i], sizeof(source_paths[i]) - 1);\n"
"            source_paths[i][sizeof(source_paths[i]) - 1] = '\\0';\n"
"        }\n"
"\n"
"        // Only build_driver.c includes embedded_sources.h, so the unpacked copy is\n"
"        // needed only when the backend is part of this build.\n"
"        if (using_embedded_sources && include_backend) {\n"
"            embedded_header = join_path(embedded_dir, \"embedded_sources.h\");\n"
"            if (write_embedded_sources_header(embedded_header) != 0) {\n"
"                using_embedded_sources = 0;\n"
"            }\n"
"        }\n"
"    }\n"
"    }\n"
"#endif\n"
"\n"
"    if (!using_embedded_sources) {\n"
"        for (int i = 0; i < PRISMIO_TOOLCHAIN_FILE_COUNT; i++) {\n"
"            if (!prismio_toolchain_files[i].runtime && !include_backend) continue;\n"
"\n"
"            if (!find_toolchain_source(source_paths[i], sizeof(source_paths[i]),\n"
"                                       prismio_toolchain_files[i].name)) {\n"
"                fprintf(stderr, \"ERROR: could not find runtime/%s\\n\",\n"
"                        prismio_toolchain_files[i].name);\n"
"                return 1;\n"
"            }\n"
"        }\n"
"    }\n"
"\n"
"    // The IR is already an object by this point; compile each toolchain source and\n"
"    // link the lot together with it.\n"
"    char* q_program_obj = command_quote_arg(program_obj);\n"
"    char* q_exe = command_quote_arg(exe_file);\n"
"\n"
"    char* objs[PRISMIO_TOOLCHAIN_FILE_COUNT];\n"
"    char* q_objs[PRISMIO_TOOLCHAIN_FILE_COUNT];\n"
"    for (int i = 0; i < PRISMIO_TOOLCHAIN_FILE_COUNT; i++) {\n"
"        objs[i] = NULL;\n"
"        q_objs[i] = NULL;\n"
"    }\n"
"\n"
"    int command_len = 4096;\n"
"    for (int i = 0; i < PRISMIO_TOOLCHAIN_FILE_COUNT; i++) {\n"
"        command_len += (int)strlen(source_paths[i]) * 2 + 64;\n"
"    }\n"
"    command_len += (int)(strlen(q_exe) + strlen(q_program_obj));\n"
"    char* command = (char*)malloc(command_len);\n"
"    int result = 0;\n"
"\n"
"    for (int i = 0; i < PRISMIO_TOOLCHAIN_FILE_COUNT && result == 0; i++) {\n"
"        if (!prismio_toolchain_files[i].compiled) continue;\n"
"        if (!prismio_toolchain_files[i].runtime && !include_backend) continue;\n"
"\n"
"        objs[i] = compiler_temp_obj_path(exe_file, prismio_toolchain_files[i].role);\n"
"        q_objs[i] = command_quote_arg(objs[i]);\n"
"        char* q_src = command_quote_arg(source_paths[i]);\n"
"        snprintf(command, command_len, \"clang -Wno-deprecated-declarations %s-c %s -o %s\",\n"
"                 g_verify_mode ? \"-DPRISMIO_AIF_VERIFY \" : \"\", q_src, q_objs[i]);\n"
"        if (run_build_command(command) != 0) result = 1;\n"
"        free(q_src);\n"
"    }\n"
"\n"
"    if (result == 0) {\n"
"        int written = snprintf(command, command_len, \"clang %s\", q_program_obj);\n"
"        for (int i = 0; i < PRISMIO_TOOLCHAIN_FILE_COUNT; i++) {\n"
"            if (!q_objs[i]) continue;\n"
"            written += snprintf(command + written, command_len - written, \" %s\", q_objs[i]);\n"
"        }\n"
"        snprintf(command + written, command_len - written, \" -o %s\", q_exe);\n"
"        if (run_build_command(command) != 0) result = 1;\n"
"    }\n"
"\n"
"    for (int i = 0; i < PRISMIO_TOOLCHAIN_FILE_COUNT; i++) {\n"
"        if (objs[i]) delete_file(objs[i]);\n"
"        if (unpacked_paths[i]) delete_file(unpacked_paths[i]);\n"
"    }\n"
"    if (embedded_header) delete_file(embedded_header);\n"
"    if (embedded_dir) PRISMIO_RMDIR(embedded_dir);\n"
"\n"
"    free(command);\n"
"    free(q_exe);\n"
"    free(q_program_obj);\n"
"    for (int i = 0; i < PRISMIO_TOOLCHAIN_FILE_COUNT; i++) {\n"
"        if (q_objs[i]) free(q_objs[i]);\n"
"        if (objs[i]) free(objs[i]);\n"
"        if (unpacked_paths[i]) free(unpacked_paths[i]);\n"
"    }\n"
"    if (embedded_header) free(embedded_header);\n"
"    if (embedded_dir) free(embedded_dir);\n"
"\n"
"    return result;\n"
"}\n"
"\n"
"// Normal user mode. The program links against the runtime only, so a link failure\n"
"// here is most often someone trying to build the compiler itself -- src/main.psm\n"
"// calls the backend's ir_* functions, which deliberately are not in runtime.lib.\n"
"int compiler_build_executable(const char* ir_file, const char* exe_file) {\n"
"    if (compiler_prepare_output_path(exe_file) != 0) {\n"
"        fprintf(stderr, \"ERROR: could not create output directory\\n\");\n"
"        return 1;\n"
"    }\n"
"\n"
"    char* program_obj = compiler_temp_obj_path(exe_file, \"program\");\n"
"    int result = compile_ir_to_object(ir_file, program_obj);\n"
"\n"
"    if (result == 0) {\n"
"        char runtime_lib[1024];\n"
"        // An installed runtime.lib was compiled without PRISMIO_AIF_VERIFY, so a\n"
"        // verify build cannot use it: half the allocations would be outside the\n"
"        // accounting. Compiling from source is slower and this is a debug mode.\n"
"        if (!g_verify_mode\n"
"            && find_toolchain_library(runtime_lib, sizeof(runtime_lib), \"runtime\")) {\n"
"            result = link_against_runtime_library(program_obj, runtime_lib, exe_file);\n"
"        } else {\n"
"            result = build_from_toolchain_sources(program_obj, exe_file, 0, 0);\n"
"        }\n"
"\n"
"        if (result != 0) {\n"
"            fprintf(stderr,\n"
"                    \"\\nNOTE: a normal build links against the Prismio runtime only.\\n\"\n"
"                    \"      If you are building the Prismio compiler itself, use:\\n\"\n"
"                    \"          prismio bootstrap %s\\n\"\n"
"                    \"      which also links the compiler backend (the ir_* functions).\\n\",\n"
"                    \"src/main.psm\");\n"
"        }\n"
"    }\n"
"\n"
"    delete_file(program_obj);\n"
"    free(program_obj);\n"
"    return result;\n"
"}\n"
"\n"
"// Bootstrap / compiler-development mode.\n"
"//\n"
"// Always builds against the repository sources and never against an installed\n"
"// toolchain, so an edit to runtime/*.c shows up in the very next compiler\n"
"// generation. That guarantee is what the mode exists for, and it is why this is a\n"
"// separate entry point selected by the `bootstrap` command rather than a flag or an\n"
"// environment variable read somewhere inside the build.\n"
"int compiler_bootstrap_executable(const char* ir_file, const char* exe_file) {\n"
"    if (compiler_prepare_output_path(exe_file) != 0) {\n"
"        fprintf(stderr, \"ERROR: could not create output directory\\n\");\n"
"        return 1;\n"
"    }\n"
"\n"
"    char probe[1024];\n"
"    if (!find_toolchain_source(probe, sizeof(probe), \"lang_runtime.c\")) {\n"
"        fprintf(stderr,\n"
"                \"ERROR: bootstrap needs the Prismio repository sources.\\n\"\n"
"                \"       Could not find runtime/lang_runtime.c relative to the compiler\\n\"\n"
"                \"       or the current directory. Run this from a Prismio checkout.\\n\");\n"
"        return 1;\n"
"    }\n"
"\n"
"    char* program_obj = compiler_temp_obj_path(exe_file, \"program\");\n"
"    int result = compile_ir_to_object(ir_file, program_obj);\n"
"\n"
"    if (result == 0) {\n"
"        // include_backend = 1: the artifact being produced is a compiler.\n"
"        result = build_from_toolchain_sources(program_obj, exe_file, 1, 1);\n"
"    }\n"
"\n"
"    delete_file(program_obj);\n"
"    free(program_obj);\n"
"    return result;\n"
"}\n"
"\n"
"// The path in the *command* position needs more care than one in an argument\n"
"// position, which is why this does not just quote and go.\n"
"//\n"
"// On Windows, `prismio run app.psm -o build/app.exe` failed outright: cmd.exe\n"
"// reads `build/app.exe` as the command `build` with the switch `/app.exe`, even\n"
"// quoted. It then reported \"Program exited with failure\" -- blaming the compiled\n"
"// program for a mistake the compiler made invoking it. A forward slash in `-o`\n"
"// is a completely ordinary thing to write, so normalise instead of rejecting.\n"
"//\n"
"// Everywhere else the separator is left alone: llc and clang take forward\n"
"// slashes happily, and only the command position is parsed by the shell this way.\n"
"static char* run_command_path(const char* exe_file) {\n"
"    size_t len = strlen(exe_file);\n"
"    // Room for a leading \"./\" (or \".\\\") if the path has no directory part.\n"
"    char* path = (char*)malloc(len + 3);\n"
"    if (!path) return NULL;\n"
"\n"
"    int has_separator = 0;\n"
"    for (size_t i = 0; i < len; i++) {\n"
"        if (exe_file[i] == '/' || exe_file[i] == '\\\\') has_separator = 1;\n"
"    }\n"
"\n"
"    size_t out = 0;\n"
"    // A bare name would otherwise be looked up on PATH first, which can run a\n"
"    // different program with the same name than the one just built.\n"
"    if (!has_separator) {\n"
"        path[out++] = '.';\n"
"        path[out++] = PRISMIO_PATH_SEP;\n"
"    }\n"
"\n"
"    for (size_t i = 0; i < len; i++) {\n"
"        char c = exe_file[i];\n"
"        path[out++] = (c == '/' || c == '\\\\') ? PRISMIO_PATH_SEP : c;\n"
"    }\n"
"    path[out] = '\\0';\n"
"    return path;\n"
"}\n"
"\n"
"int compiler_run_executable(const char* exe_file) {\n"
"    char* normalized = run_command_path(exe_file);\n"
"    if (!normalized) return 1;\n"
"\n"
"    char* q_exe = command_quote_arg(normalized);\n"
"    int command_len = (int)strlen(q_exe) + 8;\n"
"    char* command = (char*)malloc(command_len);\n"
"\n"
"    snprintf(command, command_len, \"%s\", q_exe);\n"
"    int result = run_build_command(command);\n"
"\n"
"    free(command);\n"
"    free(q_exe);\n"
"    free(normalized);\n"
"    return result;\n"
"}\n"
;

static const char prismio_embedded_ir_symbols_c[] =
"// ============================================================================\n"
"// Compiler symbol tables and ownership bookkeeping.\n"
"//\n"
"// These are the frontend's own data structures -- what a struct's fields are,\n"
"// which names are globals, what type each binding has, which values have been\n"
"// moved from or borrowed, and where break/continue jump to. None of it is\n"
"// backend state: it describes the program being compiled, not the IR being\n"
"// produced.\n"
"//\n"
"// It used to live in llvm-bridge.c purely because that was the only C file the\n"
"// frontend already talked to. That became a problem the moment a second backend\n"
"// existed: linking the LLVM C API backend left every one of these undefined,\n"
"// even though none of them have anything to do with emitting IR. They are\n"
"// shared here so both backends link against the same copy and neither owns it.\n"
"//\n"
"// Every table was previously a fixed array of char[64] that truncated names at\n"
"// 63 characters and silently stopped recording once full. Both were latent\n"
"// silent-wrong-answer bugs rather than theoretical ones: mangled overload\n"
"// symbols in this compiler's own source already reach 77 characters, so two\n"
"// overloads sharing a long prefix would have been recorded as the same symbol\n"
"// and one would have been given the other's return type -- with no diagnostic,\n"
"// at any point. Names are now interned at full length and every table grows,\n"
"// so neither failure mode exists.\n"
"// ============================================================================\n"
"\n"
"#include <stdio.h>\n"
"#include <stdlib.h>\n"
"#include <string.h>\n"
"\n"
"// The compiler cannot continue meaningfully past an allocation failure, and\n"
"// pretending otherwise is how the old silent truncation happened. Say what\n"
"// broke and stop.\n"
"static void symbols_oom(const char* what) {\n"
"    fprintf(stderr, \"internal error: out of memory growing %s\\n\", what);\n"
"    fflush(stderr);\n"
"    exit(1);\n"
"}\n"
"\n"
"static void* xmalloc(size_t n, const char* what) {\n"
"    void* p = malloc(n);\n"
"    if (!p) symbols_oom(what);\n"
"    return p;\n"
"}\n"
"\n"
"static void* xrealloc(void* p, size_t n, const char* what) {\n"
"    void* q = realloc(p, n);\n"
"    if (!q) symbols_oom(what);\n"
"    return q;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Name interning\n"
"//\n"
"// Every name the tables hold is stored once, at full length, and referred to by\n"
"// a canonical pointer. Two benefits: nothing is ever truncated, and a lookup\n"
"// compares pointers instead of running strcmp against every entry -- which\n"
"// matters because find_binding() is called once per identifier in the program\n"
"// and scans backwards over the whole binding table.\n"
"//\n"
"// Interned strings live for the life of the process. There is nothing to free:\n"
"// a compiler run ends when compilation does.\n"
"// ============================================================================\n"
"\n"
"#define INTERN_BUCKETS 4096\n"
"\n"
"typedef struct InternNode {\n"
"    struct InternNode* next;\n"
"    unsigned hash;\n"
"    char text[1]; // over-allocated to hold the whole name\n"
"} InternNode;\n"
"\n"
"static InternNode* intern_buckets[INTERN_BUCKETS];\n"
"\n"
"static unsigned hash_str(const char* s) {\n"
"    // FNV-1a. Cheap, and good enough for identifiers.\n"
"    unsigned h = 2166136261u;\n"
"    while (*s) {\n"
"        h ^= (unsigned char)*s++;\n"
"        h *= 16777619u;\n"
"    }\n"
"    return h;\n"
"}\n"
"\n"
"const char* ir_intern(const char* name) {\n"
"    if (!name) name = \"\";\n"
"\n"
"    unsigned h = hash_str(name);\n"
"    unsigned bucket = h & (INTERN_BUCKETS - 1);\n"
"\n"
"    for (InternNode* n = intern_buckets[bucket]; n; n = n->next) {\n"
"        if (n->hash == h && strcmp(n->text, name) == 0) return n->text;\n"
"    }\n"
"\n"
"    size_t len = strlen(name);\n"
"    InternNode* n = (InternNode*)xmalloc(sizeof(InternNode) + len, \"the name table\");\n"
"    n->hash = h;\n"
"    memcpy(n->text, name, len + 1);\n"
"    n->next = intern_buckets[bucket];\n"
"    intern_buckets[bucket] = n;\n"
"    return n->text;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Loop context stack -- break/continue targets, supports nesting\n"
"// ============================================================================\n"
"\n"
"#define MAX_LOOP_DEPTH 256\n"
"\n"
"static int loop_continue_stack[MAX_LOOP_DEPTH];\n"
"static int loop_break_stack[MAX_LOOP_DEPTH];\n"
"static int loop_depth = 0;\n"
"\n"
"void ir_loop_push(int continue_label, int break_label) {\n"
"    if (loop_depth >= MAX_LOOP_DEPTH) {\n"
"        fprintf(stderr, \"internal error: loops nested more than %d deep\\n\", MAX_LOOP_DEPTH);\n"
"        exit(1);\n"
"    }\n"
"    loop_continue_stack[loop_depth] = continue_label;\n"
"    loop_break_stack[loop_depth] = break_label;\n"
"    loop_depth++;\n"
"}\n"
"\n"
"void ir_loop_pop(void) {\n"
"    if (loop_depth > 0) loop_depth--;\n"
"}\n"
"\n"
"int ir_loop_continue_label(void) {\n"
"    return loop_depth > 0 ? loop_continue_stack[loop_depth - 1] : -1;\n"
"}\n"
"\n"
"int ir_loop_break_label(void) {\n"
"    return loop_depth > 0 ? loop_break_stack[loop_depth - 1] : -1;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// A growable list of interned names, shared by the several tables that are\n"
"// exactly that (globals, moved-from values, borrowed values).\n"
"// ============================================================================\n"
"\n"
"typedef struct {\n"
"    const char** items;\n"
"    int count;\n"
"    int capacity;\n"
"    const char* what; // named in the message if growing it fails\n"
"} NameList;\n"
"\n"
"static void namelist_add(NameList* list, const char* name) {\n"
"    if (list->count == list->capacity) {\n"
"        int next = list->capacity ? list->capacity * 2 : 64;\n"
"        list->items = (const char**)xrealloc(list->items, (size_t)next * sizeof(char*), list->what);\n"
"        list->capacity = next;\n"
"    }\n"
"    list->items[list->count++] = ir_intern(name);\n"
"}\n"
"\n"
"static int namelist_contains(const NameList* list, const char* name) {\n"
"    const char* interned = ir_intern(name);\n"
"    for (int i = 0; i < list->count; i++) {\n"
"        if (list->items[i] == interned) return 1;\n"
"    }\n"
"    return 0;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Global variable name registry\n"
"// ============================================================================\n"
"\n"
"static NameList global_names = { NULL, 0, 0, \"the global name table\" };\n"
"\n"
"void ir_register_global_name(const char* name) {\n"
"    if (namelist_contains(&global_names, name)) return;\n"
"    namelist_add(&global_names, name);\n"
"}\n"
"\n"
"int ir_is_global_name(const char* name) {\n"
"    return namelist_contains(&global_names, name);\n"
"}\n"
"\n"
"void ir_reset_globals(void) {\n"
"    global_names.count = 0;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Named type registry -- \"is this identifier a struct, an enum, or neither?\"\n"
"//\n"
"// Separate from the struct registry below, which holds field layouts and is\n"
"// populated by codegen. This one is filled by sema before checking begins and\n"
"// answers only the question a type annotation asks.\n"
"//\n"
"// It exists for speed. sema_annotation_type() used to answer by walking the\n"
"// whole module looking for a matching declaration, once per annotation -- and\n"
"// annotations are read for every parameter of every function, inside a loop over\n"
"// every function. On a 1600-function module that was the difference between\n"
"// quadratic and cubic.\n"
"// ============================================================================\n"
"\n"
"static NameList struct_type_names = { NULL, 0, 0, \"the struct name table\" };\n"
"static NameList enum_type_names = { NULL, 0, 0, \"the enum name table\" };\n"
"\n"
"// kind: 1 = struct, 2 = enum.\n"
"void ir_declare_named_type(const char* name, int kind) {\n"
"    NameList* list = (kind == 1) ? &struct_type_names : &enum_type_names;\n"
"    if (namelist_contains(list, name)) return;\n"
"    namelist_add(list, name);\n"
"}\n"
"\n"
"// 1 = struct, 2 = enum, 0 = not a declared type.\n"
"int ir_named_type_kind(const char* name) {\n"
"    if (namelist_contains(&struct_type_names, name)) return 1;\n"
"    if (namelist_contains(&enum_type_names, name)) return 2;\n"
"    return 0;\n"
"}\n"
"\n"
"void ir_reset_named_types(void) {\n"
"    struct_type_names.count = 0;\n"
"    enum_type_names.count = 0;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Struct / enum type registry\n"
"// ============================================================================\n"
"\n"
"typedef struct {\n"
"    const char* name;\n"
"    const char* type;\n"
"} FieldInfo;\n"
"\n"
"typedef struct {\n"
"    const char* name;\n"
"    FieldInfo* fields;\n"
"    int field_count;\n"
"    int field_capacity;\n"
"} StructInfo;\n"
"\n"
"static StructInfo* struct_infos = NULL;\n"
"static int struct_info_count = 0;\n"
"static int struct_info_capacity = 0;\n"
"\n"
"typedef struct {\n"
"    const char* enum_name;\n"
"    const char* variant_name;\n"
"    int value;\n"
"} EnumVariantInfo;\n"
"\n"
"static EnumVariantInfo* enum_variants = NULL;\n"
"static int enum_variant_count = 0;\n"
"static int enum_variant_capacity = 0;\n"
"\n"
"void ir_reset_types(void) {\n"
"    // The field arrays are kept, not freed: a reset is followed by another\n"
"    // module being compiled in the same process only during bootstrap, and\n"
"    // reusing the allocations is both simpler and correct.\n"
"    for (int i = 0; i < struct_info_count; i++) struct_infos[i].field_count = 0;\n"
"    struct_info_count = 0;\n"
"    enum_variant_count = 0;\n"
"}\n"
"\n"
"static StructInfo* find_struct(const char* name) {\n"
"    const char* interned = ir_intern(name);\n"
"    for (int i = 0; i < struct_info_count; i++) {\n"
"        if (struct_infos[i].name == interned) return &struct_infos[i];\n"
"    }\n"
"    return NULL;\n"
"}\n"
"\n"
"int ir_is_struct_type_name(const char* name) {\n"
"    return find_struct(name) != NULL;\n"
"}\n"
"\n"
"void ir_register_struct(const char* name) {\n"
"    if (find_struct(name)) return;\n"
"\n"
"    if (struct_info_count == struct_info_capacity) {\n"
"        int next = struct_info_capacity ? struct_info_capacity * 2 : 32;\n"
"        struct_infos = (StructInfo*)xrealloc(struct_infos, (size_t)next * sizeof(StructInfo),\n"
"                                             \"the struct table\");\n"
"        for (int i = struct_info_capacity; i < next; i++) {\n"
"            struct_infos[i].fields = NULL;\n"
"            struct_infos[i].field_count = 0;\n"
"            struct_infos[i].field_capacity = 0;\n"
"        }\n"
"        struct_info_capacity = next;\n"
"    }\n"
"\n"
"    struct_infos[struct_info_count].name = ir_intern(name);\n"
"    struct_infos[struct_info_count].field_count = 0;\n"
"    struct_info_count++;\n"
"}\n"
"\n"
"void ir_register_struct_field(const char* struct_name, const char* field_name, const char* field_type) {\n"
"    StructInfo* s = find_struct(struct_name);\n"
"    if (!s) return;\n"
"\n"
"    if (s->field_count == s->field_capacity) {\n"
"        int next = s->field_capacity ? s->field_capacity * 2 : 16;\n"
"        s->fields = (FieldInfo*)xrealloc(s->fields, (size_t)next * sizeof(FieldInfo),\n"
"                                         \"a struct's field table\");\n"
"        s->field_capacity = next;\n"
"    }\n"
"\n"
"    s->fields[s->field_count].name = ir_intern(field_name);\n"
"    s->fields[s->field_count].type = ir_intern(field_type);\n"
"    s->field_count++;\n"
"}\n"
"\n"
"int ir_get_struct_field_index(const char* struct_name, const char* field_name) {\n"
"    StructInfo* s = find_struct(struct_name);\n"
"    if (!s) return -1;\n"
"    const char* interned = ir_intern(field_name);\n"
"    for (int j = 0; j < s->field_count; j++) {\n"
"        if (s->fields[j].name == interned) return j;\n"
"    }\n"
"    return -1;\n"
"}\n"
"\n"
"const char* ir_get_struct_field_type(const char* struct_name, const char* field_name) {\n"
"    StructInfo* s = find_struct(struct_name);\n"
"    if (s) {\n"
"        const char* interned = ir_intern(field_name);\n"
"        for (int j = 0; j < s->field_count; j++) {\n"
"            if (s->fields[j].name == interned) return s->fields[j].type;\n"
"        }\n"
"    }\n"
"    return \"i32\";\n"
"}\n"
"\n"
"// Number of fields registered for a struct, so a backend can build the type\n"
"// body without knowing how the frontend stored it.\n"
"int ir_get_struct_field_count(const char* struct_name) {\n"
"    StructInfo* s = find_struct(struct_name);\n"
"    return s ? s->field_count : 0;\n"
"}\n"
"\n"
"const char* ir_get_struct_field_type_at(const char* struct_name, int index) {\n"
"    StructInfo* s = find_struct(struct_name);\n"
"    if (!s || index < 0 || index >= s->field_count) return \"i32\";\n"
"    return s->fields[index].type;\n"
"}\n"
"\n"
"void ir_register_enum_variant(const char* enum_name, const char* variant_name, int value) {\n"
"    if (enum_variant_count == enum_variant_capacity) {\n"
"        int next = enum_variant_capacity ? enum_variant_capacity * 2 : 128;\n"
"        enum_variants = (EnumVariantInfo*)xrealloc(enum_variants,\n"
"                                                   (size_t)next * sizeof(EnumVariantInfo),\n"
"                                                   \"the enum variant table\");\n"
"        enum_variant_capacity = next;\n"
"    }\n"
"\n"
"    enum_variants[enum_variant_count].enum_name = ir_intern(enum_name);\n"
"    enum_variants[enum_variant_count].variant_name = ir_intern(variant_name);\n"
"    enum_variants[enum_variant_count].value = value;\n"
"    enum_variant_count++;\n"
"}\n"
"\n"
"int ir_get_enum_variant(const char* enum_name, const char* variant_name) {\n"
"    const char* e = ir_intern(enum_name);\n"
"    const char* v = ir_intern(variant_name);\n"
"    for (int i = 0; i < enum_variant_count; i++) {\n"
"        if (enum_variants[i].enum_name == e && enum_variants[i].variant_name == v) {\n"
"            return enum_variants[i].value;\n"
"        }\n"
"    }\n"
"    return -1;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Variable type tracking\n"
"// ============================================================================\n"
"\n"
"// Bindings, innermost last.\n"
"//\n"
"// A block pushes a scope on entry and pops it on exit, which simply truncates\n"
"// the table back to where it started. Lookup scans backwards, so the innermost\n"
"// binding of a name wins and an outer one becomes visible again when the inner\n"
"// scope is popped. Before this existed the table was flat and cleared only per\n"
"// function, so a `let` inside an `if` stayed visible after the block ended.\n"
"//\n"
"// Each binding also carries its own slot name -- the identifier codegen uses for\n"
"// the alloca. Two `let x` in sibling blocks are two entries with two distinct\n"
"// slots, which is what stops them sharing one stack allocation sized by\n"
"// whichever appeared first (an i8 slot written with an 8-byte pointer, say).\n"
"//\n"
"// is_global distinguishes a module-level binding from a local, because codegen\n"
"// has to emit @name for one and %slot for the other. Asking a separate registry\n"
"// \"is this name a global?\" was wrong in the presence of shadowing: a local named\n"
"// the same as a global had its writes go to the local slot and its reads come\n"
"// from the global.\n"
"\n"
"#define MAX_SCOPES 1024\n"
"\n"
"typedef struct {\n"
"    const char* name;\n"
"    const char* type;\n"
"    const char* slot;\n"
"    int is_global;\n"
"    int is_mutable;\n"
"    // AIF Level 2: this binding's initialiser allocated a value whose escape\n"
"    // bottoms at the scope holding the binding, so the scope's exits are where\n"
"    // it is freed. Set by codegen from the tier; nothing here decides policy.\n"
"    int is_droppable;\n"
"    // AIF Level 4: which deallocator reclaims it. A list owns a second block --\n"
"    // its element array -- so a plain free on the handle leaks that block, and\n"
"    // the storage type cannot tell you: a list and a string are both `ptr`.\n"
"    int drop_kind;\n"
"} VarBinding;\n"
"\n"
"static VarBinding* var_bindings = NULL;\n"
"static int var_type_count = 0;\n"
"static int var_type_capacity = 0;\n"
"\n"
"static int scope_marks[MAX_SCOPES];\n"
"static int scope_depth = 0;\n"
"\n"
"// Monotonic across a whole module, so a slot name is unique no matter how many\n"
"// blocks declare the same identifier.\n"
"static int slot_serial = 0;\n"
"\n"
"void ir_scope_push(void) {\n"
"    if (scope_depth >= MAX_SCOPES) {\n"
"        fprintf(stderr, \"internal error: blocks nested more than %d deep\\n\", MAX_SCOPES);\n"
"        exit(1);\n"
"    }\n"
"    scope_marks[scope_depth] = var_type_count;\n"
"    scope_depth++;\n"
"}\n"
"\n"
"void ir_scope_pop(void) {\n"
"    if (scope_depth > 0) {\n"
"        scope_depth--;\n"
"        var_type_count = scope_marks[scope_depth];\n"
"    }\n"
"}\n"
"\n"
"// Loop barriers: the binding-table watermark on entry to each loop body.\n"
"//\n"
"// Move checking is per-name and runs over the AST in source order, so it sees a\n"
"// `drop(x)` inside a loop exactly once and concludes the value is consumed once\n"
"// -- while at run time the loop executes it repeatedly. That is a double free\n"
"// the checker could not see. A binding that predates the innermost loop is one\n"
"// the loop did not create, so moving out of it inside the loop is the case that\n"
"// actually repeats.\n"
"static int loop_barriers[MAX_LOOP_DEPTH];\n"
"static int loop_barrier_depth = 0;\n"
"\n"
"void ir_loop_barrier_push(void) {\n"
"    if (loop_barrier_depth < MAX_LOOP_DEPTH) loop_barriers[loop_barrier_depth++] = var_type_count;\n"
"}\n"
"\n"
"void ir_loop_barrier_pop(void) {\n"
"    if (loop_barrier_depth > 0) loop_barrier_depth--;\n"
"}\n"
"\n"
"static int find_binding(const char* name);\n"
"\n"
"// 1 when `name` is bound outside the innermost enclosing loop.\n"
"int ir_binding_predates_loop(const char* name) {\n"
"    if (loop_barrier_depth == 0) return 0;\n"
"    int i = find_binding(name);\n"
"    if (i < 0) return 0;\n"
"    return i < loop_barriers[loop_barrier_depth - 1] ? 1 : 0;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Scope drop lists (AIF Level 2)\n"
"//\n"
"// A drop list is not a separate structure: the binding table is already a flat\n"
"// array with a watermark per scope, so \"what dies when this scope exits\" is the\n"
"// droppable bindings above that watermark. The same read with a different floor\n"
"// answers it for a `return` (the whole function) and for `break`/`continue` (the\n"
"// loop barrier), which is why those two watermarks already existing matters.\n"
"//\n"
"// Enumeration is reverse construction order, which SPEC's RAII requires: a value\n"
"// may hold a reference to one constructed before it, never after.\n"
"//\n"
"// Whether a binding was *moved* is deliberately not consulted, here or by the\n"
"// caller: move state belongs to sema and is cleared per function before codegen\n"
"// starts. What would have needed it is carried by the facts instead -- see\n"
"// generate_scope_drops.\n"
"// ============================================================================\n"
"\n"
"void ir_mark_droppable(const char* name, int kind) {\n"
"    int i = find_binding(name);\n"
"    if (i >= 0) {\n"
"        var_bindings[i].is_droppable = 1;\n"
"        var_bindings[i].drop_kind = kind;\n"
"    }\n"
"}\n"
"\n"
"int ir_scope_drop_floor(void) {\n"
"    return scope_depth > 0 ? scope_marks[scope_depth - 1] : 0;\n"
"}\n"
"\n"
"// Its own stack rather than loop_barriers above: that one is sema's, pushed\n"
"// while move checking runs, and codegen is a separate walk. Sharing it would\n"
"// have made break/continue read a watermark of 0 and drop the whole function.\n"
"static int drop_barriers[MAX_LOOP_DEPTH];\n"
"static int barrier_regions[MAX_LOOP_DEPTH];\n"
"static int drop_barrier_depth = 0;\n"
"\n"
"// How many `region` blocks are open. A return has to close all of them and a\n"
"// break/continue those the loop did not open, for the same reason each has to\n"
"// run the drops: an arena still on the stack at function exit is never released.\n"
"static int region_depth = 0;\n"
"\n"
"void ir_region_enter(void) { region_depth++; }\n"
"void ir_region_exit(void)  { if (region_depth > 0) region_depth--; }\n"
"int  ir_region_depth(void) { return region_depth; }\n"
"\n"
"int ir_loop_region_depth(void) {\n"
"    return drop_barrier_depth > 0 ? barrier_regions[drop_barrier_depth - 1] : 0;\n"
"}\n"
"\n"
"void ir_drop_barrier_push(void) {\n"
"    if (drop_barrier_depth < MAX_LOOP_DEPTH) {\n"
"        barrier_regions[drop_barrier_depth] = region_depth;\n"
"        drop_barriers[drop_barrier_depth++] = var_type_count;\n"
"    }\n"
"}\n"
"\n"
"void ir_drop_barrier_pop(void) {\n"
"    if (drop_barrier_depth > 0) drop_barrier_depth--;\n"
"}\n"
"\n"
"int ir_loop_drop_floor(void) {\n"
"    return drop_barrier_depth > 0 ? drop_barriers[drop_barrier_depth - 1] : 0;\n"
"}\n"
"\n"
"int ir_drop_count(int floor) {\n"
"    if (floor < 0) floor = 0;\n"
"    int n = 0;\n"
"    for (int i = floor; i < var_type_count; i++) {\n"
"        if (var_bindings[i].is_droppable) n++;\n"
"    }\n"
"    return n;\n"
"}\n"
"\n"
"// The i-th droppable binding at or above `floor`, counting from the most\n"
"// recently constructed.\n"
"static int drop_index(int floor, int i) {\n"
"    if (floor < 0) floor = 0;\n"
"    int n = 0;\n"
"    for (int k = var_type_count - 1; k >= floor; k--) {\n"
"        if (!var_bindings[k].is_droppable) continue;\n"
"        if (n == i) return k;\n"
"        n++;\n"
"    }\n"
"    return -1;\n"
"}\n"
"\n"
"const char* ir_drop_slot(int floor, int i) {\n"
"    int k = drop_index(floor, i);\n"
"    return k >= 0 ? var_bindings[k].slot : \"\";\n"
"}\n"
"\n"
"const char* ir_drop_type(int floor, int i) {\n"
"    int k = drop_index(floor, i);\n"
"    return k >= 0 ? var_bindings[k].type : \"\";\n"
"}\n"
"\n"
"int ir_drop_kind(int floor, int i) {\n"
"    int k = drop_index(floor, i);\n"
"    return k >= 0 ? var_bindings[k].drop_kind : 0;\n"
"}\n"
"\n"
"static int find_binding(const char* name) {\n"
"    const char* interned = ir_intern(name);\n"
"    for (int i = var_type_count - 1; i >= 0; i--) {\n"
"        if (var_bindings[i].name == interned) return i;\n"
"    }\n"
"    return -1;\n"
"}\n"
"\n"
"static void add_binding(const char* name, const char* type, int is_global) {\n"
"    if (var_type_count == var_type_capacity) {\n"
"        int next = var_type_capacity ? var_type_capacity * 2 : 256;\n"
"        var_bindings = (VarBinding*)xrealloc(var_bindings, (size_t)next * sizeof(VarBinding),\n"
"                                             \"the binding table\");\n"
"        var_type_capacity = next;\n"
"    }\n"
"\n"
"    VarBinding* b = &var_bindings[var_type_count];\n"
"    b->name = ir_intern(name);\n"
"    b->type = ir_intern(type);\n"
"    b->is_global = is_global;\n"
"    b->is_mutable = 0;\n"
"    b->is_droppable = 0;\n"
"    b->drop_kind = 0;\n"
"\n"
"    if (is_global) {\n"
"        // Globals are addressed by their own name (@name), so no renaming.\n"
"        b->slot = b->name;\n"
"    } else {\n"
"        // '.' cannot appear in a Prismio identifier, so a slot name can never\n"
"        // collide with a user variable. Built at full length: truncating here\n"
"        // was how two long distinct names ended up sharing one stack slot.\n"
"        size_t len = strlen(b->name) + 24;\n"
"        char* slot = (char*)xmalloc(len, \"a slot name\");\n"
"        snprintf(slot, len, \"%s.%d\", b->name, slot_serial++);\n"
"        b->slot = ir_intern(slot);\n"
"        free(slot);\n"
"    }\n"
"\n"
"    var_type_count++;\n"
"}\n"
"\n"
"// Declares a binding in the current scope. Each call is a distinct binding, so\n"
"// re-declaring a name shadows rather than overwrites.\n"
"void ir_set_var_type(const char* name, const char* type) {\n"
"    add_binding(name, type, 0);\n"
"}\n"
"\n"
"void ir_set_global_var_type(const char* name, const char* type) {\n"
"    add_binding(name, type, 1);\n"
"}\n"
"\n"
"const char* ir_get_var_type(const char* name) {\n"
"    int i = find_binding(name);\n"
"    return i >= 0 ? var_bindings[i].type : \"i64\"; // default if unknown\n"
"}\n"
"\n"
"// The LLVM-level name for the innermost binding of `name`.\n"
"const char* ir_get_var_slot(const char* name) {\n"
"    int i = find_binding(name);\n"
"    return i >= 0 ? var_bindings[i].slot : name;\n"
"}\n"
"\n"
"// Whether the innermost binding of `name` is module-level. Shadowing-aware, so\n"
"// a local that happens to share a global's name reports 0.\n"
"int ir_var_is_global(const char* name) {\n"
"    int i = find_binding(name);\n"
"    return i >= 0 ? var_bindings[i].is_global : 0;\n"
"}\n"
"\n"
"int ir_has_var_type(const char* name) {\n"
"    return find_binding(name) >= 0;\n"
"}\n"
"\n"
"// `let mut` marks the binding just declared. Assignment to anything not so\n"
"// marked is rejected -- the parser has always recorded `mut`, but nothing read\n"
"// it, so explicit mutability was advertised and unenforced.\n"
"void ir_mark_mutable(const char* name) {\n"
"    int i = find_binding(name);\n"
"    if (i >= 0) var_bindings[i].is_mutable = 1;\n"
"}\n"
"\n"
"int ir_var_is_mutable(const char* name) {\n"
"    int i = find_binding(name);\n"
"    return i >= 0 ? var_bindings[i].is_mutable : 1; // unknown names error elsewhere\n"
"}\n"
"\n"
"void ir_clear_var_types(void) {\n"
"    var_type_count = 0;\n"
"    scope_depth = 0;\n"
"    slot_serial = 0;\n"
"}\n"
"\n"
"// Drops everything a function introduced, keeping module-level bindings and the\n"
"// $fn$ return-type keys. Scopes handle blocks; this handles the function\n"
"// boundary itself.\n"
"void ir_clear_local_var_types(void) {\n"
"    int write = 0;\n"
"    for (int read = 0; read < var_type_count; read++) {\n"
"        if (strncmp(var_bindings[read].name, \"$fn$\", 4) == 0 || var_bindings[read].is_global) {\n"
"            if (write != read) var_bindings[write] = var_bindings[read];\n"
"            write++;\n"
"        }\n"
"    }\n"
"    var_type_count = write;\n"
"    scope_depth = 0;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Move tracking (MVS): names of move-only values that have been moved-from\n"
"// ============================================================================\n"
"\n"
"static NameList moved_names = { NULL, 0, 0, \"the moved-value table\" };\n"
"\n"
"void ir_clear_moved(void) {\n"
"    moved_names.count = 0;\n"
"}\n"
"\n"
"int ir_is_moved(const char* name) {\n"
"    return namelist_contains(&moved_names, name);\n"
"}\n"
"\n"
"void ir_mark_moved(const char* name) {\n"
"    if (ir_is_moved(name)) return;\n"
"    namelist_add(&moved_names, name);\n"
"}\n"
"\n"
"// Moved-from state is tracked per name, but a `let` binds a *fresh* value to that\n"
"// name, so whatever was moved out of the previous binding no longer applies. Without\n"
"// this, reusing an ordinary name (`let t = ...` twice in one function, in different\n"
"// branches) makes every use after the first move a spurious \"use of moved value\".\n"
"void ir_unmark_moved(const char* name) {\n"
"    const char* interned = ir_intern(name);\n"
"    for (int i = 0; i < moved_names.count; i++) {\n"
"        if (moved_names.items[i] == interned) {\n"
"            for (int j = i; j < moved_names.count - 1; j++) {\n"
"                moved_names.items[j] = moved_names.items[j + 1];\n"
"            }\n"
"            moved_names.count--;\n"
"            return;\n"
"        }\n"
"    }\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Borrow tracking (MVS): names bound to non-owning (let/inout) parameters\n"
"// ============================================================================\n"
"\n"
"static NameList borrowed_names = { NULL, 0, 0, \"the borrowed-value table\" };\n"
"\n"
"void ir_clear_borrowed(void) {\n"
"    borrowed_names.count = 0;\n"
"}\n"
"\n"
"int ir_is_borrowed(const char* name) {\n"
"    return namelist_contains(&borrowed_names, name);\n"
"}\n"
"\n"
"void ir_mark_borrowed(const char* name) {\n"
"    if (ir_is_borrowed(name)) return;\n"
"    namelist_add(&borrowed_names, name);\n"
"}\n"
"\n"
"// Same reason ir_unmark_moved exists. A `let` binds a fresh value, and AIF Level\n"
"// 4 made borrowing something a `let` can do -- `let p = node.child1` reborrows\n"
"// the field -- so a name that reborrowed once and owns the next time must not\n"
"// keep the first answer.\n"
"void ir_unmark_borrowed(const char* name) {\n"
"    const char* interned = ir_intern(name);\n"
"    for (int i = 0; i < borrowed_names.count; i++) {\n"
"        if (borrowed_names.items[i] == interned) {\n"
"            for (int j = i; j < borrowed_names.count - 1; j++) {\n"
"                borrowed_names.items[j] = borrowed_names.items[j + 1];\n"
"            }\n"
"            borrowed_names.count--;\n"
"            return;\n"
"        }\n"
"    }\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Return tracking\n"
"//\n"
"// Set when a block has emitted its terminator, so the caller knows not to emit\n"
"// a fall-through branch. break/continue reuse it for the same purpose.\n"
"// ============================================================================\n"
"\n"
"static int has_returned = 0;\n"
"\n"
"void ir_set_returned(void) {\n"
"    has_returned = 1;\n"
"}\n"
"\n"
"int ir_has_returned(void) {\n"
"    return has_returned;\n"
"}\n"
"\n"
"void ir_clear_returned(void) {\n"
"    has_returned = 0;\n"
"}\n"
;

static const char prismio_embedded_aif_support_c[] =
"// ============================================================================\n"
"// AIF \342\200\224 the inference engine's data structures and fixed point.\n"
"//\n"
"// AIF (aif/) is Prismio's memory model. The engine assigns every allocation\n"
"// site a tier T0-T4 from four inferred fact domains, and this file holds\n"
"// everything iteration needs: the scope forest, the site table, the points-to\n"
"// graph, the constraint list, and the solver loop itself.\n"
"//\n"
"// WHY THIS IS IN C. The policy lives in src/aif.psm -- which nodes become\n"
"// sites, which transfer rule fires where, what an extern's ownership contract\n"
"// is, how a tier becomes a manifest line. None of that is here. What is here is\n"
"// the container layer: growable bitsets, an interning table, and a hash map\n"
"// from key tuples to ids. Prismio has no generics, no maps and no growable\n"
"// vectors (aif/implementation/COMPILER-AUDIT.md 4.3 calls this the finding that\n"
"// most changes the schedule), so the engine would otherwise be written with\n"
"// parallel arrays and integer indices -- in the one component where a silent\n"
"// bug yields a wrong-tier binary rather than a crash.\n"
"//\n"
"// This is the same split ir_symbols.c already makes for the symbol tables, and\n"
"// it is deliberate rather than expedient: the compiler is written in Prismio,\n"
"// its containers are written in C.\n"
"//\n"
"// SOUNDNESS NOTE. Every fact here only ever *rises* (INFERENCE.md M2). No\n"
"// operation in this file lowers E, A or C, which is what makes the iteration\n"
"// monotone, terminating, and safe to abandon -- see aif_widen().\n"
"// ============================================================================\n"
"\n"
"#include <stdio.h>\n"
"#include <stdint.h>\n"
"#include <stdlib.h>\n"
"#include <string.h>\n"
"\n"
"static void aif_oom(const char* what) {\n"
"    fprintf(stderr, \"internal error: out of memory growing %s\\n\", what);\n"
"    fflush(stderr);\n"
"    exit(1);\n"
"}\n"
"\n"
"static void* xmalloc(size_t n, const char* what) {\n"
"    void* p = malloc(n);\n"
"    if (!p) aif_oom(what);\n"
"    return p;\n"
"}\n"
"\n"
"static void* xcalloc(size_t n, size_t sz, const char* what) {\n"
"    void* p = calloc(n ? n : 1, sz);\n"
"    if (!p) aif_oom(what);\n"
"    return p;\n"
"}\n"
"\n"
"static void* xrealloc(void* p, size_t n, const char* what) {\n"
"    void* q = realloc(p, n);\n"
"    if (!q) aif_oom(what);\n"
"    return q;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Fact encodings\n"
"//\n"
"// Escape is a single int so that it fits an array slot and a Prismio `Int`\n"
"// alike: the two top elements are negative, and every Region(s) is the scope id\n"
"// itself. The ordering Region(s) < Caller < Global is not the integer ordering\n"
"// -- escape_join() implements it.\n"
"// ============================================================================\n"
"\n"
"#define AIF_E_GLOBAL (-2)\n"
"#define AIF_E_CALLER (-1)\n"
"\n"
"#define AIF_A_UNIQUE   0\n"
"#define AIF_A_BORROWED 1\n"
"#define AIF_A_SHARED   2\n"
"\n"
"#define AIF_C_ACYCLIC 0\n"
"#define AIF_C_MAYBE   1\n"
"\n"
"// Site kinds. Mirrors what src/aif.psm classifies a type as; the solver only\n"
"// cares that kind 0 is a struct (the T0 clause and the copy rule both test it).\n"
"// LAYOUT 4. Assumed trip count of a loop with no profile, and the one estimator\n"
"// both static profiles share -- arena placement's allocs_in(s) and the layout\n"
"// search's access counts. One definition, so they cannot drift apart.\n"
"#define AIF_LOOP_ITERS      16\n"
"\n"
"#define AIF_K_STRUCT 0\n"
"#define AIF_K_STRING 1\n"
"#define AIF_K_ARRAY  2\n"
"#define AIF_K_LIST   3\n"
"#define AIF_K_OPAQUE 4\n"
"\n"
"// ============================================================================\n"
"// Growable bitsets\n"
"//\n"
"// Both halves of the solver state are sets of small integers: a points-to node\n"
"// holds a set of sites, and a site holds the set of nodes referencing it.\n"
"// Bitsets make union and subset one word-loop each, which keeps the round cost\n"
"// proportional to the graph rather than to the constraint list.\n"
"// ============================================================================\n"
"\n"
"typedef unsigned long long Word;\n"
"#define WORD_BITS 64\n"
"\n"
"typedef struct {\n"
"    Word* w;\n"
"    int nwords;\n"
"} Bits;\n"
"\n"
"static void bits_ensure(Bits* b, int bit, const char* what) {\n"
"    int need = bit / WORD_BITS + 1;\n"
"    if (need <= b->nwords) return;\n"
"    int grow = b->nwords ? b->nwords * 2 : 8;\n"
"    if (grow < need) grow = need;\n"
"    b->w = (Word*)xrealloc(b->w, (size_t)grow * sizeof(Word), what);\n"
"    memset(b->w + b->nwords, 0, (size_t)(grow - b->nwords) * sizeof(Word));\n"
"    b->nwords = grow;\n"
"}\n"
"\n"
"static int bits_test(const Bits* b, int bit) {\n"
"    int wi = bit / WORD_BITS;\n"
"    if (bit < 0 || wi >= b->nwords) return 0;\n"
"    return (int)((b->w[wi] >> (bit % WORD_BITS)) & 1u);\n"
"}\n"
"\n"
"// Returns 1 only when the bit was absent. The solver's `changed` flag is the\n"
"// disjunction of every such return, so an update that adds nothing must report\n"
"// nothing -- otherwise the loop never terminates.\n"
"static int bits_set(Bits* b, int bit, const char* what) {\n"
"    bits_ensure(b, bit, what);\n"
"    int wi = bit / WORD_BITS;\n"
"    Word m = (Word)1 << (bit % WORD_BITS);\n"
"    if (b->w[wi] & m) return 0;\n"
"    b->w[wi] |= m;\n"
"    return 1;\n"
"}\n"
"\n"
"static void bits_clear(Bits* b) {\n"
"    if (b->nwords) memset(b->w, 0, (size_t)b->nwords * sizeof(Word));\n"
"}\n"
"\n"
"// dst |= src, reporting whether dst grew.\n"
"static int bits_or(Bits* dst, const Bits* src, const char* what) {\n"
"    int changed = 0;\n"
"    for (int i = 0; i < src->nwords; i++) {\n"
"        if (!src->w[i]) continue;\n"
"        bits_ensure(dst, i * WORD_BITS, what);\n"
"        Word before = dst->w[i];\n"
"        Word after = before | src->w[i];\n"
"        if (after != before) {\n"
"            dst->w[i] = after;\n"
"            changed = 1;\n"
"        }\n"
"    }\n"
"    return changed;\n"
"}\n"
"\n"
"static int bits_count_at_least_two(const Bits* b) {\n"
"    int seen = 0;\n"
"    for (int i = 0; i < b->nwords; i++) {\n"
"        Word x = b->w[i];\n"
"        while (x) {\n"
"            x &= x - 1;\n"
"            if (++seen >= 2) return 1;\n"
"        }\n"
"    }\n"
"    return 0;\n"
"}\n"
"\n"
"static void bits_free(Bits* b) {\n"
"    free(b->w);\n"
"    b->w = NULL;\n"
"    b->nwords = 0;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Int vectors\n"
"//\n"
"// Set membership is a bitset, but the solver's rules need to *enumerate* a set,\n"
"// sometimes two of them nested. Materialising a bitset into a plain int array\n"
"// keeps that a pair of ordinary loops. The buffers are reused across rounds,\n"
"// so this allocates a handful of times for the whole run.\n"
"// ============================================================================\n"
"\n"
"typedef struct {\n"
"    int* v;\n"
"    int len, cap;\n"
"} IntVec;\n"
"\n"
"static void vec_push(IntVec* iv, int x, const char* what) {\n"
"    if (iv->len == iv->cap) {\n"
"        iv->cap = iv->cap ? iv->cap * 2 : 64;\n"
"        iv->v = (int*)xrealloc(iv->v, (size_t)iv->cap * sizeof(int), what);\n"
"    }\n"
"    iv->v[iv->len++] = x;\n"
"}\n"
"\n"
"// Portable count-trailing-zeros. A branchless intrinsic exists on every\n"
"// compiler that matters and on none of them by the same name, and this runs\n"
"// once per set bit rather than once per word, so a six-step binary search costs\n"
"// nothing measurable next to the round it sits inside.\n"
"static int ctz64(Word x) {\n"
"    int n = 0;\n"
"    if (!(x & 0xFFFFFFFFull)) { x >>= 32; n += 32; }\n"
"    if (!(x & 0xFFFFull))     { x >>= 16; n += 16; }\n"
"    if (!(x & 0xFFull))       { x >>= 8;  n += 8;  }\n"
"    if (!(x & 0xFull))        { x >>= 4;  n += 4;  }\n"
"    if (!(x & 0x3ull))        { x >>= 2;  n += 2;  }\n"
"    if (!(x & 0x1ull))        { n += 1; }\n"
"    return n;\n"
"}\n"
"\n"
"static void bits_to_vec(const Bits* b, IntVec* out) {\n"
"    out->len = 0;\n"
"    for (int wi = 0; wi < b->nwords; wi++) {\n"
"        for (Word x = b->w[wi]; x; x &= x - 1) {\n"
"            vec_push(out, wi * WORD_BITS + ctz64(x), \"AIF bit enumeration\");\n"
"        }\n"
"    }\n"
"}\n"
"\n"
"// ============================================================================\n"
"// String interning\n"
"//\n"
"// Type names, field names and variable names all become integer ids, because\n"
"// every key in the points-to graph is a tuple of small integers and comparing\n"
"// tuples of ints is what makes the key map cheap. Id 0 is always \"\".\n"
"// ============================================================================\n"
"\n"
"#define AIF_INTERN_BUCKETS 8192\n"
"\n"
"typedef struct InternNode {\n"
"    struct InternNode* next;\n"
"    unsigned hash;\n"
"    int id;\n"
"    char text[1];   // over-allocated to hold the whole name\n"
"} InternNode;\n"
"\n"
"static InternNode* intern_buckets[AIF_INTERN_BUCKETS];\n"
"static const char** intern_by_id;\n"
"static int intern_count, intern_cap;\n"
"\n"
"static unsigned hash_str(const char* s) {\n"
"    unsigned h = 2166136261u;   // FNV-1a\n"
"    while (*s) {\n"
"        h ^= (unsigned char)*s++;\n"
"        h *= 16777619u;\n"
"    }\n"
"    return h;\n"
"}\n"
"\n"
"int aif_intern(const char* s) {\n"
"    if (!s) s = \"\";\n"
"    unsigned h = hash_str(s);\n"
"    unsigned bucket = h & (AIF_INTERN_BUCKETS - 1);\n"
"\n"
"    for (InternNode* n = intern_buckets[bucket]; n; n = n->next) {\n"
"        if (n->hash == h && strcmp(n->text, s) == 0) return n->id;\n"
"    }\n"
"\n"
"    size_t len = strlen(s);\n"
"    InternNode* n = (InternNode*)xmalloc(sizeof(InternNode) + len, \"AIF interned names\");\n"
"    memcpy(n->text, s, len + 1);\n"
"    n->hash = h;\n"
"    n->next = intern_buckets[bucket];\n"
"    intern_buckets[bucket] = n;\n"
"\n"
"    if (intern_count == intern_cap) {\n"
"        intern_cap = intern_cap ? intern_cap * 2 : 256;\n"
"        intern_by_id = (const char**)xrealloc(intern_by_id,\n"
"            (size_t)intern_cap * sizeof(char*), \"AIF name index\");\n"
"    }\n"
"    n->id = intern_count;\n"
"    intern_by_id[intern_count++] = n->text;\n"
"    return n->id;\n"
"}\n"
"\n"
"const char* aif_str(int id) {\n"
"    if (id < 0 || id >= intern_count) return \"\";\n"
"    return intern_by_id[id];\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Scope forest\n"
"//\n"
"// Each function body is a root; a block nests inside its parent. The join of\n"
"// two Region values is their least common ancestor, which exists because scopes\n"
"// nest (INFERENCE 2.1). Scopes in different functions have no common region --\n"
"// scope_lca reports -1 and escape_join falls back to Caller.\n"
"// ============================================================================\n"
"\n"
"typedef struct {\n"
"    int parent;\n"
"    int depth;\n"
"    int owner;      // function id\n"
"    // SPEC 5.2. -1 unless a `region` statement opened this scope, in which case\n"
"    // it is the interned name -- which is what the manifest's `region:<name>`\n"
"    // placement reports, and how codegen knows an arena is live here.\n"
"    int region_name;\n"
"    // LAYOUT 7.1. Set by aif_place_arenas when the cost model chooses this scope,\n"
"    // or unconditionally when `region` pinned it. Codegen reads it through the\n"
"    // block node to know where to bracket arena_push/arena_pop.\n"
"    int arena;\n"
"    // How many loops enclose this scope, within its function. The weight a site\n"
"    // contributes to its arena's benefit is one allocation per entry of the\n"
"    // arena, times the trip count of every loop between them.\n"
"    int loop_depth;\n"
"    const void* node;   // the BLOCK this scope came from, for the codegen lookup\n"
"    // REQUIREMENTS 19. A byte cap asserted by `region name pin(N)`, or 0. The\n"
"    // span travels with it so a refuted budget can underline the annotation\n"
"    // rather than the block.\n"
"    long budget;\n"
"    int budget_file, budget_line, budget_col;\n"
"} Scope;\n"
"\n"
"static Scope* scopes;\n"
"static int scope_count, scope_cap;\n"
"\n"
"int aif_scope_new(int parent, int owner) {\n"
"    if (scope_count == scope_cap) {\n"
"        scope_cap = scope_cap ? scope_cap * 2 : 256;\n"
"        scopes = (Scope*)xrealloc(scopes, (size_t)scope_cap * sizeof(Scope), \"AIF scopes\");\n"
"    }\n"
"    Scope* s = &scopes[scope_count];\n"
"    s->parent = parent;\n"
"    s->owner = owner;\n"
"    s->depth = (parent < 0) ? 0 : scopes[parent].depth + 1;\n"
"    s->region_name = -1;\n"
"    s->arena = 0;\n"
"    s->loop_depth = 0;\n"
"    s->node = NULL;\n"
"    s->budget = 0;\n"
"    s->budget_file = s->budget_line = s->budget_col = 0;\n"
"    return scope_count++;\n"
"}\n"
"\n"
"void aif_scope_set_budget(int scope, int bytes, int file, int line, int col) {\n"
"    if (scope < 0 || scope >= scope_count) return;\n"
"    scopes[scope].budget = bytes;\n"
"    scopes[scope].budget_file = file;\n"
"    scopes[scope].budget_line = line;\n"
"    scopes[scope].budget_col = col;\n"
"}\n"
"\n"
"void aif_scope_set_region(int scope, const char* name) {\n"
"    if (scope < 0 || scope >= scope_count) return;\n"
"    scopes[scope].region_name = aif_intern(name);\n"
"    // SPEC 5.2: `region` is a pin on the placement decision, not an input to it.\n"
"    // The cost model never sees this scope -- it is guaranteed an arena whether\n"
"    // or not the model would have chosen one, and the manifest records that.\n"
"    scopes[scope].arena = 1;\n"
"}\n"
"\n"
"void aif_scope_set_loop_depth(int scope, int depth) {\n"
"    if (scope < 0 || scope >= scope_count) return;\n"
"    scopes[scope].loop_depth = depth < 0 ? 0 : depth;\n"
"}\n"
"\n"
"void aif_scope_note_node(int scope, const void* node) {\n"
"    if (scope < 0 || scope >= scope_count) return;\n"
"    scopes[scope].node = node;\n"
"}\n"
"\n"
"int aif_scope_count(void) { return scope_count; }\n"
"\n"
"static int scope_lca(int a, int b) {\n"
"    if (a < 0 || b < 0 || a >= scope_count || b >= scope_count) return -1;\n"
"    if (scopes[a].owner != scopes[b].owner) return -1;\n"
"    while (scopes[a].depth > scopes[b].depth) a = scopes[a].parent;\n"
"    while (scopes[b].depth > scopes[a].depth) b = scopes[b].parent;\n"
"    while (a != b) {\n"
"        a = scopes[a].parent;\n"
"        b = scopes[b].parent;\n"
"        if (a < 0 || b < 0) return -1;\n"
"    }\n"
"    return a;\n"
"}\n"
"\n"
"// Least upper bound on Region(s) < Caller < Global.\n"
"static int escape_join(int x, int y) {\n"
"    if (x == AIF_E_GLOBAL || y == AIF_E_GLOBAL) return AIF_E_GLOBAL;\n"
"    if (x == AIF_E_CALLER || y == AIF_E_CALLER) return AIF_E_CALLER;\n"
"    int m = scope_lca(x, y);\n"
"    return (m < 0) ? AIF_E_CALLER : m;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Functions\n"
"// ============================================================================\n"
"\n"
"typedef struct {\n"
"    int symbol;     // interned mangled symbol -- the identity\n"
"    int name;       // interned plain name\n"
"    int file;\n"
"    int sealed;     // no visible body: analysed like an FFI call (PIR 5)\n"
"    int nsites;     // running count, so each site gets a stable ordinal\n"
"} Fn;\n"
"\n"
"static Fn* fns;\n"
"static int fn_count, fn_cap;\n"
"\n"
"// Interned symbol id -> function id, -1 where the string is not a function\n"
"// symbol. Sparse and grown on demand, which beats a second hash table.\n"
"static int* fn_by_symbol;\n"
"static int fn_by_symbol_cap;\n"
"\n"
"static void fn_index_put(int symbol, int fid) {\n"
"    if (symbol >= fn_by_symbol_cap) {\n"
"        int grow = fn_by_symbol_cap ? fn_by_symbol_cap * 2 : 1024;\n"
"        if (grow <= symbol) grow = symbol + 1;\n"
"        fn_by_symbol = (int*)xrealloc(fn_by_symbol, (size_t)grow * sizeof(int),\n"
"                                      \"AIF function index\");\n"
"        for (int i = fn_by_symbol_cap; i < grow; i++) fn_by_symbol[i] = -1;\n"
"        fn_by_symbol_cap = grow;\n"
"    }\n"
"    fn_by_symbol[symbol] = fid;\n"
"}\n"
"\n"
"int aif_fn_new(const char* symbol, const char* name, int file) {\n"
"    int sym = aif_intern(symbol);\n"
"    if (sym < fn_by_symbol_cap && fn_by_symbol[sym] >= 0) return fn_by_symbol[sym];\n"
"\n"
"    if (fn_count == fn_cap) {\n"
"        fn_cap = fn_cap ? fn_cap * 2 : 256;\n"
"        fns = (Fn*)xrealloc(fns, (size_t)fn_cap * sizeof(Fn), \"AIF functions\");\n"
"    }\n"
"    Fn* f = &fns[fn_count];\n"
"    f->symbol = sym;\n"
"    f->name = aif_intern(name);\n"
"    f->file = file;\n"
"    f->sealed = 0;\n"
"    f->nsites = 0;\n"
"    fn_index_put(sym, fn_count);\n"
"    return fn_count++;\n"
"}\n"
"\n"
"int aif_fn_lookup(const char* symbol) {\n"
"    int sym = aif_intern(symbol);\n"
"    if (sym >= fn_by_symbol_cap) return -1;\n"
"    return fn_by_symbol[sym];\n"
"}\n"
"\n"
"int aif_fn_count(void) { return fn_count; }\n"
"const char* aif_fn_symbol(int f) { return (f < 0 || f >= fn_count) ? \"\" : aif_str(fns[f].symbol); }\n"
"const char* aif_fn_name(int f)   { return (f < 0 || f >= fn_count) ? \"\" : aif_str(fns[f].name); }\n"
"int aif_fn_file(int f)           { return (f < 0 || f >= fn_count) ? 0 : fns[f].file; }\n"
"void aif_fn_seal(int f)          { if (f >= 0 && f < fn_count) fns[f].sealed = 1; }\n"
"int aif_fn_is_sealed(int f)      { return (f < 0 || f >= fn_count) ? 0 : fns[f].sealed; }\n"
"\n"
"// ============================================================================\n"
"// Nominal types\n"
"//\n"
"// Structs carry a field count (the T0/T1 size proxy -- see aif_tier_of) and an\n"
"// edge set for the type reference graph. Enums are recorded only so the\n"
"// frontend can exclude them: an enum is an i32 and participates in no memory\n"
"// model.\n"
"// ============================================================================\n"
"\n"
"typedef struct {\n"
"    int name;\n"
"    int nfields;\n"
"    int bytes;          // 0 until the frontend computes a layout for it\n"
"    int is_enum;\n"
"    Bits reaches;       // direct edges, then closed transitively\n"
"    int acyclic;\n"
"    // LAYOUT 7.2. The fields themselves, in declaration order, plus the access\n"
"    // profile over them and the permutation the search chose.\n"
"    int* field_name;    // interned\n"
"    // The field's *declared* type, base-named. Struct-field ownership compares\n"
"    // it against what the sites say is in the slot: this compiler puns an\n"
"    // ASTNode pointer as `String`, and a release chosen from the sites alone\n"
"    // would emit a call to __aif_release_String.\n"
"    int* field_type;\n"
"    int* field_bytes;   // width, from the frontend -- it knows the lowering\n"
"    long long* field_acc;\n"
"    int* order;         // order[i] is the declaration index placed i-th\n"
"    int field_cap;\n"
"    int reordered;\n"
"} Nominal;\n"
"\n"
"static Nominal* nominals;\n"
"static int nominal_count, nominal_cap;\n"
"static int* nominal_by_name;\n"
"static int nominal_by_name_cap;\n"
"\n"
"static void nominal_index_put(int name, int id) {\n"
"    if (name >= nominal_by_name_cap) {\n"
"        int grow = nominal_by_name_cap ? nominal_by_name_cap * 2 : 1024;\n"
"        if (grow <= name) grow = name + 1;\n"
"        nominal_by_name = (int*)xrealloc(nominal_by_name, (size_t)grow * sizeof(int),\n"
"                                         \"AIF type index\");\n"
"        for (int i = nominal_by_name_cap; i < grow; i++) nominal_by_name[i] = -1;\n"
"        nominal_by_name_cap = grow;\n"
"    }\n"
"    nominal_by_name[name] = id;\n"
"}\n"
"\n"
"static int nominal_find_id(int name) {\n"
"    if (name < 0 || name >= nominal_by_name_cap) return -1;\n"
"    return nominal_by_name[name];\n"
"}\n"
"\n"
"static int nominal_find(const char* name) {\n"
"    return nominal_find_id(aif_intern(name));\n"
"}\n"
"\n"
"static int nominal_intern(const char* name, int is_enum) {\n"
"    int existing = nominal_find(name);\n"
"    if (existing >= 0) return existing;\n"
"\n"
"    if (nominal_count == nominal_cap) {\n"
"        nominal_cap = nominal_cap ? nominal_cap * 2 : 64;\n"
"        nominals = (Nominal*)xrealloc(nominals, (size_t)nominal_cap * sizeof(Nominal),\n"
"                                      \"AIF nominal types\");\n"
"    }\n"
"    Nominal* t = &nominals[nominal_count];\n"
"    t->name = aif_intern(name);\n"
"    t->nfields = 0;\n"
"    t->bytes = 0;\n"
"    t->is_enum = is_enum;\n"
"    t->reaches.w = NULL;\n"
"    t->reaches.nwords = 0;\n"
"    t->acyclic = 1;\n"
"    t->field_name = NULL;\n"
"    t->field_type = NULL;\n"
"    t->field_bytes = NULL;\n"
"    t->field_acc = NULL;\n"
"    t->order = NULL;\n"
"    t->field_cap = 0;\n"
"    t->reordered = 0;\n"
"    nominal_index_put(t->name, nominal_count);\n"
"    return nominal_count++;\n"
"}\n"
"\n"
"void aif_struct_new(const char* name) { nominal_intern(name, 0); }\n"
"void aif_enum_new(const char* name)   { nominal_intern(name, 1); }\n"
"\n"
"int aif_is_struct(const char* name) {\n"
"    int id = nominal_find(name);\n"
"    return (id >= 0 && !nominals[id].is_enum) ? 1 : 0;\n"
"}\n"
"\n"
"int aif_is_enum(const char* name) {\n"
"    int id = nominal_find(name);\n"
"    return (id >= 0 && nominals[id].is_enum) ? 1 : 0;\n"
"}\n"
"\n"
"int aif_struct_nfields(const char* name) {\n"
"    int id = nominal_find(name);\n"
"    return (id >= 0) ? nominals[id].nfields : 0;\n"
"}\n"
"\n"
"void aif_struct_add_field(const char* name, const char* field, const char* type, int bytes) {\n"
"    Nominal* t = &nominals[nominal_intern(name, 0)];\n"
"    if (t->nfields == t->field_cap) {\n"
"        int grow = t->field_cap ? t->field_cap * 2 : 8;\n"
"        t->field_name  = (int*)xrealloc(t->field_name,  (size_t)grow * sizeof(int), \"AIF fields\");\n"
"        t->field_type  = (int*)xrealloc(t->field_type,  (size_t)grow * sizeof(int), \"AIF field types\");\n"
"        t->field_bytes = (int*)xrealloc(t->field_bytes, (size_t)grow * sizeof(int), \"AIF field widths\");\n"
"        t->field_acc = (long long*)xrealloc(t->field_acc,\n"
"                                           (size_t)grow * sizeof(long long), \"AIF field accesses\");\n"
"        t->order = (int*)xrealloc(t->order, (size_t)grow * sizeof(int), \"AIF field order\");\n"
"        t->field_cap = grow;\n"
"    }\n"
"    int i = t->nfields++;\n"
"    t->field_name[i] = aif_intern(field);\n"
"    t->field_type[i] = aif_intern(type);\n"
"    t->field_bytes[i] = bytes;\n"
"    t->field_acc[i] = 0;\n"
"    t->order[i] = i;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// The access profile (LAYOUT 2.1) and layout selection (LAYOUT 7.2)\n"
"//\n"
"// LAYOUT 2 wants the profile measured, by running a declared `workload` under\n"
"// instrumentation. There is no workload runner, so this is the static estimate\n"
"// LAYOUT 10.4 names as the fallback -- one count per syntactic access, weighted\n"
"// by AIF_LOOP_ITERS per enclosing loop, which is exactly how automatic arena\n"
"// placement estimates allocs_in(s). Same estimator, same known crudeness, and\n"
"// the same property that matters: it is deterministic and needs no profile file.\n"
"//\n"
"// **Only one candidate dimension is searched, and the rest is not caution.**\n"
"// LAYOUT 6's table lists grouping (AoS/SoA), a hot/cold split, field order,\n"
"// bit-packing and handle width. Field order is the only one this compiler can\n"
"// *emit*: SoA and a hot/cold split both make one logical object several\n"
"// allocations, so a field reference stops being `getelementptr` on a pointer and\n"
"// becomes a base plus an index -- which is 1's finding 6, handles, rated as\n"
"// touching every layer. Bit-packing needs a mask and a shift at every access.\n"
"// Choosing a layout codegen cannot produce would be a manifest that describes a\n"
"// binary nobody built.\n"
"// ============================================================================\n"
"\n"
"void aif_field_access(const char* type, const char* field, int loops) {\n"
"    int id = nominal_find(type);\n"
"    if (id < 0) return;\n"
"    Nominal* t = &nominals[id];\n"
"    int f = aif_intern(field);\n"
"    long long weight = 1;\n"
"    if (loops > 6) loops = 6;       // capped as weight_of caps it, and for the same reason\n"
"    for (int i = 0; i < loops; i++) weight *= AIF_LOOP_ITERS;\n"
"    for (int i = 0; i < t->nfields; i++) {\n"
"        if (t->field_name[i] == f) { t->field_acc[i] += weight; return; }\n"
"    }\n"
"}\n"
"\n"
"// **The first field never moves, and this is not a tuning choice.**\n"
"//\n"
"// The compiler puns a struct pointer as `String` and spells \"this slot is empty\"\n"
"// as `str_equals(ptr, \"\")`, which reads the *first byte of the pointed-to\n"
"// struct*. That is why NodeKind and TypeKind both reserve ordinal 0: a live node\n"
"// whose first field is zero is byte-for-byte an empty slot, and every\n"
"// node_exists in the compiler rests on it (tests/test_41_punned_slot_bytes.psm).\n"
"//\n"
"// Sorting by width puts an 8-byte pointer at offset 0, and a pointer to \"\" has a\n"
"// zero first byte -- so every live node with an empty `s1` began reading as\n"
"// absent. The generation built by the first compiler that did this could not\n"
"// parse its own source. SPEC 8.2 grants the compiler layout freedom; this\n"
"// implementation's representation of \"absent\" spends the first field of it, and\n"
"// the search has to know that rather than rediscover it.\n"
"// **Descending width alone is wrong here, and measurement is what says so.**\n"
"//\n"
"// LAYOUT 6 derives field order as a sort -- descending frequency, then descending\n"
"// alignment -- and a sort is optimal for padding only when placement starts at\n"
"// offset 0 with nothing fixed. The pinned first field breaks that: pinning a\n"
"// 4-byte `kind` leaves a 4-byte hole that only a narrow field can fill, and a\n"
"// width sort puts the widest field next and pays the padding. Measured on the\n"
"// corpus, sorting made `Health` 16 bytes -> 24 and `Sprite` 40 -> 48. It made\n"
"// nothing smaller.\n"
"//\n"
"// So placement is greedy over the running offset instead: at each step take the\n"
"// widest remaining field that needs *no* padding where the last one ended, and\n"
"// only when nothing fits fall back to the widest overall. That fills the pin's\n"
"// hole with the narrow field declaration order would have put there, and is at\n"
"// least as good as both a sort and source order everywhere on this corpus.\n"
"//\n"
"// Frequency is the tie-break rather than the primary key, and LAYOUT 6's ordering\n"
"// of the two is right for the reason it gives -- frequency decides where a\n"
"// hot/cold cut falls. There is no cut here (it needs handles), so frequency has\n"
"// nothing structural to decide and only costs padding if it leads.\n"
"static int layout_pad(int offset, int width) {\n"
"    if (width <= 0) return 0;\n"
"    int slack = offset % width;\n"
"    return slack == 0 ? 0 : width - slack;\n"
"}\n"
"\n"
"void aif_layout_select(void) {\n"
"    for (int n = 0; n < nominal_count; n++) {\n"
"        Nominal* t = &nominals[n];\n"
"        if (t->is_enum || t->nfields < 3) continue;   // nothing to permute past field 0\n"
"\n"
"        // The first field never moves; see above. Everything else is chosen by\n"
"        // greedy best-fit from the offset the pinned prefix left.\n"
"        int offset = t->field_bytes[0];\n"
"        for (int slot = 1; slot < t->nfields; slot++) {\n"
"            int best = -1, best_pad = 0;\n"
"            for (int c = slot; c < t->nfields; c++) {\n"
"                int f = t->order[c];\n"
"                int pad = layout_pad(offset, t->field_bytes[f]);\n"
"                if (best < 0) { best = c; best_pad = pad; continue; }\n"
"                int b = t->order[best];\n"
"                // Fits without padding beats anything that does not; then wider;\n"
"                // then hotter; then declaration index, so the order is total and\n"
"                // the output deterministic (LAYOUT 9).\n"
"                int better = 0;\n"
"                if ((pad == 0) != (best_pad == 0))            better = (pad == 0);\n"
"                else if (t->field_bytes[f] != t->field_bytes[b]) better = t->field_bytes[f] > t->field_bytes[b];\n"
"                else if (t->field_acc[f] != t->field_acc[b])     better = t->field_acc[f] > t->field_acc[b];\n"
"                else                                             better = f < b;\n"
"                if (better) { best = c; best_pad = pad; }\n"
"            }\n"
"            int chosen = t->order[best];\n"
"            t->order[best] = t->order[slot];\n"
"            t->order[slot] = chosen;\n"
"            offset += best_pad + t->field_bytes[chosen];\n"
"        }\n"
"\n"
"        for (int i = 0; i < t->nfields; i++) {\n"
"            if (t->order[i] != i) { t->reordered = 1; break; }\n"
"        }\n"
"    }\n"
"}\n"
"\n"
"// The i-th field of `type` in the chosen order, or \"\" when there is none. Codegen\n"
"// reads this to emit the struct body, and ir_register_struct_field follows in the\n"
"// same loop -- so the name -> index map and the LLVM type stay in lockstep and\n"
"// every field access follows without knowing anything about layout.\n"
"const char* aif_layout_field(const char* type, int i) {\n"
"    int id = nominal_find(type);\n"
"    if (id < 0) return \"\";\n"
"    Nominal* t = &nominals[id];\n"
"    if (i < 0 || i >= t->nfields) return \"\";\n"
"    return aif_str(t->field_name[t->order[i]]);\n"
"}\n"
"\n"
"int aif_layout_reordered(const char* type) {\n"
"    int id = nominal_find(type);\n"
"    return id >= 0 ? nominals[id].reordered : 0;\n"
"}\n"
"\n"
"// The width of the field placed i-th, so the size computation walks the layout\n"
"// the search chose rather than the one the source wrote.\n"
"int aif_layout_field_bytes(const char* type, int i) {\n"
"    int id = nominal_find(type);\n"
"    if (id < 0) return 0;\n"
"    Nominal* t = &nominals[id];\n"
"    if (i < 0 || i >= t->nfields) return 0;\n"
"    return t->field_bytes[t->order[i]];\n"
"}\n"
"\n"
"// The frontend computes this from the field types once every type is known.\n"
"// It is here rather than derived here because AIF-1's layout *is* declaration\n"
"// order (SPEC 8.2 gives the compiler layout freedom; AIF-1 does not use it), and\n"
"// the frontend is what knows what a field's type lowers to.\n"
"void aif_struct_set_size(const char* name, int bytes) {\n"
"    nominals[nominal_intern(name, 0)].bytes = bytes;\n"
"}\n"
"\n"
"int aif_struct_size(const char* name) {\n"
"    int id = nominal_find(name);\n"
"    return (id >= 0) ? nominals[id].bytes : 0;\n"
"}\n"
"\n"
"// One edge of the type reference graph (INFERENCE 4.4 stage 1). The frontend\n"
"// walks each field's type annotation and reports every nominal type it can\n"
"// reach, so `List<Node>` and `[Node]` both produce an edge to Node -- the\n"
"// element is reachable from the container whatever the container is.\n"
"void aif_type_edge(const char* from, const char* to) {\n"
"    int a = nominal_find(from);\n"
"    int b = nominal_find(to);\n"
"    if (a < 0 || b < 0) return;\n"
"    bits_set(&nominals[a].reaches, b, \"AIF type graph\");\n"
"}\n"
"\n"
"// Transitive closure, then: a type is cyclic when it reaches itself, or reaches\n"
"// anything that reaches itself. Acyclic is the complement.\n"
"//\n"
"// Closure rather than Tarjan because the graph has one node per nominal type --\n"
"// tens, not thousands -- so an O(n^3/64) fixpoint is free and has no recursion\n"
"// depth to get wrong.\n"
"void aif_compute_type_acyclic(void) {\n"
"    int changed = 1;\n"
"    while (changed) {\n"
"        changed = 0;\n"
"        for (int t = 0; t < nominal_count; t++) {\n"
"            for (int u = 0; u < nominal_count; u++) {\n"
"                if (!bits_test(&nominals[t].reaches, u)) continue;\n"
"                if (bits_or(&nominals[t].reaches, &nominals[u].reaches, \"AIF type graph\")) {\n"
"                    changed = 1;\n"
"                }\n"
"            }\n"
"        }\n"
"    }\n"
"\n"
"    for (int t = 0; t < nominal_count; t++) {\n"
"        int cyclic = bits_test(&nominals[t].reaches, t);\n"
"        for (int u = 0; !cyclic && u < nominal_count; u++) {\n"
"            if (bits_test(&nominals[t].reaches, u) && bits_test(&nominals[u].reaches, u)) {\n"
"                cyclic = 1;\n"
"            }\n"
"        }\n"
"        nominals[t].acyclic = !cyclic;\n"
"    }\n"
"}\n"
"\n"
"// Unknown types report acyclic. They are scalars and externs' opaque returns --\n"
"// none of which can hold a reference back into the program, so there is nothing\n"
"// for them to be part of a cycle with.\n"
"static int type_acyclic_id(int name) {\n"
"    int id = nominal_find_id(name);\n"
"    return (id < 0) ? 1 : nominals[id].acyclic;\n"
"}\n"
"\n"
"int aif_type_acyclic(const char* name) { return type_acyclic_id(aif_intern(name)); }\n"
"\n"
"int aif_nominal_count(void) { return nominal_count; }\n"
"const char* aif_nominal_name(int i) { return (i < 0 || i >= nominal_count) ? \"\" : aif_str(nominals[i].name); }\n"
"int aif_nominal_is_struct(int i)    { return (i < 0 || i >= nominal_count) ? 0 : !nominals[i].is_enum; }\n"
"int aif_nominal_acyclic(int i)      { return (i < 0 || i >= nominal_count) ? 1 : nominals[i].acyclic; }\n"
"\n"
"// ============================================================================\n"
"// Allocation sites\n"
"// ============================================================================\n"
"\n"
"typedef struct {\n"
"    int type;       // interned type display name\n"
"    int kind;\n"
"    int fn;\n"
"    int ordinal;    // position among its function's sites, in walk order\n"
"    int scope;\n"
"    int file, line, col;\n"
"    int nfields;\n"
"    int bytes;          // stamped once, before iteration\n"
"    int E, A, C;\n"
"    int type_acyclic;   // stamped once, before iteration\n"
"    int no_stack;       // explicitly dropped -- see AIF_CON_NO_STACK\n"
"    // Stored into a container by a `retain_in` call. The container owns it from\n"
"    // that point on, which is what makes a container teardown a release point --\n"
"    // and what takes the value's own binding off the drop list.\n"
"    int in_container;\n"
"    // SPEC 5.1. `unique` asserts A = Unique and cuts the aliasing graph: a rule\n"
"    // that would raise A above Unique is suppressed rather than applied.\n"
"    int alias_axiom;\n"
"    int alias_suppressed;   // the axiom actually stopped a rule; reported\n"
"    // SPEC 5.4. The tier a `pin` froze, or -1. Applied after convergence.\n"
"    int pin_tier;\n"
"    int pin_verdict;        // AIF_PIN_*, decided by aif_check_pins\n"
"} Site;\n"
"\n"
"// SPEC 5.4's four outcomes, plus \"there is no pin here\".\n"
"#define AIF_PIN_NONE     0\n"
"#define AIF_PIN_HONOURED 1\n"
"#define AIF_PIN_REFUTED  2   // converged facts make it unreachable -- an error\n"
"#define AIF_PIN_UNPROVEN 3   // budget ran out -- a warning, and the pin is dropped\n"
"\n"
"static Site* sites;\n"
"static int site_count, site_cap;\n"
"static int orphan_sites;    // sites with no enclosing function; none today\n"
"\n"
"int aif_site_new(const char* type, int kind, int fn, int scope,\n"
"                 int file, int line, int col, int nfields) {\n"
"    if (site_count == site_cap) {\n"
"        site_cap = site_cap ? site_cap * 2 : 1024;\n"
"        sites = (Site*)xrealloc(sites, (size_t)site_cap * sizeof(Site), \"AIF sites\");\n"
"    }\n"
"    Site* s = &sites[site_count];\n"
"    s->type = aif_intern(type);\n"
"    s->kind = kind;\n"
"    s->fn = fn;\n"
"    // The manifest is diffed, so a record's name must not move when an\n"
"    // unrelated line elsewhere in the file does. Numbering within the declaring\n"
"    // function gives that: an edit is visible on the function it changed and\n"
"    // nowhere else.\n"
"    s->ordinal = (fn >= 0 && fn < fn_count) ? fns[fn].nsites++ : orphan_sites++;\n"
"    s->scope = scope;\n"
"    s->file = file;\n"
"    s->line = line;\n"
"    s->col = col;\n"
"    s->nfields = nfields;\n"
"    s->bytes = 0;\n"
"    s->type_acyclic = 1;\n"
"    s->no_stack = 0;\n"
"    s->in_container = 0;\n"
"    s->alias_axiom = 0;\n"
"    s->alias_suppressed = 0;\n"
"    s->pin_tier = -1;\n"
"    s->pin_verdict = AIF_PIN_NONE;\n"
"    // Bottom, per INFERENCE 5.2 line 2: Region(defscope), Unique, Acyclic.\n"
"    s->E = scope;\n"
"    s->A = AIF_A_UNIQUE;\n"
"    s->C = AIF_C_ACYCLIC;\n"
"    return site_count++;\n"
"}\n"
"\n"
"int aif_site_count(void) { return site_count; }\n"
"\n"
"const char* aif_site_type(int id) { return (id < 0 || id >= site_count) ? \"\" : aif_str(sites[id].type); }\n"
"int aif_site_kind(int id)    { return (id < 0 || id >= site_count) ? AIF_K_OPAQUE : sites[id].kind; }\n"
"int aif_site_fn(int id)      { return (id < 0 || id >= site_count) ? -1 : sites[id].fn; }\n"
"int aif_site_scope(int id)   { return (id < 0 || id >= site_count) ? -1 : sites[id].scope; }\n"
"int aif_site_file(int id)    { return (id < 0 || id >= site_count) ? 0 : sites[id].file; }\n"
"int aif_site_line(int id)    { return (id < 0 || id >= site_count) ? 0 : sites[id].line; }\n"
"int aif_site_col(int id)     { return (id < 0 || id >= site_count) ? 0 : sites[id].col; }\n"
"int aif_site_nfields(int id) { return (id < 0 || id >= site_count) ? 0 : sites[id].nfields; }\n"
"int aif_site_ordinal(int id) { return (id < 0 || id >= site_count) ? 0 : sites[id].ordinal; }\n"
"int aif_site_escape(int id)  { return (id < 0 || id >= site_count) ? AIF_E_GLOBAL : sites[id].E; }\n"
"int aif_site_alias(int id)   { return (id < 0 || id >= site_count) ? AIF_A_SHARED : sites[id].A; }\n"
"int aif_site_cyc(int id)     { return (id < 0 || id >= site_count) ? AIF_C_MAYBE : sites[id].C; }\n"
"\n"
"// ============================================================================\n"
"// Points-to keys\n"
"//\n"
"// A key names a location that can hold references: a local binding, a struct\n"
"// field (field-sensitive, object-insensitive -- INFERENCE 3.1), a return\n"
"// position, or a parameter. Identity is the tuple, so the same name in two\n"
"// functions is two keys, and `Lexer.source` is one key across every Lexer.\n"
"// ============================================================================\n"
"\n"
"#define AIF_KEY_VAR    0\n"
"#define AIF_KEY_FIELD  1\n"
"#define AIF_KEY_RET    2\n"
"#define AIF_KEY_PARAM  3\n"
"#define AIF_KEY_EXTERN 4\n"
"\n"
"#define AIF_KEY_BUCKETS 16384\n"
"\n"
"typedef struct KeyNode {\n"
"    struct KeyNode* next;\n"
"    int kind, a, b;\n"
"    int id;\n"
"} KeyNode;\n"
"\n"
"static KeyNode* key_buckets[AIF_KEY_BUCKETS];\n"
"static int key_count;\n"
"\n"
"static int key_intern(int kind, int a, int b) {\n"
"    unsigned h = (unsigned)kind * 2654435761u\n"
"               ^ (unsigned)a * 40503u\n"
"               ^ (unsigned)b * 2246822519u;\n"
"    unsigned bucket = h & (AIF_KEY_BUCKETS - 1);\n"
"    for (KeyNode* n = key_buckets[bucket]; n; n = n->next) {\n"
"        if (n->kind == kind && n->a == a && n->b == b) return n->id;\n"
"    }\n"
"    KeyNode* n = (KeyNode*)xmalloc(sizeof(KeyNode), \"AIF points-to keys\");\n"
"    n->kind = kind;\n"
"    n->a = a;\n"
"    n->b = b;\n"
"    n->id = key_count++;\n"
"    n->next = key_buckets[bucket];\n"
"    key_buckets[bucket] = n;\n"
"    return n->id;\n"
"}\n"
"\n"
"int aif_key_var(int fn, const char* name)            { return key_intern(AIF_KEY_VAR, fn, aif_intern(name)); }\n"
"\n"
"// ---------------------------------------------------------------------------\n"
"// Declaring scopes\n"
"//\n"
"// E-BIND needs the scope a *variable* was declared in, not the scope the\n"
"// assignment sits in. Without it a value created inside a loop and assigned to a\n"
"// binding declared outside keeps the loop body's escape -- which reads as \"dies\n"
"// at the end of this iteration\" and is false, because the outer binding still\n"
"// refers to it on the next one.\n"
"//\n"
"// At Level 0 that was invisible: every tier is semantically valid and nothing\n"
"// allocated differently. It stops being invisible the moment T0 emits one\n"
"// hoisted alloca per site and every iteration writes the same slot.\n"
"//\n"
"// Shadowing joins outward. Two declarations of one name in sibling blocks join\n"
"// to their least common ancestor, which is at least as long-lived as either, so\n"
"// the answer is conservative rather than dependent on which the walk saw last.\n"
"// ---------------------------------------------------------------------------\n"
"\n"
"static int* var_scope;\n"
"static int var_scope_cap;\n"
"\n"
"static void var_scope_grow(int key) {\n"
"    if (key < var_scope_cap) return;\n"
"    int grow = var_scope_cap ? var_scope_cap * 2 : 1024;\n"
"    if (grow <= key) grow = key + 1;\n"
"    var_scope = (int*)xrealloc(var_scope, (size_t)grow * sizeof(int), \"AIF declaring scopes\");\n"
"    for (int i = var_scope_cap; i < grow; i++) var_scope[i] = -1;\n"
"    var_scope_cap = grow;\n"
"}\n"
"\n"
"void aif_var_note_scope(int fn, const char* name, int scope) {\n"
"    int key = aif_key_var(fn, name);\n"
"    var_scope_grow(key);\n"
"    if (var_scope[key] < 0) {\n"
"        var_scope[key] = scope;\n"
"        return;\n"
"    }\n"
"    int m = scope_lca(var_scope[key], scope);\n"
"    if (m >= 0) var_scope[key] = m;\n"
"}\n"
"\n"
"// -1 when the name has no declaration on record -- a global, or an assignment\n"
"// the walk reached before the declaration. The caller falls back to the\n"
"// assignment's own scope, which is what this function replaced.\n"
"int aif_var_scope(int fn, const char* name) {\n"
"    int key = aif_key_var(fn, name);\n"
"    return (key < var_scope_cap) ? var_scope[key] : -1;\n"
"}\n"
"int aif_key_field(const char* type, const char* fld) { return key_intern(AIF_KEY_FIELD, aif_intern(type), aif_intern(fld)); }\n"
"int aif_key_ret(int fn)                              { return key_intern(AIF_KEY_RET, fn, 0); }\n"
"int aif_key_param(int fn, int index)                 { return key_intern(AIF_KEY_PARAM, fn, index); }\n"
"int aif_key_count(void)                              { return key_count; }\n"
"\n"
"// ---------------------------------------------------------------------------\n"
"// Declared FFI contracts\n"
"//\n"
"// What an `extern` declaration says about ownership (FFI 5), keyed by the\n"
"// callee's name and a parameter index. Index -1 holds the return contract and\n"
"// -2 marks the name as declared at all.\n"
"//\n"
"// Keyed through the same tuple map as everything else, so a contract lookup at a\n"
"// call site is one hash rather than a scan over declarations.\n"
"// ---------------------------------------------------------------------------\n"
"\n"
"static int* extern_contract;    // key id -> interned contract text, -1 unset\n"
"static int extern_contract_cap;\n"
"\n"
"static void extern_contract_grow(int key) {\n"
"    if (key < extern_contract_cap) return;\n"
"    int grow = extern_contract_cap ? extern_contract_cap * 2 : 1024;\n"
"    if (grow <= key) grow = key + 1;\n"
"    extern_contract = (int*)xrealloc(extern_contract, (size_t)grow * sizeof(int),\n"
"                                     \"AIF extern contracts\");\n"
"    for (int i = extern_contract_cap; i < grow; i++) extern_contract[i] = -1;\n"
"    extern_contract_cap = grow;\n"
"}\n"
"\n"
"void aif_extern_contract_set(const char* fn, int index, const char* contract) {\n"
"    int key = key_intern(AIF_KEY_EXTERN, aif_intern(fn), index);\n"
"    extern_contract_grow(key);\n"
"    extern_contract[key] = aif_intern(contract);\n"
"}\n"
"\n"
"// \"\" when nothing was declared, which the frontend reads as \"fall through to the\n"
"// default\" rather than as a contract in its own right.\n"
"const char* aif_extern_contract(const char* fn, int index) {\n"
"    int key = key_intern(AIF_KEY_EXTERN, aif_intern(fn), index);\n"
"    if (key >= extern_contract_cap || extern_contract[key] < 0) return \"\";\n"
"    return aif_str(extern_contract[key]);\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Value-set expressions\n"
"//\n"
"// The set of sites an expression may denote: part known while walking (a struct\n"
"// literal is its own site), part only at the fixed point (an identifier is\n"
"// whatever its binding points to). Holding both in one object is what lets the\n"
"// AST walk compose expressions uniformly without knowing which it has.\n"
"//\n"
"// Items are tagged integers -- an even item is a site, an odd item is a key.\n"
"// ============================================================================\n"
"\n"
"typedef struct {\n"
"    int* items;\n"
"    int len, cap;\n"
"} ValueSet;\n"
"\n"
"static ValueSet* vsets;\n"
"static int vs_count, vs_cap;\n"
"\n"
"int aif_vs_new(void) {\n"
"    if (vs_count == vs_cap) {\n"
"        vs_cap = vs_cap ? vs_cap * 2 : 1024;\n"
"        vsets = (ValueSet*)xrealloc(vsets, (size_t)vs_cap * sizeof(ValueSet), \"AIF value sets\");\n"
"    }\n"
"    ValueSet* v = &vsets[vs_count];\n"
"    v->items = NULL;\n"
"    v->len = 0;\n"
"    v->cap = 0;\n"
"    return vs_count++;\n"
"}\n"
"\n"
"static void vs_push(int vs, int item) {\n"
"    if (vs < 0 || vs >= vs_count) return;\n"
"    ValueSet* v = &vsets[vs];\n"
"    for (int i = 0; i < v->len; i++) {\n"
"        if (v->items[i] == item) return;\n"
"    }\n"
"    if (v->len == v->cap) {\n"
"        v->cap = v->cap ? v->cap * 2 : 4;\n"
"        v->items = (int*)xrealloc(v->items, (size_t)v->cap * sizeof(int), \"AIF value set\");\n"
"    }\n"
"    v->items[v->len++] = item;\n"
"}\n"
"\n"
"void aif_vs_site(int vs, int site) { vs_push(vs, site * 2); }\n"
"void aif_vs_key(int vs, int key)   { vs_push(vs, key * 2 + 1); }\n"
"\n"
"int aif_vs_is_empty(int vs) {\n"
"    return (vs < 0 || vs >= vs_count) ? 1 : (vsets[vs].len == 0);\n"
"}\n"
"\n"
"int aif_vs_union(int a, int b) {\n"
"    int out = aif_vs_new();\n"
"    if (a >= 0 && a < vs_count) {\n"
"        for (int i = 0; i < vsets[a].len; i++) vs_push(out, vsets[a].items[i]);\n"
"    }\n"
"    if (b >= 0 && b < vs_count) {\n"
"        for (int i = 0; i < vsets[b].len; i++) vs_push(out, vsets[b].items[i]);\n"
"    }\n"
"    return out;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Argument stacks\n"
"//\n"
"// Two FFI contracts refer to another argument of the same call: `retain_in(k)`\n"
"// says \"the callee stores me into argument k\", and `alias` says \"my return is\n"
"// argument k\". Both need the call's arguments addressable by index while it is\n"
"// being walked -- and calls nest, because an argument can itself be a call.\n"
"//\n"
"// Evaluating an argument creates allocation sites, so it must happen exactly\n"
"// once; re-walking to find argument k would duplicate every site inside it.\n"
"// Hence a stack: the frontend opens a frame, pushes each argument's value set\n"
"// as it evaluates it, indexes freely, and closes the frame.\n"
"// ============================================================================\n"
"\n"
"static IntVec argv;\n"
"\n"
"int aif_argv_begin(void) { return argv.len; }\n"
"\n"
"void aif_argv_push(int vs) { vec_push(&argv, vs, \"AIF call arguments\"); }\n"
"\n"
"int aif_argv_count(int base) { return argv.len - base; }\n"
"\n"
"// Out of range yields -1, which every consumer reads as the empty value set --\n"
"// a contract naming an argument the call does not have contributes nothing.\n"
"int aif_argv_get(int base, int i) {\n"
"    int at = base + i;\n"
"    if (i < 0 || at >= argv.len) return -1;\n"
"    return argv.v[at];\n"
"}\n"
"\n"
"void aif_argv_end(int base) { argv.len = base; }\n"
"\n"
"// ============================================================================\n"
"// Constraints\n"
"//\n"
"// One entry per transfer-rule instance the AST walk discovered. Solving is\n"
"// re-applying all of them until nothing rises.\n"
"// ============================================================================\n"
"\n"
"#define AIF_CON_BIND          0\n"
"#define AIF_CON_ARG           1\n"
"#define AIF_CON_STORE         2\n"
"#define AIF_CON_LIVE_IN       3\n"
"#define AIF_CON_OPAQUE        4\n"
"#define AIF_CON_RETAIN_IN     5\n"
"#define AIF_CON_BORROW        6\n"
"#define AIF_CON_ESCAPE_CALLER 7\n"
"#define AIF_CON_ESCAPE_GLOBAL 8\n"
"#define AIF_CON_NO_STACK      9\n"
"// SPEC 5's annotations. Neither is a transfer rule: both are applied once,\n"
"// between the points-to fixed point and the fact loop, because an axiom that\n"
"// arrives mid-iteration would only cut what had not already been raised.\n"
"#define AIF_CON_UNIQUE       10\n"
"#define AIF_CON_PIN          11\n"
"// Not constraints: the two rules that read a site's own state rather than an\n"
"// incoming edge. They still need names, because a witness path that ends at one\n"
"// has to say so rather than reporting \"no cause\".\n"
"#define AIF_RULE_A_ESCAPE    12\n"
"#define AIF_RULE_A_COPY      13\n"
"#define AIF_RULE_ALLOC       14   // the root: this is where the value is made\n"
"#define AIF_RULE_A_CONTAIN   15\n"
"\n"
"typedef struct {\n"
"    int kind, a, b, c;\n"
"    // Where in the source this constraint came from. Carried so a manifest diff\n"
"    // can name the store or the call that moved a fact (SPEC 6.3's example puts\n"
"    // a file:line on every edge of the witness path), not just which rule fired.\n"
"    int file, line, col;\n"
"} Constraint;\n"
"\n"
"static Constraint* cons;\n"
"static int con_count, con_cap;\n"
"static int con_file, con_line, con_col;\n"
"\n"
"static void con_add(int kind, int a, int b, int c) {\n"
"    if (con_count == con_cap) {\n"
"        con_cap = con_cap ? con_cap * 2 : 4096;\n"
"        cons = (Constraint*)xrealloc(cons, (size_t)con_cap * sizeof(Constraint), \"AIF constraints\");\n"
"    }\n"
"    cons[con_count].file = con_file;\n"
"    cons[con_count].line = con_line;\n"
"    cons[con_count].col = con_col;\n"
"    Constraint* k = &cons[con_count++];\n"
"    k->kind = kind;\n"
"    k->a = a;\n"
"    k->b = b;\n"
"    k->c = c;\n"
"}\n"
"\n"
"void aif_con_bind(int key, int vs)              { con_add(AIF_CON_BIND, key, vs, 0); }\n"
"void aif_con_arg(int key, int vs)               { con_add(AIF_CON_ARG, key, vs, 0); }\n"
"void aif_con_store(int key, int vs, int owners) { con_add(AIF_CON_STORE, key, vs, owners); }\n"
"void aif_con_live_in(int vs, int scope, int fn) { con_add(AIF_CON_LIVE_IN, vs, scope, fn); }\n"
"void aif_con_opaque(int vs)                     { con_add(AIF_CON_OPAQUE, vs, 0, 0); }\n"
"void aif_con_retain_in(int vs, int holder)      { con_add(AIF_CON_RETAIN_IN, vs, holder, 0); }\n"
"void aif_con_borrow(int vs)                     { con_add(AIF_CON_BORROW, vs, 0, 0); }\n"
"void aif_con_escape_caller(int vs)              { con_add(AIF_CON_ESCAPE_CALLER, vs, 0, 0); }\n"
"void aif_con_escape_global(int vs)              { con_add(AIF_CON_ESCAPE_GLOBAL, vs, 0, 0); }\n"
"void aif_con_unique(int vs)                     { con_add(AIF_CON_UNIQUE, vs, 0, 0); }\n"
"void aif_con_pin(int vs, int tier)              { con_add(AIF_CON_PIN, vs, tier, 0); }\n"
"\n"
"// `drop(x)` lowers to a free, and a stack slot is not a thing that can be freed.\n"
"// A T0 value has no allocation to release -- its storage *is* the frame -- so\n"
"// promoting a value the source explicitly drops turns a working program into\n"
"// heap corruption.\n"
"//\n"
"// This is not a fact about the value and deliberately does not touch E, A or C:\n"
"// an explicit drop says nothing about lifetime or aliasing, and distorting a\n"
"// fact domain to carry a codegen constraint would make the manifest lie about\n"
"// why. It suppresses the T0 clause and nothing else, so the value lands T1/T2 --\n"
"// heap-allocated, with something to free.\n"
"//\n"
"// The better answer is for `drop` on a T0 value to emit nothing at all, which\n"
"// needs codegen to resolve the tier of a *binding* at the drop site rather than\n"
"// the tier of an allocation at its literal. That wants COMPILER-AUDIT 4.1's node\n"
"// ids. Until then this is the sound direction to be wrong in.\n"
"void aif_con_no_stack(int vs)                   { con_add(AIF_CON_NO_STACK, vs, 0, 0); }\n"
"\n"
"int aif_con_count(void) { return con_count; }\n"
"\n"
"// ============================================================================\n"
"// The fixed point\n"
"// ============================================================================\n"
"\n"
"static Bits* pt;            // key id -> set of sites\n"
"static Bits* holders;       // site id -> set of keys holding it\n"
"// site id -> set of *container sites* holding it. Separate from `holders`, which\n"
"// counts keys -- named locations the move checker governs. A container element is\n"
"// neither: `list_push` is a call, so nothing about it is a move, and two pushes\n"
"// of one value are two owners the language never had to notice.\n"
"static Bits* container_of;\n"
"static int pt_len, holders_len;\n"
"static Bits scratch_val, scratch_own;\n"
"static IntVec vec_val, vec_own;\n"
"static int solve_rounds;\n"
"static int pt_rounds;       // of solve_rounds, how many the points-to phase used\n"
"\n"
"// Delta, in INFERENCE 5.3's sense: what moved in the round that just ran. On a\n"
"// truncated run that is the frontier the widening has to start from, so it is\n"
"// reset at the top of every round and only the last one's survives.\n"
"static Bits delta;          // sites whose facts moved\n"
"static int  delta_pt;       // did any points-to or holders set grow?\n"
"static Bits widened;        // sites aif_widen raised, for the manifest\n"
"\n"
"// Whether collections are affine, i.e. whether the copy rule applies to them.\n"
"// Today's Prismio makes only structs move-only (types.psm); AIF specifies\n"
"// affine references for every heap value (SPEC 11 item 10). The difference is\n"
"// 100% of the measured T3 residue, so it is a switch rather than an assumption.\n"
"static int owned_collections;\n"
"\n"
"void aif_set_owned_collections(int on) { owned_collections = on ? 1 : 0; }\n"
"\n"
"// A move-only value can be held by several bindings over its lifetime without\n"
"// ever being aliased -- the move checker guarantees the earlier binding is dead\n"
"// -- so multiple holders means sequential ownership, not sharing. A copyable\n"
"// one has no such guarantee.\n"
"static int site_is_move_only(const Site* s) {\n"
"    if (s->kind == AIF_K_STRUCT) return 1;\n"
"    if (!owned_collections) return 0;\n"
"    return s->kind == AIF_K_STRING || s->kind == AIF_K_ARRAY || s->kind == AIF_K_LIST;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// The derivation DAG (INFERENCE 5.6, SPEC 6.3)\n"
"//\n"
"// A manifest diff has to answer *why* a tier moved, and the answer is a witness\n"
"// path from a root cause to the record. INFERENCE 5.6 specifies a backward BFS\n"
"// through **maximal contributors**: for a fact `f` at node `n` holding value\n"
"// `v`, the predecessors whose transfer produced `v`.\n"
"//\n"
"// Keeping every predecessor and searching backward is one way to get that. This\n"
"// keeps **one edge per site per domain** instead, written the moment a rule\n"
"// first raises the fact to the value it ends at -- which is a maximal\n"
"// contributor by construction, because a rule that raises is one that set the\n"
"// value rather than one that merely failed to contradict it. Walking those edges\n"
"// backward is then a chain rather than a search.\n"
"//\n"
"// Two honest consequences of that choice:\n"
"//\n"
"//   * The path is *a* witness, not provably the *shortest* one. The first rule\n"
"//     to reach the final value is recorded, which is the shortest among the\n"
"//     rules that fired in that round, but a different constraint order could\n"
"//     have produced a shorter chain. INFERENCE 5.1 permits the order to vary,\n"
"//     so \"shortest\" was never stable anyway.\n"
"//   * Memory is O(sites), not O(edges). 5.6's requirement is that the DAG be\n"
"//     *retained through tier assignment*, and one maximal edge per fact is\n"
"//     enough to retain what a diff reads back.\n"
"// ============================================================================\n"
"\n"
"typedef struct {\n"
"    int rule;   // the AIF_CON_* that fired, or -1 for \"never raised\"\n"
"    int from;   // the site the value came from, or -1 for an axiom or a root\n"
"    int value;  // what it was raised to\n"
"    int file, line, col;\n"
"} Deriv;\n"
"\n"
"static Deriv* deriv_e;      // why each site's E is what it is\n"
"static Deriv* deriv_a;      // and its A\n"
"static int cur_con = -1;    // the constraint being applied, for attribution\n"
"static int synth_rule = -1; // ...or the rule, when there is no constraint\n"
"\n"
"// Where the constraint currently being *built* came from. Constraints are added\n"
"// during the walk, one node at a time, so a sticky position costs nothing and\n"
"// keeps ten aif_con_* signatures unchanged.\n"
"void aif_con_at(int file, int line, int col) {\n"
"    con_file = file;\n"
"    con_line = line;\n"
"    con_col = col;\n"
"}\n"
"\n"
"static void note_deriv(Deriv* d, int site, int from, int value) {\n"
"    if (!d) return;\n"
"    int live = (cur_con >= 0 && cur_con < con_count);\n"
"    d[site].rule  = live ? cons[cur_con].kind : synth_rule;\n"
"    d[site].from  = from;\n"
"    d[site].value = value;\n"
"    d[site].file  = live ? cons[cur_con].file : sites[site].file;\n"
"    d[site].line  = live ? cons[cur_con].line : sites[site].line;\n"
"    d[site].col   = live ? cons[cur_con].col  : sites[site].col;\n"
"}\n"
"\n"
"\n"
"static void solver_alloc(void) {\n"
"    pt_len = key_count;\n"
"    holders_len = site_count;\n"
"    pt = (Bits*)xcalloc((size_t)pt_len, sizeof(Bits), \"AIF points-to\");\n"
"    holders = (Bits*)xcalloc((size_t)holders_len, sizeof(Bits), \"AIF holders\");\n"
"    container_of = (Bits*)xcalloc((size_t)holders_len, sizeof(Bits), \"AIF container holders\");\n"
"    // INFERENCE 5.6 requires the derivation be retained through tier assignment.\n"
"    deriv_e = (Deriv*)xcalloc((size_t)site_count, sizeof(Deriv), \"AIF derivation (E)\");\n"
"    deriv_a = (Deriv*)xcalloc((size_t)site_count, sizeof(Deriv), \"AIF derivation (A)\");\n"
"    for (int s = 0; s < site_count; s++) {\n"
"        // A site nothing ever raised is at its own allocation, which is the root\n"
"        // every witness path terminates at.\n"
"        deriv_e[s].rule = AIF_RULE_ALLOC;\n"
"        deriv_a[s].rule = AIF_RULE_ALLOC;\n"
"        deriv_e[s].from = -1;\n"
"        deriv_a[s].from = -1;\n"
"        // The bottom values, so a fact nothing ever raised still reports what it\n"
"        // is rather than whatever calloc left behind.\n"
"        deriv_e[s].value = sites[s].E;\n"
"        deriv_a[s].value = sites[s].A;\n"
"        deriv_e[s].file = deriv_a[s].file = sites[s].file;\n"
"        deriv_e[s].line = deriv_a[s].line = sites[s].line;\n"
"        deriv_e[s].col  = deriv_a[s].col  = sites[s].col;\n"
"    }\n"
"    for (int s = 0; s < site_count; s++) {\n"
"        sites[s].type_acyclic = type_acyclic_id(sites[s].type);\n"
"        int t = nominal_find_id(sites[s].type);\n"
"        sites[s].bytes = (t >= 0) ? nominals[t].bytes : 0;\n"
"    }\n"
"}\n"
"\n"
"// Flatten a value-set expression against the current points-to state.\n"
"static void resolve(int vs, Bits* out) {\n"
"    bits_clear(out);\n"
"    if (vs < 0 || vs >= vs_count) return;\n"
"    ValueSet* v = &vsets[vs];\n"
"    for (int i = 0; i < v->len; i++) {\n"
"        int item = v->items[i];\n"
"        if (item & 1) {\n"
"            int key = item >> 1;\n"
"            if (key < pt_len) bits_or(out, &pt[key], \"AIF resolve\");\n"
"        } else {\n"
"            bits_set(out, item >> 1, \"AIF resolve\");\n"
"        }\n"
"    }\n"
"}\n"
"\n"
"// Records the site in this round's delta and returns 1, so a rule reads\n"
"// `if (raise_alias(s, X)) changed = moved(s);`.\n"
"static int moved(int site) {\n"
"    bits_set(&delta, site, \"AIF delta\");\n"
"    return 1;\n"
"}\n"
"\n"
"static int raise_escape(int site, int target, int from) {\n"
"    int j = escape_join(sites[site].E, target);\n"
"    if (j == sites[site].E) return 0;\n"
"    sites[site].E = j;\n"
"    note_deriv(deriv_e, site, from, j);\n"
"    return 1;\n"
"}\n"
"\n"
"static int raise_alias(int site, int level, int from) {\n"
"    if (sites[site].A >= level) return 0;\n"
"    // SPEC 5.1: `unique` is an axiom, so the solver takes A = Unique as given\n"
"    // and does not propagate aliasing into the annotated binding. This is the\n"
"    // cut, and it is the whole mechanism -- an axiom that a rule could overrule\n"
"    // is not one.\n"
"    //\n"
"    // What makes it sound here rather than merely asserted is the language: a\n"
"    // second *owning* reference within the declaring scope is already a\n"
"    // compile error under affine collections, because taking one is a move and\n"
"    // using the original afterwards is `use of moved value`. So the local\n"
"    // verification SPEC 5.1 asks for is discharged by the move checker, and\n"
"    // what remains is the interprocedural half -- exactly what an axiom is for.\n"
"    // The suppression is recorded so the manifest can say which values rest on\n"
"    // the assertion.\n"
"    if (sites[site].alias_axiom && level > AIF_A_UNIQUE) {\n"
"        sites[site].alias_suppressed = 1;\n"
"        return 0;\n"
"    }\n"
"    sites[site].A = level;\n"
"    note_deriv(deriv_a, site, from, level);\n"
"    return 1;\n"
"}\n"
"\n"
"// Iteration runs to full convergence, so by Kleene's theorem the result is the\n"
"// least fixed point regardless of the order constraints are applied in\n"
"// (INFERENCE 5.1 permits asynchronous iteration on exactly that condition).\n"
"// Order-independence is what licenses updating in place rather than\n"
"// double-buffering -- and it is why this engine's manifest must equal the\n"
"// Python oracle's, which applies the same constraints the same way.\n"
"//\n"
"// Returns 1 on convergence, 0 when the round budget ran out. A 0 return is NOT\n"
"// safe to assign tiers from: see aif_widen.\n"
"// Every rule that writes pt or holders reads only pt -- no fact feeds back into\n"
"// the points-to relation -- so its least fixed point is independent of the facts\n"
"// and reaching it first changes no answer. What it changes is the frontier:\n"
"// solved together, points-to is still growing when a budget bites, and a set\n"
"// that may still gain members this pass cannot name makes every site a possible\n"
"// successor. Separated, the fact phase always truncates over a final graph.\n"
"static int solve_points_to(int max_rounds) {\n"
"    for (int r = 0; r < max_rounds; r++) {\n"
"        solve_rounds++;\n"
"        int changed = 0;\n"
"\n"
"        for (int ci = 0; ci < con_count; ci++) {\n"
"            Constraint* k = &cons[ci];\n"
"            if (k->kind != AIF_CON_BIND && k->kind != AIF_CON_ARG\n"
"                && k->kind != AIF_CON_STORE) {\n"
"                continue;\n"
"            }\n"
"\n"
"            resolve(k->b, &scratch_val);\n"
"            if (bits_or(&pt[k->a], &scratch_val, \"AIF points-to\")) changed = 1;\n"
"\n"
"            // Passing a value as an argument does not make the parameter a\n"
"            // holder of it, so ARG records none.\n"
"            if (k->kind == AIF_CON_ARG) continue;\n"
"            bits_to_vec(&scratch_val, &vec_val);\n"
"            for (int i = 0; i < vec_val.len; i++) {\n"
"                if (bits_set(&holders[vec_val.v[i]], k->a, \"AIF holders\")) changed = 1;\n"
"            }\n"
"        }\n"
"\n"
"        if (!changed) return 1;\n"
"    }\n"
"    return 0;\n"
"}\n"
"\n"
"int aif_solve(int max_rounds) {\n"
"    solver_alloc();\n"
"    solve_rounds = 0;\n"
"\n"
"    if (!solve_points_to(max_rounds)) {\n"
"        delta_pt = 1;\n"
"        pt_rounds = solve_rounds;\n"
"        return 0;\n"
"    }\n"
"    pt_rounds = solve_rounds;\n"
"\n"
"    // SPEC 5: annotations enter here, after points-to and before the facts.\n"
"    //\n"
"    // After, because a value set may name a variable rather than a site, and\n"
"    // resolving one needs the points-to relation. Before, because both are\n"
"    // statements about the *result*: an axiom applied mid-iteration would only\n"
"    // cut the rules that had not fired yet, which would make the answer depend\n"
"    // on constraint order -- and INFERENCE 5.1 lets the order vary.\n"
"    for (int ci = 0; ci < con_count; ci++) {\n"
"        Constraint* k = &cons[ci];\n"
"        if (k->kind != AIF_CON_UNIQUE && k->kind != AIF_CON_PIN) continue;\n"
"        resolve(k->a, &scratch_val);\n"
"        bits_to_vec(&scratch_val, &vec_val);\n"
"        for (int i = 0; i < vec_val.len; i++) {\n"
"            if (k->kind == AIF_CON_UNIQUE) {\n"
"                sites[vec_val.v[i]].alias_axiom = 1;\n"
"            } else if (k->b > sites[vec_val.v[i]].pin_tier) {\n"
"                // Two pins on one site is a program that annotated the same\n"
"                // allocation twice; the stricter reading is the more expensive\n"
"                // tier, which is the one that cannot be unsound.\n"
"                sites[vec_val.v[i]].pin_tier = k->b;\n"
"            }\n"
"        }\n"
"    }\n"
"\n"
"    // Nothing has been proved about any site yet, so if the budget leaves no\n"
"    // round for the facts the frontier is the whole graph. Overwritten by the\n"
"    // first round that runs.\n"
"    for (int s = 0; s < site_count; s++) bits_set(&delta, s, \"AIF delta\");\n"
"\n"
"    for (int r = solve_rounds; r < max_rounds; r++) {\n"
"        solve_rounds = r + 1;\n"
"        int changed = 0;\n"
"        bits_clear(&delta);\n"
"        delta_pt = 0;\n"
"\n"
"        for (int ci = 0; ci < con_count; ci++) {\n"
"            Constraint* k = &cons[ci];\n"
"            cur_con = ci;\n"
"\n"
"            if (k->kind == AIF_CON_BIND) {\n"
"                resolve(k->b, &scratch_val);\n"
"                if (bits_or(&pt[k->a], &scratch_val, \"AIF points-to\")) changed = delta_pt = 1;\n"
"                bits_to_vec(&scratch_val, &vec_val);\n"
"                for (int i = 0; i < vec_val.len; i++) {\n"
"                    if (bits_set(&holders[vec_val.v[i]], k->a, \"AIF holders\")) changed = delta_pt = 1;\n"
"                }\n"
"\n"
"            } else if (k->kind == AIF_CON_ARG) {\n"
"                resolve(k->b, &scratch_val);\n"
"                if (bits_or(&pt[k->a], &scratch_val, \"AIF points-to\")) changed = delta_pt = 1;\n"
"                bits_to_vec(&scratch_val, &vec_val);\n"
"                // A-CALL: passing a value hands out a borrow of it.\n"
"                for (int i = 0; i < vec_val.len; i++) {\n"
"                    if (raise_alias(vec_val.v[i], AIF_A_BORROWED, -1)) changed = moved(vec_val.v[i]);\n"
"                }\n"
"\n"
"            } else if (k->kind == AIF_CON_STORE) {\n"
"                resolve(k->b, &scratch_val);\n"
"                resolve(k->c, &scratch_own);\n"
"                if (bits_or(&pt[k->a], &scratch_val, \"AIF points-to\")) changed = delta_pt = 1;\n"
"                bits_to_vec(&scratch_val, &vec_val);\n"
"                bits_to_vec(&scratch_own, &vec_own);\n"
"                for (int i = 0; i < vec_val.len; i++) {\n"
"                    int s = vec_val.v[i];\n"
"                    if (bits_set(&holders[s], k->a, \"AIF holders\")) changed = delta_pt = 1;\n"
"                    for (int j = 0; j < vec_own.len; j++) {\n"
"                        int o = vec_own.v[j];\n"
"                        // E-STORE: reachable from the container, so it lives at\n"
"                        // least as long as the container does.\n"
"                        if (raise_escape(s, sites[o].E, o)) changed = moved(s);\n"
"                        // A-STORE: sharing is inherited through reachability.\n"
"                        if (raise_alias(s, sites[o].A, o)) changed = moved(s);\n"
"                    }\n"
"                }\n"
"\n"
"            } else if (k->kind == AIF_CON_LIVE_IN) {\n"
"                resolve(k->a, &scratch_val);\n"
"                bits_to_vec(&scratch_val, &vec_val);\n"
"                for (int i = 0; i < vec_val.len; i++) {\n"
"                    int s = vec_val.v[i];\n"
"                    // Cross-function flow does not extend a lifetime: only a\n"
"                    // binding in the site's own function says anything about\n"
"                    // which of that function's scopes the value outlives.\n"
"                    int target = (sites[s].fn == k->c) ? k->b : AIF_E_CALLER;\n"
"                    if (raise_escape(s, target, -1)) changed = moved(s);\n"
"                }\n"
"\n"
"            } else if (k->kind == AIF_CON_OPAQUE) {\n"
"                resolve(k->a, &scratch_val);\n"
"                bits_to_vec(&scratch_val, &vec_val);\n"
"                for (int i = 0; i < vec_val.len; i++) {\n"
"                    int s = vec_val.v[i];\n"
"                    if (sites[s].E != AIF_E_GLOBAL && raise_escape(s, AIF_E_CALLER, -1)) changed = moved(s);\n"
"                    if (raise_alias(s, AIF_A_SHARED, -1)) changed = moved(s);\n"
"                }\n"
"\n"
"            } else if (k->kind == AIF_CON_RETAIN_IN) {\n"
"                // E-STORE / A-STORE against a container reached through a call\n"
"                // rather than through a field assignment (FFI `retain_in`).\n"
"                resolve(k->a, &scratch_val);\n"
"                resolve(k->b, &scratch_own);\n"
"                bits_to_vec(&scratch_val, &vec_val);\n"
"                bits_to_vec(&scratch_own, &vec_own);\n"
"                for (int i = 0; i < vec_val.len; i++) {\n"
"                    int s = vec_val.v[i];\n"
"                    for (int j = 0; j < vec_own.len; j++) {\n"
"                        int h = vec_own.v[j];\n"
"                        if (raise_escape(s, sites[h].E, h)) changed = moved(s);\n"
"                        if (raise_alias(s, sites[h].A, h)) changed = moved(s);\n"
"                        // Which containers hold it, not merely that one does. The\n"
"                        // count is the fact A-CONTAIN reads, and it is the only\n"
"                        // thing separating \"the container owns this, free it at\n"
"                        // teardown\" from a double free through the second one.\n"
"                        if (bits_set(&container_of[s], h, \"AIF container holders\")) {\n"
"                            changed = moved(s);\n"
"                        }\n"
"                    }\n"
"                    if (!sites[s].in_container && vec_own.len > 0) {\n"
"                        sites[s].in_container = 1;\n"
"                        changed = moved(s);\n"
"                    }\n"
"                    if (raise_alias(s, AIF_A_BORROWED, -1)) changed = moved(s);\n"
"                }\n"
"\n"
"            } else if (k->kind == AIF_CON_BORROW) {\n"
"                // Raises A to Borrowed for the call's duration and nothing\n"
"                // else. Escape is untouched: a callee that does not retain\n"
"                // cannot extend a lifetime (FFI 6, `borrow` row).\n"
"                resolve(k->a, &scratch_val);\n"
"                bits_to_vec(&scratch_val, &vec_val);\n"
"                for (int i = 0; i < vec_val.len; i++) {\n"
"                    if (raise_alias(vec_val.v[i], AIF_A_BORROWED, -1)) changed = moved(vec_val.v[i]);\n"
"                }\n"
"\n"
"            } else if (k->kind == AIF_CON_ESCAPE_CALLER) {\n"
"                resolve(k->a, &scratch_val);\n"
"                bits_to_vec(&scratch_val, &vec_val);\n"
"                for (int i = 0; i < vec_val.len; i++) {\n"
"                    if (raise_escape(vec_val.v[i], AIF_E_CALLER, -1)) changed = moved(vec_val.v[i]);\n"
"                }\n"
"\n"
"            } else if (k->kind == AIF_CON_NO_STACK) {\n"
"                resolve(k->a, &scratch_val);\n"
"                bits_to_vec(&scratch_val, &vec_val);\n"
"                for (int i = 0; i < vec_val.len; i++) {\n"
"                    if (!sites[vec_val.v[i]].no_stack) {\n"
"                        sites[vec_val.v[i]].no_stack = 1;\n"
"                        changed = moved(vec_val.v[i]);\n"
"                    }\n"
"                }\n"
"\n"
"            } else if (k->kind == AIF_CON_ESCAPE_GLOBAL) {\n"
"                resolve(k->a, &scratch_val);\n"
"                bits_to_vec(&scratch_val, &vec_val);\n"
"                for (int i = 0; i < vec_val.len; i++) {\n"
"                    int s = vec_val.v[i];\n"
"                    if (sites[s].E != AIF_E_GLOBAL) {\n"
"                        sites[s].E = AIF_E_GLOBAL;\n"
"                        note_deriv(deriv_e, s, -1, AIF_E_GLOBAL);\n"
"                        changed = moved(s);\n"
"                    }\n"
"                }\n"
"            }\n"
"        }\n"
"\n"
"        // Rules that read a site's own state rather than an incoming edge. They\n"
"        // have no constraint to attribute to, so the derivation names the rule\n"
"        // directly -- cur_con of -1 makes note_deriv fall back to synth_rule.\n"
"        cur_con = -1;\n"
"        for (int s = 0; s < site_count; s++) {\n"
"            // A-ESCAPE: anything globally reachable is reachable more than once.\n"
"            synth_rule = AIF_RULE_A_ESCAPE;\n"
"            if (sites[s].E == AIF_E_GLOBAL && raise_alias(s, AIF_A_SHARED, -1)) changed = moved(s);\n"
"\n"
"            // A-COPY: only a copyable value can be genuinely multiply held.\n"
"            synth_rule = AIF_RULE_A_COPY;\n"
"            if (!site_is_move_only(&sites[s])\n"
"                && bits_count_at_least_two(&holders[s])\n"
"                && raise_alias(s, AIF_A_SHARED, -1)) {\n"
"                changed = moved(s);\n"
"            }\n"
"\n"
"            // A-CONTAIN: two containers holding one value is sharing, whatever\n"
"            // the type.\n"
"            //\n"
"            // A-COPY exempts move-only values because a second *binding* is a\n"
"            // move, so the earlier one is provably dead. That argument does not\n"
"            // reach a container: `list_push(l, x)` is a call, and a call is not a\n"
"            // move -- so `store(l1, x); store(l2, x)` puts one value under two\n"
"            // owners with nothing in the language to notice. Once a container\n"
"            // teardown releases its elements, that is the double free.\n"
"            //\n"
"            // Making it Shared is not a workaround for the gap; it is the correct\n"
"            // reading, and it lands the value on the tier built for exactly this\n"
"            // shape. One container owns and frees (T2); two share and count (T3).\n"
"            synth_rule = AIF_RULE_A_CONTAIN;\n"
"            if (bits_count_at_least_two(&container_of[s])\n"
"                && raise_alias(s, AIF_A_SHARED, -1)) {\n"
"                changed = moved(s);\n"
"            }\n"
"\n"
"            // C-UNIQUE / C-TYPE (INFERENCE 4.4 stage 2).\n"
"            int acyclic = (sites[s].A == AIF_A_UNIQUE) || sites[s].type_acyclic;\n"
"            int want = acyclic ? AIF_C_ACYCLIC : AIF_C_MAYBE;\n"
"            if (want > sites[s].C) {\n"
"                sites[s].C = want;\n"
"                changed = moved(s);\n"
"            }\n"
"        }\n"
"\n"
"        if (!changed) return 1;\n"
"    }\n"
"    return 0;\n"
"}\n"
"\n"
"int aif_rounds(void) { return solve_rounds; }\n"
"int aif_pt_rounds(void) { return pt_rounds; }\n"
"\n"
"// INFERENCE 5.3: a truncated ascending iteration is a *pre*-fixed point, so its\n"
"// facts are too optimistic -- assigning tiers from one would hand a value T2\n"
"// where the unexplored rounds would have proved it Shared. That is a\n"
"// use-after-free, not a slowdown, so truncation must be followed by widening to\n"
"// a post-fixed point.\n"
"//\n"
"// U := delta union transitive_succs(delta). If a site's facts change in round\n"
"// r+1, some input of it changed in round r, so chaining back puts everything\n"
"// still in motion inside the closure of the last round's delta -- and raising\n"
"// exactly that set to top yields a post-fixed point.\n"
"//\n"
"// Fact flow between sites runs owner -> value and only through STORE and\n"
"// RETAIN_IN; every other rule raises a site from a constant, and the per-site\n"
"// rules are self-edges. Those two edges are read out of the points-to state,\n"
"// which takes no input from the facts -- so once points-to has settled the\n"
"// successor graph is final and the frontier is exact. While points-to is still\n"
"// growing it is not: a later round can put a site into a set this pass cannot\n"
"// name, so there the whole graph is the only sound answer.\n"
"static void widen_sites(const Bits* u) {\n"
"    for (int s = 0; s < site_count; s++) {\n"
"        if (u && !bits_test(u, s)) continue;\n"
"        sites[s].E = AIF_E_GLOBAL;\n"
"        sites[s].A = AIF_A_SHARED;\n"
"        sites[s].C = AIF_C_MAYBE;\n"
"        bits_set(&widened, s, \"AIF widened\");\n"
"    }\n"
"}\n"
"\n"
"void aif_widen(void) {\n"
"    if (site_count <= 0) return;\n"
"\n"
"    if (delta_pt) {\n"
"        widen_sites(NULL);\n"
"        return;\n"
"    }\n"
"\n"
"    Bits* succ = (Bits*)xcalloc((size_t)site_count, sizeof(Bits), \"AIF widen succ\");\n"
"    for (int ci = 0; ci < con_count; ci++) {\n"
"        Constraint* k = &cons[ci];\n"
"        int vs_val, vs_own;\n"
"        if (k->kind == AIF_CON_STORE)           { vs_val = k->b; vs_own = k->c; }\n"
"        else if (k->kind == AIF_CON_RETAIN_IN)  { vs_val = k->a; vs_own = k->b; }\n"
"        else continue;\n"
"\n"
"        resolve(vs_val, &scratch_val);\n"
"        resolve(vs_own, &scratch_own);\n"
"        bits_to_vec(&scratch_own, &vec_own);\n"
"        for (int j = 0; j < vec_own.len; j++) {\n"
"            bits_or(&succ[vec_own.v[j]], &scratch_val, \"AIF widen succ\");\n"
"        }\n"
"    }\n"
"\n"
"    Bits u;\n"
"    memset(&u, 0, sizeof(u));\n"
"    bits_or(&u, &delta, \"AIF widen frontier\");\n"
"\n"
"    IntVec work;\n"
"    memset(&work, 0, sizeof(work));\n"
"    bits_to_vec(&delta, &vec_val);\n"
"    for (int i = 0; i < vec_val.len; i++) vec_push(&work, vec_val.v[i], \"AIF widen work\");\n"
"\n"
"    while (work.len > 0) {\n"
"        int s = work.v[--work.len];\n"
"        bits_to_vec(&succ[s], &vec_own);\n"
"        for (int i = 0; i < vec_own.len; i++) {\n"
"            if (bits_set(&u, vec_own.v[i], \"AIF widen frontier\")) {\n"
"                vec_push(&work, vec_own.v[i], \"AIF widen work\");\n"
"            }\n"
"        }\n"
"    }\n"
"\n"
"    widen_sites(&u);\n"
"\n"
"    free(work.v);\n"
"    bits_free(&u);\n"
"    for (int s = 0; s < site_count; s++) bits_free(&succ[s]);\n"
"    free(succ);\n"
"}\n"
"\n"
"// Whether this site's facts were raised by the widening rather than inferred.\n"
"// SPEC 6.2 marks exactly those records budget-exhausted; the rest of a truncated\n"
"// build carries facts that converged and are as good as any other build's.\n"
"int aif_site_widened(int id) {\n"
"    if (id < 0 || id >= site_count) return 0;\n"
"    return bits_test(&widened, id);\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Tier derivation (SPEC 4.2)\n"
"//\n"
"// Here rather than in Prismio because the first clause needs defscope(s), and\n"
"// the escape encoding that makes that comparison a single integer test is this\n"
"// file's private business. The derivation itself is the spec's, clause for\n"
"// clause, first match wins.\n"
"//\n"
"// Theta_stack is approximated by field count: at this stage the frontend has no\n"
"// layout, so a byte threshold is not available. SPEC 4.2 requires the threshold\n"
"// be documented by the implementation -- it is emitted in the manifest header.\n"
"//\n"
"// T4a is unreachable by construction: the language has no tasks, so the thread\n"
"// affinity domain is vacuous and every value is Isolated.\n"
"// ============================================================================\n"
"\n"
"#define AIF_THETA_STACK_FIELDS 8\n"
"#define AIF_THETA_STACK_BYTES 256\n"
"\n"
"#define AIF_THETA_MODE_BYTES  0\n"
"#define AIF_THETA_MODE_FIELDS 1\n"
"\n"
"#define AIF_T0  0\n"
"#define AIF_T1  1\n"
"#define AIF_T2  2\n"
"#define AIF_T3  3\n"
"#define AIF_T4B 4\n"
"\n"
"// Which Theta_stack to apply. Bytes is the real threshold and the default;\n"
"// fields is the prototype's approximation (its A5), kept switchable because the\n"
"// oracle reads a JSON dump with no layout in it and cannot compute the other.\n"
"// A comparison against the oracle therefore runs in fields mode -- otherwise the\n"
"// two would differ on the T0/T1 split alone and the differential test would stop\n"
"// saying anything about the part that matters, which is the inference.\n"
"static int theta_mode = AIF_THETA_MODE_BYTES;\n"
"\n"
"void aif_set_theta_mode(int mode) {\n"
"    theta_mode = (mode == AIF_THETA_MODE_FIELDS) ? AIF_THETA_MODE_FIELDS\n"
"                                                 : AIF_THETA_MODE_BYTES;\n"
"}\n"
"\n"
"int aif_theta_mode(void) { return theta_mode; }\n"
"\n"
"int aif_theta_stack(void) {\n"
"    return (theta_mode == AIF_THETA_MODE_FIELDS) ? AIF_THETA_STACK_FIELDS\n"
"                                                 : AIF_THETA_STACK_BYTES;\n"
"}\n"
"\n"
"// SPEC 4.2 requires the size be *statically known* as well as under the\n"
"// threshold. A struct whose size the frontend never computed is not known, and\n"
"// unknown must not read as small.\n"
"static int fits_on_stack(const Site* s) {\n"
"    if (theta_mode == AIF_THETA_MODE_FIELDS) {\n"
"        return s->nfields <= AIF_THETA_STACK_FIELDS;\n"
"    }\n"
"    return s->bytes > 0 && s->bytes <= AIF_THETA_STACK_BYTES;\n"
"}\n"
"\n"
"// The cheapest tier the converged facts permit. This is where SPEC 3's ladder\n"
"// becomes a decision, and the clauses are ordered so the first match wins.\n"
"static int derived_tier(const Site* s) {\n"
"    // in_container joins no_stack here for the same reason it sits next to it in\n"
"    // the drop predicate: the container reclaims its elements, and a frame slot is\n"
"    // not something a deallocator can take. Reachable whenever the container and\n"
"    // the element share a scope, which keeps E at that scope and every other T0\n"
"    // conjunct satisfied.\n"
"    if (s->E == s->scope && s->A <= AIF_A_BORROWED\n"
"        && s->kind == AIF_K_STRUCT && fits_on_stack(s)\n"
"        && !s->no_stack && !s->in_container) {\n"
"        return AIF_T0;\n"
"    }\n"
"    if (s->E != AIF_E_CALLER && s->E != AIF_E_GLOBAL) return AIF_T1;\n"
"    if (s->A <= AIF_A_BORROWED) return AIF_T2;\n"
"    if (s->C == AIF_C_ACYCLIC) return AIF_T3;\n"
"    return AIF_T4B;\n"
"}\n"
"\n"
"int aif_tier_of(int id) {\n"
"    if (id < 0 || id >= site_count) return AIF_T4B;\n"
"    Site* s = &sites[id];\n"
"    // SPEC 5.4: a honoured pin freezes the tier, and everything downstream --\n"
"    // codegen, the drop predicate, the arena test -- has to read the frozen one\n"
"    // or they would disagree with the manifest about what was built.\n"
"    if (s->pin_verdict == AIF_PIN_HONOURED) return s->pin_tier;\n"
"    return derived_tier(s);\n"
"}\n"
"\n"
"// SPEC 5.4, after convergence. The pin derives nothing and seeds nothing; it\n"
"// constrains the output, so this runs once the facts are final.\n"
"//\n"
"// SPEC's pseudocode has four branches and the middle one -- \"the facts permit\n"
"// the pinned tier but the solver did not reach it\" -- is **vacuous here**, and\n"
"// saying why matters more than the code. derived_tier returns the cheapest tier\n"
"// its clauses admit, and the clauses read the facts directly; there is no search\n"
"// that could settle above its own optimum. An implementation whose tier\n"
"// assignment was a separate optimisation would need that branch. This one cannot\n"
"// enter it, so a pin below the derived tier is refuted rather than rescued.\n"
"void aif_check_pins(int converged) {\n"
"    for (int i = 0; i < site_count; i++) {\n"
"        Site* s = &sites[i];\n"
"        if (s->pin_tier < 0) continue;\n"
"\n"
"        int derived = derived_tier(s);\n"
"        if (s->pin_tier >= derived) {\n"
"            s->pin_verdict = AIF_PIN_HONOURED;\n"
"        } else if (converged) {\n"
"            s->pin_verdict = AIF_PIN_REFUTED;\n"
"        } else {\n"
"            // SPEC 5.4.2: unproven is not disproven. Failing here would punish\n"
"            // the programmer for the budget, which SPEC 1 forbids. The tier is\n"
"            // kept so the warning can name what was asked for; only the verdict\n"
"            // decides whether aif_tier_of uses it, and this one does not.\n"
"            s->pin_verdict = AIF_PIN_UNPROVEN;\n"
"        }\n"
"    }\n"
"}\n"
"\n"
"int aif_site_pin_verdict(int id) {\n"
"    if (id < 0 || id >= site_count) return AIF_PIN_NONE;\n"
"    return sites[id].pin_verdict;\n"
"}\n"
"\n"
"int aif_site_pin_tier(int id) {\n"
"    if (id < 0 || id >= site_count) return -1;\n"
"    return sites[id].pin_tier;\n"
"}\n"
"\n"
"// The tier the facts would have given, so a refuted pin's diagnostic can say\n"
"// what the analysis actually proved instead of just refusing.\n"
"int aif_site_derived_tier(int id) {\n"
"    if (id < 0 || id >= site_count) return AIF_T4B;\n"
"    return derived_tier(&sites[id]);\n"
"}\n"
"\n"
"int aif_site_alias_axiom(int id) {\n"
"    if (id < 0 || id >= site_count) return 0;\n"
"    return sites[id].alias_axiom;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Minimal cause (INFERENCE 5.6, SPEC 6.3)\n"
"//\n"
"// Walk the derivation backward from a site through maximal contributors until a\n"
"// root -- an allocation, an axiom, or a rule with no incoming site. The result\n"
"// is the witness path SPEC 6.3 prints under \"minimal cause\", innermost edge\n"
"// first, which is the order it reads in: the change, then what made the change\n"
"// matter.\n"
"//\n"
"// Which domain to walk is decided by the tier, and that mapping is the reason\n"
"// the two are kept separately. A T1 -> T2 move is an *escape* question and a\n"
"// T2 -> T3 move is an *aliasing* one; showing the E path for a value that lost\n"
"// its tier to sharing would be a confident answer to the wrong question.\n"
"// ============================================================================\n"
"\n"
"#define AIF_CAUSE_MAX 32\n"
"\n"
"static int cause_site[AIF_CAUSE_MAX];\n"
"static int cause_rule[AIF_CAUSE_MAX];\n"
"static int cause_value[AIF_CAUSE_MAX];\n"
"static int cause_file[AIF_CAUSE_MAX];\n"
"static int cause_line[AIF_CAUSE_MAX];\n"
"static int cause_col[AIF_CAUSE_MAX];\n"
"static int cause_len;\n"
"static int cause_domain;    // 0 = escape, 1 = aliasing\n"
"\n"
"// Which fact cost this site its tier, and therefore which derivation explains\n"
"// it.\n"
"//\n"
"// The order matters and is the reverse of the tier clauses'. A site is asked\n"
"// about because its tier is worse than someone wanted, so the interesting fact\n"
"// is the *last* one that was binding, not the first. Aliasing is checked before\n"
"// escape because A > Borrowed is what separates T3 from T2: a T3 record whose E\n"
"// is also Caller would otherwise be explained by the escape that only got it as\n"
"// far as T2, which is a confident answer to the wrong question.\n"
"//\n"
"// T4b is cyclicity, which is derived from A and the type graph rather than\n"
"// propagated, so it reports the aliasing path too -- that is where its own\n"
"// witness would start.\n"
"int aif_cause_domain_for(int id) {\n"
"    if (id < 0 || id >= site_count) return 0;\n"
"    Site* s = &sites[id];\n"
"    if (s->A > AIF_A_BORROWED) return 1;                          // aliasing\n"
"    return 0;                                                     // escape\n"
"}\n"
"\n"
"// Builds the path and returns its length. The caller reads it back edge by edge;\n"
"// one buffer is enough because a diff explains one record at a time.\n"
"int aif_cause_build(int id, int domain) {\n"
"    cause_len = 0;\n"
"    cause_domain = domain;\n"
"    if (id < 0 || id >= site_count || !deriv_e || !deriv_a) return 0;\n"
"\n"
"    Deriv* d = domain == 1 ? deriv_a : deriv_e;\n"
"    int cur = id;\n"
"    for (int hops = 0; hops < AIF_CAUSE_MAX; hops++) {\n"
"        cause_site[cause_len]  = cur;\n"
"        cause_rule[cause_len]  = d[cur].rule;\n"
"        cause_value[cause_len] = d[cur].value;\n"
"        cause_file[cause_len]  = d[cur].file;\n"
"        cause_line[cause_len]  = d[cur].line;\n"
"        cause_col[cause_len]   = d[cur].col;\n"
"        cause_len++;\n"
"\n"
"        int next = d[cur].from;\n"
"        if (next < 0 || next >= site_count) break;   // a root: nothing fed it\n"
"        // The derivation is a DAG by construction -- a fact only ever rises, so\n"
"        // an edge always points at a site that reached its value earlier -- but\n"
"        // a cap costs nothing and turns a bug here into a truncated explanation\n"
"        // rather than a hang.\n"
"        int seen = 0;\n"
"        for (int i = 0; i < cause_len; i++) {\n"
"            if (cause_site[i] == next) { seen = 1; break; }\n"
"        }\n"
"        if (seen) break;\n"
"        cur = next;\n"
"    }\n"
"    return cause_len;\n"
"}\n"
"\n"
"int aif_cause_len(void)          { return cause_len; }\n"
"int aif_cause_site(int i)        { return (i < 0 || i >= cause_len) ? -1 : cause_site[i]; }\n"
"int aif_cause_rule(int i)        { return (i < 0 || i >= cause_len) ? -1 : cause_rule[i]; }\n"
"int aif_cause_value(int i)       { return (i < 0 || i >= cause_len) ? -1 : cause_value[i]; }\n"
"int aif_cause_file(int i)        { return (i < 0 || i >= cause_len) ? 0 : cause_file[i]; }\n"
"int aif_cause_line(int i)        { return (i < 0 || i >= cause_len) ? 0 : cause_line[i]; }\n"
"int aif_cause_col(int i)         { return (i < 0 || i >= cause_len) ? 0 : cause_col[i]; }\n"
"\n"
"// The E value an edge raised to, spelled the way the manifest spells a scope.\n"
"// Region ids are per-function and meaningless outside one, so a scope reports as\n"
"// its depth rather than its id -- what a reader needs is \"an enclosing scope\",\n"
"// not which array slot it occupies.\n"
"const char* aif_escape_name(int value) {\n"
"    if (value == AIF_E_CALLER) return \"Caller\";\n"
"    if (value == AIF_E_GLOBAL) return \"Global\";\n"
"    return \"Region\";\n"
"}\n"
"\n"
"const char* aif_alias_name(int value) {\n"
"    if (value <= AIF_A_UNIQUE) return \"Unique\";\n"
"    if (value <= AIF_A_BORROWED) return \"Borrowed\";\n"
"    return \"Shared\";\n"
"}\n"
"\n"
"// SPEC 6.3 prints the rule that fired on each edge, because that is what makes\n"
"// a repair derivable: breaking the edge restores the tier, and the rule says\n"
"// what breaking it would mean.\n"
"const char* aif_rule_name(int rule) {\n"
"    if (rule == AIF_CON_BIND)           return \"E-BIND\";\n"
"    if (rule == AIF_CON_ARG)            return \"A-CALL\";\n"
"    if (rule == AIF_CON_STORE)          return \"A-STORE\";\n"
"    if (rule == AIF_CON_LIVE_IN)        return \"E-BIND\";\n"
"    if (rule == AIF_CON_OPAQUE)         return \"E-OPAQUE\";\n"
"    if (rule == AIF_CON_RETAIN_IN)      return \"A-RETAIN\";\n"
"    if (rule == AIF_CON_BORROW)         return \"A-CALL\";\n"
"    if (rule == AIF_CON_ESCAPE_CALLER)  return \"E-RETURN\";\n"
"    if (rule == AIF_CON_ESCAPE_GLOBAL)  return \"E-STATIC\";\n"
"    if (rule == AIF_RULE_A_ESCAPE)      return \"A-ESCAPE\";\n"
"    if (rule == AIF_RULE_A_COPY)        return \"A-COPY\";\n"
"    if (rule == AIF_RULE_A_CONTAIN)     return \"A-CONTAIN\";\n"
"    if (rule == AIF_RULE_ALLOC)         return \"ALLOC\";\n"
"    return \"?\";\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Tier lookup by AST node\n"
"//\n"
"// Codegen has to ask \"what tier is the value this expression allocates?\", and\n"
"// the answer has to survive the gap between the two passes. The join key is the\n"
"// node itself: the AIF pass and codegen walk the same in-memory tree in the same\n"
"// process, so the address the parser allocated is a name for the expression that\n"
"// costs nothing to carry and cannot collide.\n"
"//\n"
"// It replaces a file:line:col key, which could: an array literal and its first\n"
"// element start at the same column, and `[str_concat(a,b), ...]` puts a site at\n"
"// each. That key had to resolve a collision by keeping the *highest* tier, since\n"
"// codegen reads T0 as permission to use a stack slot and rounding down there is\n"
"// heap corruption. Nothing rounds now -- one node, one site.\n"
"// ============================================================================\n"
"\n"
"#define AIF_NODE_BUCKETS 8192\n"
"\n"
"typedef struct NodeSite {\n"
"    struct NodeSite* next;\n"
"    const void* node;\n"
"    int site;\n"
"} NodeSite;\n"
"\n"
"static NodeSite* node_buckets[AIF_NODE_BUCKETS];\n"
"\n"
"static unsigned node_hash(const void* p) {\n"
"    uintptr_t v = (uintptr_t)p;\n"
"    v ^= v >> 33;\n"
"    v *= 0xff51afd7ed558ccdull;\n"
"    v ^= v >> 29;\n"
"    return (unsigned)v & (AIF_NODE_BUCKETS - 1);\n"
"}\n"
"\n"
"// One site per allocating expression, so a node that already has one is a bug\n"
"// in the walk rather than a collision to resolve. Recording the first keeps that\n"
"// deterministic if it ever happens.\n"
"void aif_site_note_node(int site, const void* node) {\n"
"    if (site < 0 || site >= site_count || node == NULL) return;\n"
"    unsigned b = node_hash(node);\n"
"    for (NodeSite* n = node_buckets[b]; n; n = n->next) {\n"
"        if (n->node == node) return;\n"
"    }\n"
"    NodeSite* n = (NodeSite*)xmalloc(sizeof(NodeSite), \"AIF node index\");\n"
"    n->node = node;\n"
"    n->site = site;\n"
"    n->next = node_buckets[b];\n"
"    node_buckets[b] = n;\n"
"}\n"
"\n"
"// -1 when no site was inferred for this node. Codegen must read that as \"no\n"
"// information\" and allocate the way it always did -- which is what makes SPEC\n"
"// 7.1's zero-analysis build behaviourally identical rather than merely intended\n"
"// to be.\n"
"int aif_tier_at_node(const void* node) {\n"
"    if (node == NULL) return -1;\n"
"    for (NodeSite* n = node_buckets[node_hash(node)]; n; n = n->next) {\n"
"        if (n->node == node) return aif_tier_of(n->site);\n"
"    }\n"
"    return -1;\n"
"}\n"
"\n"
"// Level 2's question: may the value this node allocates be freed when the scope\n"
"// that allocated it exits?\n"
"//\n"
"// Two things have to hold, and the analysis supplies only one of them.\n"
"//\n"
"// The escape must bottom at that scope -- the same test the T0 clause opens\n"
"// with, and the reason the declaring-scope fix in the escape module had to be\n"
"// right. The tier alone does not answer it: T1 says \"some region\", which may be\n"
"// an enclosing scope if the value was also bound further out, and freeing at the\n"
"// inner exit would then be a use-after-free rather than a leak.\n"
"//\n"
"// The *language* must also guarantee a single owner, which is what\n"
"// site_is_move_only reports. Without it there is nothing to stop a second\n"
"// binding holding the same value, and a free at one binding's scope exit is a\n"
"// double free through the other. Today that admits structs only; it widens on\n"
"// its own when SPEC 11 item 10's affine collections land, which is what makes\n"
"// this the change Level 4 pays off rather than Level 2.\n"
"// The innermost scope at or above this one that has an arena, or -1.\n"
"//\n"
"// \"Has an arena\" is a `region` statement (which pins one) or a scope the cost\n"
"// model chose (LAYOUT 7.1). Both are the same thing to every question below:\n"
"// what matters is where the bump allocator that would serve this site lives.\n"
"static int enclosing_region(int scope) {\n"
"    for (int s = scope; s >= 0; s = scopes[s].parent) {\n"
"        if (scopes[s].arena) return s;\n"
"    }\n"
"    return -1;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Automatic arena placement (LAYOUT 7.1)\n"
"//\n"
"//     ArenaBenefit(s) = allocs_in(s)\302\267(\316\261_T2 \342\210\222 \316\261_T1) \342\210\222 entries(s)\302\267arenaSetupCost\n"
"//\n"
"// Every scope is already an implicit region (SPEC 4.1), so the question is not\n"
"// which scopes *could* have an arena but which ones are worth the setup. Both\n"
"// inputs are supposed to come from an access profile; there is no profiler, so\n"
"// they are estimated statically and the estimate is stated rather than hidden:\n"
"//\n"
"//   entries(s)     factors out. It multiplies both terms once `allocs_in` is\n"
"//                  written as \"allocations per entry of s\", so the *sign* of the\n"
"//                  benefit -- which is the only thing the decision reads -- does\n"
"//                  not depend on it. That is why no loop-trip estimate above s\n"
"//                  is needed, and it is the reason to write the model this way.\n"
"//   allocs_in(s)   per entry: one per site the arena would serve, weighted by\n"
"//                  AIF_LOOP_ITERS for each loop between the site and s, since a\n"
"//                  site in a loop inside s allocates many times per entry.\n"
"//\n"
"// Placement is greedy innermost-first, which needs no separate nesting rule.\n"
"// A site can only be served by an arena its escape bottoms at or below, so an\n"
"// inner arena takes exactly the values that die earlier -- LAYOUT's condition\n"
"// for an inner arena being worth it, satisfied by construction rather than by a\n"
"// heuristic. Whatever the inner one cannot take, the next one out sees.\n"
"//\n"
"// Ties break by scope id, which is creation order and therefore node order\n"
"// (LAYOUT 7.1 last line).\n"
"// ============================================================================\n"
"\n"
"#define AIF_ALPHA_T1        3     // LAYOUT 4: allocation cycles at T1 (bump)\n"
"#define AIF_ALPHA_T2        90    //           and at T2 (a general allocator)\n"
"#define AIF_ARENA_SETUP    40     // LAYOUT 4: ~one block acquisition plus reset\n"
"\n"
"// Loops between `inner` and its ancestor `outer`, or 0 if unrelated.\n"
"static int loops_between(int inner, int outer) {\n"
"    if (inner < 0 || outer < 0) return 0;\n"
"    int d = scopes[inner].loop_depth - scopes[outer].loop_depth;\n"
"    return d > 0 ? d : 0;\n"
"}\n"
"\n"
"static long weight_of(int site_scope, int arena_scope) {\n"
"    long w = 1;\n"
"    int loops = loops_between(site_scope, arena_scope);\n"
"    // Capped so a deeply nested site cannot overflow the benefit; anything past\n"
"    // the cap is already far above the threshold and the exact value is noise.\n"
"    if (loops > 6) loops = 6;\n"
"    for (int i = 0; i < loops; i++) w *= AIF_LOOP_ITERS;\n"
"    return w;\n"
"}\n"
"\n"
"static int is_ancestor_or_self(int anc, int s) {\n"
"    for (int p = s; p >= 0; p = scopes[p].parent) {\n"
"        if (p == anc) return 1;\n"
"    }\n"
"    return 0;\n"
"}\n"
"\n"
"// Would an arena at `cand` serve this site, given the arenas chosen so far?\n"
"static int arena_would_serve(int site_id, int cand) {\n"
"    Site* s = &sites[site_id];\n"
"    if (aif_tier_of(site_id) != AIF_T1) return 0;   // T0 has the frame already\n"
"    if (s->no_stack) return 0;                      // an explicit drop frees it\n"
"    if (s->kind == AIF_K_LIST) return 0;            // grows past its site; see below\n"
"    if (s->E < 0) return 0;                         // Caller or Global\n"
"    if (!is_ancestor_or_self(cand, s->scope)) return 0;\n"
"    if (scope_lca(s->E, cand) != cand) return 0;    // outlives the arena\n"
"    // A nearer arena already claimed it. Innermost-first placement means any\n"
"    // scope strictly between the site and `cand` that has one gets it first.\n"
"    for (int p = s->scope; p >= 0 && p != cand; p = scopes[p].parent) {\n"
"        if (scopes[p].arena) return 0;\n"
"    }\n"
"    return 1;\n"
"}\n"
"\n"
"// Chosen after the fixed point, because every input is a converged fact.\n"
"void aif_place_arenas(void) {\n"
"    // Innermost-first: a higher scope id is a scope created later, and the walk\n"
"    // creates a parent before its children, so descending id visits every child\n"
"    // before its parent.\n"
"    for (int s = scope_count - 1; s >= 0; s--) {\n"
"        if (scopes[s].arena) continue;              // pinned by `region`\n"
"        if (scopes[s].node == NULL) continue;       // no block for codegen to bracket\n"
"\n"
"        // Inside a `region`, the region decides. SPEC 5.2 makes `region` a pin on\n"
"        // this decision, and a pin that the cost model can undercut by placing a\n"
"        // tighter arena two lines in is not one -- the named region would serve\n"
"        // nothing and the manifest would stop being able to say which block owns\n"
"        // a value. A programmer who wants per-iteration reclamation inside a\n"
"        // region writes a nested `region`, which test_44's breaks_out does.\n"
"        //\n"
"        // Only *explicit* ancestors count, and the traversal is what makes that\n"
"        // true for free: innermost-first means an ancestor's flag is set here\n"
"        // only if `region` set it, never if this pass did.\n"
"        int pinned_above = 0;\n"
"        for (int p = scopes[s].parent; p >= 0; p = scopes[p].parent) {\n"
"            if (scopes[p].arena) { pinned_above = 1; break; }\n"
"        }\n"
"        if (pinned_above) continue;\n"
"\n"
"        long served = 0;\n"
"        for (int k = 0; k < site_count; k++) {\n"
"            if (arena_would_serve(k, s)) served += weight_of(sites[k].scope, s);\n"
"        }\n"
"        if (served == 0) continue;\n"
"\n"
"        long benefit = served * (AIF_ALPHA_T2 - AIF_ALPHA_T1) - (long)AIF_ARENA_SETUP;\n"
"        if (benefit > 0) scopes[s].arena = 1;\n"
"    }\n"
"}\n"
"\n"
"// ============================================================================\n"
"// REQUIREMENTS 19 -- memory budget reporting\n"
"//\n"
"// The arena high-water mark, statically estimated. Fixed budgets are a hard\n"
"// constraint on console targets, and arenas are what make one tractable: a\n"
"// region's peak is the sum of what it serves, and the peak for a program is the\n"
"// largest sum along a **root-to-leaf chain** of arena scopes -- not the total,\n"
"// which would add sibling regions that are never live at the same time.\n"
"//\n"
"// Weighted by AIF_LOOP_ITERS per enclosing loop, the same estimator automatic\n"
"// placement uses for allocs_in(s), so the two cannot disagree about how much a\n"
"// scope serves.\n"
"//\n"
"// **It is an estimate, and the manifest says which part it cannot see.** A\n"
"// struct's size is known from its layout; a string's is its length, which is a\n"
"// run-time value. Sites whose size is not statically known are counted\n"
"// separately rather than guessed at, because a fabricated per-string constant\n"
"// would make a budget gate that passes or fails on a number nobody computed.\n"
"// ============================================================================\n"
"\n"
"long aif_arena_high_water(void) {\n"
"    if (scope_count <= 0) return 0;\n"
"    long* own = (long*)xcalloc((size_t)scope_count, sizeof(long), \"AIF arena bytes\");\n"
"\n"
"    for (int s = 0; s < scope_count; s++) {\n"
"        if (!scopes[s].arena) continue;\n"
"        long b = 0;\n"
"        for (int k = 0; k < site_count; k++) {\n"
"            if (!arena_would_serve(k, s)) continue;\n"
"            b += (long)sites[k].bytes * weight_of(sites[k].scope, s);\n"
"        }\n"
"        own[s] = b;\n"
"    }\n"
"\n"
"    long peak = 0;\n"
"    for (int s = 0; s < scope_count; s++) {\n"
"        if (!scopes[s].arena) continue;\n"
"        long chain = 0;\n"
"        for (int p = s; p >= 0; p = scopes[p].parent) {\n"
"            if (scopes[p].arena) chain += own[p];\n"
"        }\n"
"        if (chain > peak) peak = chain;\n"
"    }\n"
"\n"
"    free(own);\n"
"    return peak;\n"
"}\n"
"\n"
"// What one region's arena serves, for the `pin(N)` gate. Its own scope only:\n"
"// a nested region has its own arena and its own cap.\n"
"static long arena_bytes_of(int scope) {\n"
"    long b = 0;\n"
"    for (int k = 0; k < site_count; k++) {\n"
"        if (!arena_would_serve(k, scope)) continue;\n"
"        b += (long)sites[k].bytes * weight_of(sites[k].scope, scope);\n"
"    }\n"
"    return b;\n"
"}\n"
"\n"
"// REQUIREMENTS 19's gate. A refuted budget is an error for the same reason a\n"
"// refuted `pin` is (SPEC 5.4.1): it is a false assertion about one's own\n"
"// program, not an inference failure, so SPEC 1's invariant is untouched.\n"
"//\n"
"// Returns the number refuted; the frontend prints them.\n"
"int aif_budget_count(void) { return scope_count; }\n"
"\n"
"long aif_scope_budget(int s)     { return (s < 0 || s >= scope_count) ? 0 : scopes[s].budget; }\n"
"long aif_scope_served(int s)     { return (s < 0 || s >= scope_count) ? 0 : arena_bytes_of(s); }\n"
"const char* aif_scope_region(int s) {\n"
"    if (s < 0 || s >= scope_count || scopes[s].region_name < 0) return \"\";\n"
"    return aif_str(scopes[s].region_name);\n"
"}\n"
"int aif_scope_budget_file(int s) { return (s < 0 || s >= scope_count) ? 0 : scopes[s].budget_file; }\n"
"int aif_scope_budget_line(int s) { return (s < 0 || s >= scope_count) ? 0 : scopes[s].budget_line; }\n"
"int aif_scope_budget_col(int s)  { return (s < 0 || s >= scope_count) ? 0 : scopes[s].budget_col; }\n"
"\n"
"// Arena-served sites whose size is not statically known -- strings, whose length\n"
"// is a run-time value. Reported alongside the estimate so the number above is\n"
"// read as covering what it covers.\n"
"int aif_arena_unsized_sites(void) {\n"
"    int n = 0;\n"
"    for (int s = 0; s < scope_count; s++) {\n"
"        if (!scopes[s].arena) continue;\n"
"        for (int k = 0; k < site_count; k++) {\n"
"            if (arena_would_serve(k, s) && sites[k].bytes == 0) n++;\n"
"        }\n"
"    }\n"
"    return n;\n"
"}\n"
"\n"
"// 1 when this BLOCK node opens an arena the cost model chose. A `region`\n"
"// statement is excluded: codegen already brackets that one, and bracketing it\n"
"// twice would push two arenas and pop only the inner one at an early exit.\n"
"int aif_auto_arena_at_node(const void* node) {\n"
"    if (node == NULL) return 0;\n"
"    for (int s = 0; s < scope_count; s++) {\n"
"        if (scopes[s].node != node) continue;\n"
"        if (scopes[s].region_name >= 0) return 0;\n"
"        return scopes[s].arena;\n"
"    }\n"
"    return 0;\n"
"}\n"
"\n"
"// SPEC 5.2: may this value come from the enclosing region's arena?\n"
"//\n"
"// Only if it dies no later than that region does. The escape is a scope, and\n"
"// the arena is released when its own scope exits, so the test is \"is the region\n"
"// an ancestor-or-self of the escape scope\" -- lca(E, r) == r.\n"
"//\n"
"// The nesting case is the one that makes this more than a lexical question:\n"
"//\n"
"//     region outer { let mut x = ...; region inner { x = Foo{} } use(x) }\n"
"//\n"
"// `Foo{}` is lexically inside `inner`, but its escape is `outer`'s scope, and\n"
"// inner's arena is gone by `use(x)`. lca(outer, inner) is outer, not inner, so\n"
"// this correctly declines and the value goes to the heap.\n"
"int aif_arena_at_node(const void* node) {\n"
"    if (node == NULL) return 0;\n"
"    for (NodeSite* n = node_buckets[node_hash(node)]; n; n = n->next) {\n"
"        if (n->node != node) continue;\n"
"        Site* s = &sites[n->site];\n"
"        if (aif_tier_of(n->site) != AIF_T1) return 0;   // T0 has the frame already\n"
"        // The same reason the T0 clause asks: an arena pointer is not a thing a\n"
"        // deallocator can take, and `drop(x)` emits one unconditionally -- the\n"
"        // source, not the model, decided when that value dies. Latent while\n"
"        // arenas only appeared where a `region` was written; automatic placement\n"
"        // (LAYOUT 7.1) puts one around almost every explicit drop.\n"
"        if (s->no_stack) return 0;\n"
"        // The container frees its elements through the deallocator, and a pointer\n"
"        // into the middle of an arena chunk is not one it can take. Same exclusion\n"
"        // as no_stack above, one owner further out.\n"
"        if (s->in_container) return 0;\n"
"        // An arena serves values allocated once. A list is not one: list_push\n"
"        // reallocates the element block long after this site returned, at\n"
"        // whatever arena depth the program happens to be at then -- so the block\n"
"        // would be tied to a region the list can outlive, and freeing the old\n"
"        // block would hand arena memory to the deallocator. Lists stay on the\n"
"        // heap and are reclaimed by list_release at their binding's scope exit,\n"
"        // which is also what keeps the Level 2 drop path exercised.\n"
"        if (s->kind == AIF_K_LIST) return 0;\n"
"        int r = enclosing_region(s->scope);\n"
"        if (r < 0) return 0;\n"
"        if (s->E < 0) return 0;                         // Caller or Global\n"
"        return scope_lca(s->E, r) == r ? 1 : 0;\n"
"    }\n"
"    return 0;\n"
"}\n"
"\n"
"// The region name to report for this site, or \"\" when it is not arena-placed.\n"
"// An arena the cost model chose has no name to report -- it is a scope, not a\n"
"// declaration -- so it reports \"auto\", which is what distinguishes it in the\n"
"// manifest from a `region` the programmer pinned.\n"
"const char* aif_region_name_at_site(int id) {\n"
"    if (id < 0 || id >= site_count) return \"\";\n"
"    if (aif_tier_of(id) != AIF_T1) return \"\";\n"
"    if (sites[id].no_stack) return \"\";\n"
"    if (sites[id].in_container) return \"\";\n"
"    if (sites[id].kind == AIF_K_LIST) return \"\";\n"
"    int r = enclosing_region(sites[id].scope);\n"
"    if (r < 0 || sites[id].E < 0) return \"\";\n"
"    if (scope_lca(sites[id].E, r) != r) return \"\";\n"
"    if (scopes[r].region_name < 0) return \"auto\";\n"
"    return aif_str(scopes[r].region_name);\n"
"}\n"
"\n"
"// 1 when this site's arena was pinned by a `region` statement rather than chosen\n"
"// by the cost model. SPEC 6.2's `origin` column distinguishes them: a pin that\n"
"// stops being honoured is a gate regression, an inferred placement moving is not.\n"
"int aif_site_arena_is_pinned(int id) {\n"
"    if (id < 0 || id >= site_count) return 0;\n"
"    int r = enclosing_region(sites[id].scope);\n"
"    if (r < 0) return 0;\n"
"    return scopes[r].region_name >= 0 ? 1 : 0;\n"
"}\n"
"\n"
"static int site_in_released_field(int s);\n"
"\n"
"int aif_frees_at_scope_node(const void* node) {\n"
"    if (node == NULL) return 0;\n"
"    // An arena releases in bulk when its region exits. Freeing one of its\n"
"    // objects individually would hand a pointer into the middle of a chunk to\n"
"    // the deallocator -- so a value the arena serves is never on a drop list.\n"
"    if (aif_arena_at_node(node)) return 0;\n"
"    for (NodeSite* n = node_buckets[node_hash(node)]; n; n = n->next) {\n"
"        if (n->node != node) continue;\n"
"        Site* s = &sites[n->site];\n"
"        if (s->E != s->scope) return 0;\n"
"        if (!site_is_move_only(s)) return 0;\n"
"        // An array literal lowers to ir_array_alloca -- frame storage, like T0\n"
"        // below, so there is nothing here for a deallocator to take. This is the\n"
"        // one place the language and site_is_move_only disagree: affine\n"
"        // collections make arrays move-only in the model (and in the oracle), and\n"
"        // types.psm deliberately does not, because an affine value with no\n"
"        // allocation behind it buys the aliasing rule and costs a `drop(arr)`\n"
"        // that frees a stack pointer.\n"
"        if (s->kind == AIF_K_ARRAY) return 0;\n"
"        // An explicit `drop` already frees it; a scope drop as well is a double\n"
"        // free. Same flag that bars T0, and for the same reason -- it records\n"
"        // that the source, not the model, decides when this value dies.\n"
"        if (s->no_stack) return 0;\n"
"        // A container took ownership, so the container's teardown is the release\n"
"        // point and this binding is not one. Reachable only when the two share a\n"
"        // scope -- otherwise the container's escape already lifted E past it and\n"
"        // the test above declined -- and in that case the element would otherwise\n"
"        // be freed here *and* at the teardown, newest binding first.\n"
"        if (s->in_container) return 0;\n"
"        // The same rule one level out: a struct field the type now releases is\n"
"        // this value's release point, so its binding is not. See\n"
"        // site_in_released_field for why the E test above does not already cover\n"
"        // it.\n"
"        if (site_in_released_field(n->site)) return 0;\n"
"        return aif_tier_of(n->site) == AIF_T0 ? 0 : 1;   // T0 storage is the frame\n"
"    }\n"
"    return 0;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Ownership inside containers\n"
"//\n"
"// A container teardown is a release point, and the container has to be told what\n"
"// its elements are: probing a pointer's header to find out would be reading\n"
"// memory in front of a pointer this compilation did not allocate, which is the\n"
"// same unsound move that bars refcounting an OPAQUE site.\n"
"//\n"
"// So the disposition is decided here, once, and codegen stamps it on the\n"
"// container at construction. It is a property of the *container site*, not of the\n"
"// element, because that is the only granularity a teardown loop has: one call per\n"
"// element, all elements alike.\n"
"//\n"
"// Which means a mixed container has no answer. If one element wants a free and\n"
"// another wants a decrement, neither is right for both and the honest outcome is\n"
"// to reclaim nothing -- today's behaviour, and a leak rather than a wrong free.\n"
"// The same goes for anything the deallocator cannot take: an array element is\n"
"// frame storage and an opaque one was never ours.\n"
"// ============================================================================\n"
"\n"
"#define AIF_ELEM_NONE   0\n"
"#define AIF_ELEM_OBJECT 1   // the deallocator\n"
"#define AIF_ELEM_LIST   2   // list_release, which is two allocations\n"
"#define AIF_ELEM_RC     3   // Level 5: a decrement, and the last holder frees\n"
"#define AIF_ELEM_TYPED  4   // the type's generated release -- struct-field ownership\n"
"#define AIF_ELEM_CYCLE  5   // T4b: a decrement, and a non-zero result buffers a candidate\n"
"\n"
"// AIF Level 5. Whether this site is allocated with a reference count.\n"
"//\n"
"// Three exclusions, and each is a different kind of \"we did not allocate this\":\n"
"//\n"
"//   * OPAQUE -- the pointer came back from a function this compilation cannot\n"
"//     see. There is no header in front of it. This is the exclusion that matters,\n"
"//     because it covers all 37 of the compiler's own T3 sites.\n"
"//   * STRING and LIST -- allocated inside lang_runtime.c, past the seam, so the\n"
"//     site cannot choose its own allocator. The same asymmetry Level 4 hit with\n"
"//     the arena; a hint would work here too and is not this level.\n"
"//   * ARRAY -- frame storage.\n"
"//\n"
"// And a positive requirement: the site must be in a container. A count is a count\n"
"// of container edges, so a value in none of them would be born at zero, never\n"
"// retained, never released, and pay 16 bytes of header for nothing.\n"
"static int site_is_rc(const Site* s, int tier) {\n"
"    if (tier != AIF_T3) return 0;\n"
"    if (s->kind != AIF_K_STRUCT) return 0;\n"
"    if (s->no_stack) return 0;              // an explicit drop needs a plain free\n"
"    return s->in_container;\n"
"}\n"
"\n"
"// AIF T4b. The same shape one tier up, and the exclusions are the same: the\n"
"// object must be one this compilation allocated, so there is a header in front\n"
"// of it, and it must be in a container, because a container edge is the only\n"
"// count this compiler both increments and decrements.\n"
"//\n"
"// The extra requirement over T3 is structural rather than a policy choice: a\n"
"// T4b site is one whose type is *not* acyclic (SPEC 4.2's C = MaybeCyclic), so\n"
"// there is an SCC to walk. Without one there are no cyclic children and the\n"
"// collector would buffer candidates it can never reclaim.\n"
"static int site_is_cyclic(const Site* s, int tier) {\n"
"    if (tier != AIF_T4B) return 0;\n"
"    if (s->kind != AIF_K_STRUCT) return 0;\n"
"    if (s->no_stack) return 0;\n"
"    if (s->type_acyclic) return 0;\n"
"    return s->in_container;\n"
"}\n"
"\n"
"int aif_site_is_cyclic(int id) {\n"
"    if (id < 0 || id >= site_count) return 0;\n"
"    return site_is_cyclic(&sites[id], aif_tier_of(id));\n"
"}\n"
"\n"
"int aif_cycle_at_node(const void* node) {\n"
"    if (node == NULL) return 0;\n"
"    for (NodeSite* n = node_buckets[node_hash(node)]; n; n = n->next) {\n"
"        if (n->node != node) continue;\n"
"        return site_is_cyclic(&sites[n->site], aif_tier_of(n->site));\n"
"    }\n"
"    return 0;\n"
"}\n"
"\n"
"static int type_releases_of(int nominal);\n"
"\n"
"static int elem_disposition_of(const Site* s, int tier) {\n"
"    if (s->kind == AIF_K_ARRAY || s->kind == AIF_K_OPAQUE) return AIF_ELEM_NONE;\n"
"    if (site_is_rc(s, tier)) return AIF_ELEM_RC;\n"
"    if (site_is_cyclic(s, tier)) return AIF_ELEM_CYCLE;\n"
"    // T0 is the frame, and a T3 or T4b site the two predicates above declined has\n"
"    // no header to decrement.\n"
"    if (tier != AIF_T1 && tier != AIF_T2) return AIF_ELEM_NONE;\n"
"    if (s->no_stack) return AIF_ELEM_NONE;      // an explicit drop already frees it\n"
"    if (s->kind == AIF_K_LIST) return AIF_ELEM_LIST;\n"
"    // Struct-field ownership. Handing a struct with owned fields to the plain\n"
"    // deallocator frees the object and leaks everything it owns -- which is g3's\n"
"    // entire residue: 1365 Nodes, three owned struct fields each, 4095 leaks.\n"
"    if (s->kind == AIF_K_STRUCT && type_releases_of(nominal_find_id(s->type))) {\n"
"        return AIF_ELEM_TYPED;\n"
"    }\n"
"    return AIF_ELEM_OBJECT;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Struct-field ownership\n"
"//\n"
"// The sibling of container ownership, and deliberately not the same mechanism.\n"
"// A container is *told* its element disposition at construction because its\n"
"// contents are dynamic -- the runtime is the only thing that knows how many\n"
"// elements there are or when the last one arrived. A struct's fields are known\n"
"// statically, right here in the nominal registry, so the answer is a **function\n"
"// generated per type** with one release per owned field emitted in line.\n"
"//\n"
"// Two consequences follow from that difference, and both are the point:\n"
"//\n"
"//   * **The disposition is per field, not per type.** A container reclaims\n"
"//     nothing when its elements disagree, because a teardown loop makes one call\n"
"//     for all of them. A generated function has a separate statement per field,\n"
"//     so `World` -- five owned `List`s and an `Int` -- releases the five and\n"
"//     steps over the Int. A single answer for the whole type would have to be\n"
"//     NONE for all six, which is exactly the leak this closes.\n"
"//   * **No runtime word.** The container needs `elem_own` on the object; a struct\n"
"//     needs nothing, because the type is what selects the function.\n"
"//\n"
"// The fact this reads is not new. A struct literal's field initialiser has been\n"
"// a STORE into `key_field(type, field)` since Level 0 -- that is what carries\n"
"// E-STORE and A-STORE -- so the sites that may reach a field are exactly\n"
"// `pt[key_field(type, field)]`. This adds a query, not a rule.\n"
"// ============================================================================\n"
"\n"
"// Lookup without interning. A query after the solve must not add a key: pt is\n"
"// sized to key_count at solve start, so a fresh id would index past it, and a\n"
"// table that grows while it is being read is a table nobody can reason about.\n"
"static int key_find(int kind, int a, int b) {\n"
"    unsigned h = (unsigned)kind * 2654435761u\n"
"               ^ (unsigned)a * 40503u\n"
"               ^ (unsigned)b * 2246822519u;\n"
"    for (KeyNode* n = key_buckets[h & (AIF_KEY_BUCKETS - 1)]; n; n = n->next) {\n"
"        if (n->kind == kind && n->a == a && n->b == b) return n->id;\n"
"    }\n"
"    return -1;\n"
"}\n"
"\n"
"// What release `type.field` needs, or NONE.\n"
"//\n"
"// Agreement over the field's points-to set, for the same reason the container\n"
"// case agrees over its elements: one field holds one pointer, but the analysis\n"
"// may not be able to say which site produced it, and a field that is a `List` on\n"
"// one path and an opaque on another has no single correct release.\n"
"// `List<Token>` -> `List`, on interned ids. The frontend's aif_base_type exists\n"
"// for the same reason field keys are object-insensitive: `list_new()` types as\n"
"// `List<Invalid>` and an annotated field does not, so a raw comparison of the\n"
"// two spellings would reject every container field.\n"
"static int base_type_id(int name) {\n"
"    const char* s = aif_str(name);\n"
"    const char* lt = strchr(s, '<');\n"
"    if (!lt) return name;\n"
"    char buf[128];\n"
"    size_t n = (size_t)(lt - s);\n"
"    if (n >= sizeof(buf)) n = sizeof(buf) - 1;\n"
"    memcpy(buf, s, n);\n"
"    buf[n] = '\\0';\n"
"    return aif_intern(buf);\n"
"}\n"
"\n"
"// Whether releasing this field would re-enter the type that owns it.\n"
"//\n"
"// `struct Node { parent: Node?, children: List<Node> }` is the shape:\n"
"// __aif_release_Node(n) releasing n.parent releases *its* parent, and so on\n"
"// until the stack gives out -- or, worse, around a cycle and back to an object\n"
"// already freed. A statically generated release is for the acyclic part of the\n"
"// type graph by construction, and a cycle is what SPEC's T4b collector is for.\n"
"//\n"
"// **Only reachable once REQUIREMENTS 4 exists.** Before `none` a parent\n"
"// back-reference did not typecheck, which is precisely why CYCLES had nothing to\n"
"// run against.\n"
"static int field_closes_cycle(int owner, int declared_type) {\n"
"    if (owner < 0 || declared_type < 0) return 0;\n"
"    int fid = nominal_find_id(declared_type);\n"
"    if (fid < 0) return 0;\n"
"    if (fid == owner) return 1;\n"
"    return bits_test(&nominals[fid].reaches, owner);\n"
"}\n"
"\n"
"static int field_release_of(int type_name, int field_name, int declared_type) {\n"
"    int key = key_find(AIF_KEY_FIELD, type_name, field_name);\n"
"    if (key < 0 || key >= pt_len) return AIF_ELEM_NONE;\n"
"    if (field_closes_cycle(nominal_find_id(type_name), declared_type)) return AIF_ELEM_NONE;\n"
"\n"
"    int agreed = AIF_ELEM_NONE;\n"
"    for (int s = 0; s < site_count; s++) {\n"
"        if (!bits_test(&pt[key], s)) continue;\n"
"        // **The slot has to hold what it says it holds.** This compiler puns an\n"
"        // ASTNode pointer as `String` and walks node chains through it, so a\n"
"        // `String` field can receive struct sites -- and a release chosen from\n"
"        // the sites alone emits `__aif_release_String`, which is not a function.\n"
"        // That is not a naming bug to paper over: the language and the analysis\n"
"        // genuinely disagree about what is in the slot, and the honest answer is\n"
"        // to reclaim nothing. Same discipline as arrays in\n"
"        // aif_frees_at_scope_node, which decline by kind for the same reason.\n"
"        if (declared_type >= 0 && base_type_id(sites[s].type) != declared_type) {\n"
"            return AIF_ELEM_NONE;\n"
"        }\n"
"        int d = elem_disposition_of(&sites[s], aif_tier_of(s));\n"
"        if (d == AIF_ELEM_NONE) return AIF_ELEM_NONE;\n"
"        if (agreed == AIF_ELEM_NONE) agreed = d;\n"
"        else if (agreed != d) return AIF_ELEM_NONE;\n"
"    }\n"
"    return agreed;\n"
"}\n"
"\n"
"// The declared type of a struct's i-th field, base-named, or -1.\n"
"static int field_declared_type(const Nominal* t, int i) {\n"
"    return t->field_type ? t->field_type[i] : -1;\n"
"}\n"
"\n"
"// -1 not computed, -2 in progress.\n"
"//\n"
"// The in-progress marker is what a self-referential type needs. `struct Node {\n"
"// child: Node }` would otherwise have to know whether Node releases in order to\n"
"// decide whether Node releases. Read as \"does not\", which leaks rather than\n"
"// double-frees -- and a type that reaches itself is C-MAYBE anyway, so it is the\n"
"// cycle collector's problem and not this one's.\n"
"static int* type_releases;\n"
"static int type_releases_cap;\n"
"\n"
"static int type_releases_of(int nominal) {\n"
"    if (nominal < 0 || nominal >= nominal_count) return 0;\n"
"    if (nominals[nominal].is_enum) return 0;\n"
"\n"
"    if (nominal >= type_releases_cap) {\n"
"        int grow = type_releases_cap ? type_releases_cap * 2 : 64;\n"
"        if (grow <= nominal) grow = nominal + 1;\n"
"        type_releases = (int*)xrealloc(type_releases, (size_t)grow * sizeof(int),\n"
"                                       \"AIF type release cache\");\n"
"        for (int i = type_releases_cap; i < grow; i++) type_releases[i] = -1;\n"
"        type_releases_cap = grow;\n"
"    }\n"
"    if (type_releases[nominal] == -2) return 0;\n"
"    if (type_releases[nominal] >= 0) return type_releases[nominal];\n"
"\n"
"    type_releases[nominal] = -2;\n"
"    Nominal* t = &nominals[nominal];\n"
"    int any = 0;\n"
"    for (int i = 0; i < t->nfields && !any; i++) {\n"
"        if (field_release_of(t->name, t->field_name[i], field_declared_type(t, i))\n"
"            != AIF_ELEM_NONE) any = 1;\n"
"    }\n"
"    type_releases[nominal] = any;\n"
"    return any;\n"
"}\n"
"\n"
"int aif_type_releases(const char* name) {\n"
"    return type_releases_of(nominal_find(name));\n"
"}\n"
"\n"
"// ---------------------------------------------------------------------------\n"
"// CYCLES 4 -- the cyclic-edge restriction\n"
"//\n"
"// Every edge of a value-level reference cycle connects two types in one SCC of\n"
"// the type reference graph: an edge x -> y arises from a field of type(x) that\n"
"// can hold a type(y), so the types of a value cycle form a directed cycle in the\n"
"// type graph and therefore lie in one SCC.\n"
"//\n"
"// So a collector that traverses only fields whose type is in the owner's SCC\n"
"// still finds every cycle -- and never *leaves* the skeleton. A Node with two\n"
"// child pointers and six fields of tokens, strings and spans is walked through\n"
"// two edges rather than eight, and the collector never descends into the string\n"
"// graph hanging off it. Those subgraphs are usually far larger than the cyclic\n"
"// skeleton, which is what makes CYCLES 6's work bounds credible.\n"
"// ---------------------------------------------------------------------------\n"
"\n"
"static int same_scc(int a, int b) {\n"
"    if (a < 0 || b < 0) return 0;\n"
"    if (a == b) return bits_test(&nominals[a].reaches, a);   // a non-trivial self-loop\n"
"    return bits_test(&nominals[a].reaches, b) && bits_test(&nominals[b].reaches, a);\n"
"}\n"
"\n"
"// Whether this type lies in a non-trivial SCC. The transitive closure marks a\n"
"// type as reaching itself exactly then, which is also what makes it not acyclic.\n"
"int aif_type_in_cycle(const char* name) {\n"
"    int id = nominal_find(name);\n"
"    if (id < 0 || nominals[id].is_enum) return 0;\n"
"    return bits_test(&nominals[id].reaches, id) ? 1 : 0;\n"
"}\n"
"\n"
"// Whether this field is a cyclic edge, i.e. one the collector traverses.\n"
"int aif_field_is_cyclic(const char* type, const char* field) {\n"
"    int owner = nominal_find(type);\n"
"    if (owner < 0 || nominals[owner].is_enum) return 0;\n"
"    Nominal* t = &nominals[owner];\n"
"    int fname = aif_intern(field);\n"
"    for (int i = 0; i < t->nfields; i++) {\n"
"        if (t->field_name[i] != fname) continue;\n"
"        return same_scc(owner, nominal_find_id(field_declared_type(t, i)));\n"
"    }\n"
"    return 0;\n"
"}\n"
"\n"
"// Whether a store into this field must move a reference count.\n"
"//\n"
"// **Bacon-Rajan requires the count to reflect every reference the traversal\n"
"// walks.** Trial deletion subtracts the internal edges and reads what is left as\n"
"// \"held from outside\"; an edge the collector traverses but nobody ever counted\n"
"// makes that subtraction remove a reference that was never added, and the\n"
"// arithmetic says unreachable for a live object. That is a premature free, and\n"
"// it is what the first build of the collector did -- a segfault on the fixture,\n"
"// not a leak.\n"
"//\n"
"// So a cyclic field is counted, and only when every site that can reach it is\n"
"// one the collector can take. A field mixing a counted object with an opaque or\n"
"// stack one has no correct answer and moves no count, which leaks rather than\n"
"// corrupting.\n"
"int aif_field_is_counted(const char* type, const char* field) {\n"
"    if (!aif_field_is_cyclic(type, field)) return 0;\n"
"    int owner = nominal_find(type);\n"
"    if (owner < 0) return 0;\n"
"    int key = key_find(AIF_KEY_FIELD, nominals[owner].name, aif_intern(field));\n"
"    if (key < 0 || key >= pt_len) return 0;\n"
"\n"
"    int any = 0;\n"
"    for (int s = 0; s < site_count; s++) {\n"
"        if (!bits_test(&pt[key], s)) continue;\n"
"        any = 1;\n"
"        if (!site_is_cyclic(&sites[s], aif_tier_of(s))) return 0;\n"
"    }\n"
"    return any;\n"
"}\n"
"\n"
"// CYCLES 2's headline result, as a number the manifest can print: how many types\n"
"// lie in a non-trivial SCC. Zero means the program cannot leak a cycle and the\n"
"// collector is omitted from the binary entirely -- a property checkable from the\n"
"// type declarations alone, before any inference runs.\n"
"int aif_scc_type_count(void) {\n"
"    int n = 0;\n"
"    for (int i = 0; i < nominal_count; i++) {\n"
"        if (nominals[i].is_enum) continue;\n"
"        if (bits_test(&nominals[i].reaches, i)) n++;\n"
"    }\n"
"    return n;\n"
"}\n"
"\n"
"int aif_t4b_site_count(void) {\n"
"    int n = 0;\n"
"    for (int s = 0; s < site_count; s++) {\n"
"        if (aif_tier_of(s) == AIF_T4B) n++;\n"
"    }\n"
"    return n;\n"
"}\n"
"\n"
"int aif_field_release(const char* type, const char* field) {\n"
"    int id = nominal_find(type);\n"
"    if (id < 0 || nominals[id].is_enum) return AIF_ELEM_NONE;\n"
"    Nominal* t = &nominals[id];\n"
"    int fname = aif_intern(field);\n"
"    for (int i = 0; i < t->nfields; i++) {\n"
"        if (t->field_name[i] != fname) continue;\n"
"        return field_release_of(t->name, fname, field_declared_type(t, i));\n"
"    }\n"
"    return AIF_ELEM_NONE;\n"
"}\n"
"\n"
"// Whether any released field may hold this site.\n"
"//\n"
"// This is the double-free rule `in_container` encodes, one level out. A value\n"
"// stored into a field the type now releases has the struct's teardown as its\n"
"// release point, so its own binding is not one -- otherwise it is freed at the\n"
"// scope exit *and* again when the struct goes.\n"
"//\n"
"// Reachable for the same narrow reason the container case is: normally E-STORE\n"
"// has already raised the value's escape to the struct's, and the `E == scope`\n"
"// test in aif_frees_at_scope_node declines first. It is only when the struct and\n"
"// the field's value share a scope that both tests pass and this one has to say\n"
"// no.\n"
"//\n"
"// Computed once over every (type, field) rather than per site, because the\n"
"// answer depends on the type's fields and not on where the site sits.\n"
"static Bits in_released_field;\n"
"static int in_released_field_done;\n"
"\n"
"// Whether anything actually reclaims a value of this type.\n"
"//\n"
"// **A field is only a release point if its owner has one**, and that is not\n"
"// implied by the owner having a generated release function. A T0 struct lives in\n"
"// the frame: nothing frees it, so nothing runs its release, so its fields are\n"
"// reclaimed by nobody. Barring the field's own binding there does not move the\n"
"// release -- it deletes it.\n"
"//\n"
"// g5_asset_cache is the case, and it cost a 47 -> 2049 regression to find. Its\n"
"// `Scene` is four fields and does not escape `main`, so it takes the T0 clause;\n"
"// the `entities` list stored in it was being freed at main's exit, and barring\n"
"// that on the strength of `Scene`'s release function leaked all 2000 elements.\n"
"static int type_reclaimed_cache_valid;\n"
"static int* type_reclaimed;\n"
"\n"
"static int type_is_reclaimed(int nominal) {\n"
"    if (nominal < 0 || nominal >= nominal_count) return 0;\n"
"    if (!type_reclaimed_cache_valid) {\n"
"        type_reclaimed = (int*)xcalloc((size_t)nominal_count, sizeof(int),\n"
"                                       \"AIF reclaimed types\");\n"
"        for (int s = 0; s < site_count; s++) {\n"
"            if (elem_disposition_of(&sites[s], aif_tier_of(s)) == AIF_ELEM_NONE) continue;\n"
"            int id = nominal_find_id(base_type_id(sites[s].type));\n"
"            if (id >= 0) type_reclaimed[id] = 1;\n"
"        }\n"
"        type_reclaimed_cache_valid = 1;\n"
"    }\n"
"    return type_reclaimed[nominal];\n"
"}\n"
"\n"
"static void compute_released_fields(void) {\n"
"    if (in_released_field_done) return;\n"
"    in_released_field_done = 1;\n"
"    for (int n = 0; n < nominal_count; n++) {\n"
"        if (nominals[n].is_enum) continue;\n"
"        if (!type_is_reclaimed(n)) continue;\n"
"        Nominal* t = &nominals[n];\n"
"        for (int i = 0; i < t->nfields; i++) {\n"
"            if (field_release_of(t->name, t->field_name[i], field_declared_type(t, i))\n"
"                == AIF_ELEM_NONE) continue;\n"
"            int key = key_find(AIF_KEY_FIELD, t->name, t->field_name[i]);\n"
"            if (key < 0 || key >= pt_len) continue;\n"
"            bits_or(&in_released_field, &pt[key], \"AIF released fields\");\n"
"        }\n"
"    }\n"
"}\n"
"\n"
"static int site_in_released_field(int s) {\n"
"    compute_released_fields();\n"
"    return bits_test(&in_released_field, s);\n"
"}\n"
"\n"
"// Whether codegen should allocate this node's value through rc_alloc.\n"
"//\n"
"// Keyed by node like every other codegen query, and it must agree with\n"
"// elem_disposition_of exactly: a container told its elements are counted will\n"
"// decrement every one of them, so a site that reached that container without a\n"
"// header is a write through a pointer into someone else's allocation. They read\n"
"// the same predicate for that reason.\n"
"int aif_rc_at_node(const void* node) {\n"
"    if (node == NULL) return 0;\n"
"    for (NodeSite* n = node_buckets[node_hash(node)]; n; n = n->next) {\n"
"        if (n->node != node) continue;\n"
"        return site_is_rc(&sites[n->site], aif_tier_of(n->site));\n"
"    }\n"
"    return 0;\n"
"}\n"
"\n"
"// What the container allocated at this node should do with its elements.\n"
"int aif_elem_owner_at_node(const void* node) {\n"
"    if (node == NULL) return AIF_ELEM_NONE;\n"
"    int container = -1;\n"
"    for (NodeSite* n = node_buckets[node_hash(node)]; n; n = n->next) {\n"
"        if (n->node == node) { container = n->site; break; }\n"
"    }\n"
"    if (container < 0) return AIF_ELEM_NONE;\n"
"\n"
"    int agreed = AIF_ELEM_NONE;\n"
"    for (int s = 0; s < site_count; s++) {\n"
"        if (!bits_test(&container_of[s], container)) continue;\n"
"        int d = elem_disposition_of(&sites[s], aif_tier_of(s));\n"
"        if (d == AIF_ELEM_NONE) return AIF_ELEM_NONE;\n"
"        if (agreed == AIF_ELEM_NONE) agreed = d;\n"
"        else if (agreed != d) return AIF_ELEM_NONE;\n"
"    }\n"
"    return agreed;\n"
"}\n"
"\n"
"// The element type of a container whose elements are released by type.\n"
"//\n"
"// Read from the sites rather than from the container's spelled type, for the\n"
"// same reason the element key is object-insensitive: `list_new()` types as\n"
"// `List<Invalid>`, so the annotation is not always there to read, and the sites\n"
"// that actually reached the container always are. \"\" when they disagree, which\n"
"// aif_elem_owner_at_node has already turned into NONE.\n"
"const char* aif_elem_type_at_node(const void* node) {\n"
"    if (node == NULL) return \"\";\n"
"    int container = -1;\n"
"    for (NodeSite* n = node_buckets[node_hash(node)]; n; n = n->next) {\n"
"        if (n->node == node) { container = n->site; break; }\n"
"    }\n"
"    if (container < 0) return \"\";\n"
"\n"
"    int agreed = -1;\n"
"    for (int s = 0; s < site_count; s++) {\n"
"        if (!bits_test(&container_of[s], container)) continue;\n"
"        if (agreed < 0) agreed = sites[s].type;\n"
"        else if (agreed != sites[s].type) return \"\";\n"
"    }\n"
"    return agreed < 0 ? \"\" : aif_str(agreed);\n"
"}\n"
"\n"
"int aif_site_in_container(int id) {\n"
"    if (id < 0 || id >= site_count) return 0;\n"
"    return sites[id].in_container;\n"
"}\n"
"\n"
"// The manifest's half of aif_rc_at_node. SPEC 6.2's placement column has to say\n"
"// what was *built*, and \"rc\" for a T3 site nothing counts would be the manifest\n"
"// asserting a mechanism the binary does not contain.\n"
"int aif_site_is_rc(int id) {\n"
"    if (id < 0 || id >= site_count) return 0;\n"
"    return site_is_rc(&sites[id], aif_tier_of(id));\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Ownership transfer across a return\n"
"//\n"
"// `let cmds = cull(scene, ...)` allocates in the callee and reclaims in the\n"
"// caller, and the escape lattice cannot say so: E is per site, a site belongs to\n"
"// one function, and Region(s) can only name a scope in that function. So a\n"
"// returned value is Caller and stays Caller no matter how briefly the caller\n"
"// keeps it. INFERENCE 6's ownership contexts are the specified fix -- instantiate\n"
"// the callee per call site so the return lands in the caller's scope -- and that\n"
"// is a project, not a clause.\n"
"//\n"
"// What is available without it: T2 already means \"unique, and the callee kept no\n"
"// other holder\", which is the whole of what the caller needs to know. The rest is\n"
"// asked of the syntax at the binding, the same way node_assigns_name is, because\n"
"// the two things that could still go wrong are both visible there.\n"
"//\n"
"//   * The callee returned something it did not allocate -- a pass-through of its\n"
"//     own argument. Then the caller frees a value it already owns elsewhere.\n"
"//     Excluded by requiring every site in the return set to belong to the callee.\n"
"//   * The caller returns it onward. Excluded in ir.psm by node_returns_name,\n"
"//     which is the guard the escape fact would otherwise have supplied.\n"
"//\n"
"// Restricted to a returned **container**, and the restriction is a soundness\n"
"// requirement rather than a conservative start. A value set records the sites an\n"
"// expression may denote, and a string literal or a static is not a site -- so for\n"
"// a function returning `String`, `return \"ptr\"` contributes nothing and the set\n"
"// looks exactly like one that always allocates. Freeing that is a free of\n"
"// `.rodata`, which is the defect Level 4 found in `str_substring` arriving by a\n"
"// different road. The same goes for a struct-returning function with a sentinel\n"
"// path.\n"
"//\n"
"// A `List` has no literal form: list_new is the only way to make one and it\n"
"// always allocates. So the return set of a list-returning function is complete,\n"
"// which is the property this needs and the one the other two lack. Recovering\n"
"// them needs the points-to lattice to carry \"may hold something untracked\", which\n"
"// is a real extension and not this item.\n"
"//\n"
"// Returns the deallocator the result needs: 0 none, 2 list.\n"
"// ============================================================================\n"
"\n"
"typedef struct NodeCall {\n"
"    struct NodeCall* next;\n"
"    const void* node;\n"
"    int vs;\n"
"    int fn;\n"
"} NodeCall;\n"
"\n"
"static NodeCall* call_buckets[AIF_NODE_BUCKETS];\n"
"static Bits query_scratch;\n"
"\n"
"void aif_note_call_result(const void* node, int vs, int fn) {\n"
"    if (node == NULL || fn < 0) return;\n"
"    unsigned b = node_hash(node);\n"
"    for (NodeCall* n = call_buckets[b]; n; n = n->next) {\n"
"        if (n->node == node) return;\n"
"    }\n"
"    NodeCall* n = (NodeCall*)xmalloc(sizeof(NodeCall), \"AIF call index\");\n"
"    n->node = node;\n"
"    n->vs = vs;\n"
"    n->fn = fn;\n"
"    n->next = call_buckets[b];\n"
"    call_buckets[b] = n;\n"
"}\n"
"\n"
"int aif_owns_call_result_at_node(const void* node) {\n"
"    if (node == NULL) return AIF_ELEM_NONE;\n"
"    NodeCall* c = NULL;\n"
"    for (NodeCall* n = call_buckets[node_hash(node)]; n; n = n->next) {\n"
"        if (n->node == node) { c = n; break; }\n"
"    }\n"
"    if (c == NULL) return AIF_ELEM_NONE;\n"
"\n"
"    resolve(c->vs, &query_scratch);\n"
"    int agreed = AIF_ELEM_NONE;\n"
"    int any = 0;\n"
"    for (int s = 0; s < site_count; s++) {\n"
"        if (!bits_test(&query_scratch, s)) continue;\n"
"        any = 1;\n"
"        // Allocated by the callee, not handed to it. A pass-through leaves the\n"
"        // value owned where it was created, and freeing it here is a double free\n"
"        // through whichever binding owns it there.\n"
"        if (sites[s].fn != c->fn) return AIF_ELEM_NONE;\n"
"        if (sites[s].in_container) return AIF_ELEM_NONE;\n"
"        // A field the type releases is already this value's release point, so\n"
"        // the caller must not become a second one. The same exclusion as\n"
"        // in_container above, and reachable the same way: a function that both\n"
"        // stores a value into a field and returns that field.\n"
"        if (site_in_released_field(s)) return AIF_ELEM_NONE;\n"
"        if (aif_tier_of(s) != AIF_T2) return AIF_ELEM_NONE;\n"
"        int d = elem_disposition_of(&sites[s], AIF_T2);\n"
"        // A struct that owns something joins `List` here, and for the same\n"
"        // reason the comment above gives: the value set has to be complete.\n"
"        // A `List` qualifies because it has no literal form. A struct qualifies\n"
"        // because it has no *sentinel* form -- there is no null, so every way to\n"
"        // produce one is either a literal (a site in this callee) or a value\n"
"        // that came from somewhere else (a site whose fn is not this one, which\n"
"        // the test above declines). **REQUIREMENTS 4 must not break that**: an\n"
"        // Option-typed return would be the first struct-shaped value that is not\n"
"        // a site, and this is the line it would make unsound.\n"
"        //\n"
"        // Restricted to structs that own something, which is a scope choice and\n"
"        // not a soundness one -- the completeness argument says nothing about\n"
"        // the fields. It is where the leak is (g4's `World`), and a plain struct\n"
"        // return has a much wider blast radius for no measured gain.\n"
"        if (d != AIF_ELEM_LIST && d != AIF_ELEM_TYPED) return AIF_ELEM_NONE;\n"
"        if (agreed != AIF_ELEM_NONE && agreed != d) return AIF_ELEM_NONE;\n"
"        agreed = d;\n"
"    }\n"
"    return any ? agreed : AIF_ELEM_NONE;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Manifest ordering\n"
"//\n"
"// SPEC 6.2 makes the record order normative -- byte-wise ascending by symbol --\n"
"// because an unstable order makes every diff useless. The frontend builds each\n"
"// record's symbol (it knows what a symbol means) and hands it here to be sorted\n"
"// (sorting is a container operation).\n"
"//\n"
"// Insertion-order-stable, so equal symbols keep the order they were added in.\n"
"// There should be no equal symbols; relying on that rather than asserting it\n"
"// would make a future collision reorder the manifest silently.\n"
"// ============================================================================\n"
"\n"
"typedef struct {\n"
"    int symbol;     // interned\n"
"    int site;\n"
"    int seq;\n"
"} Record;\n"
"\n"
"static Record* records;\n"
"static int record_count, record_cap;\n"
"\n"
"void aif_order_add(const char* symbol, int site) {\n"
"    if (record_count == record_cap) {\n"
"        record_cap = record_cap ? record_cap * 2 : 1024;\n"
"        records = (Record*)xrealloc(records, (size_t)record_cap * sizeof(Record),\n"
"                                    \"AIF manifest records\");\n"
"    }\n"
"    Record* r = &records[record_count];\n"
"    r->symbol = aif_intern(symbol);\n"
"    r->site = site;\n"
"    r->seq = record_count;\n"
"    record_count++;\n"
"}\n"
"\n"
"static int record_cmp(const void* a, const void* b) {\n"
"    const Record* x = (const Record*)a;\n"
"    const Record* y = (const Record*)b;\n"
"    int c = strcmp(aif_str(x->symbol), aif_str(y->symbol));\n"
"    if (c != 0) return c;\n"
"    return x->seq - y->seq;\n"
"}\n"
"\n"
"void aif_order_sort(void) {\n"
"    if (record_count > 1) qsort(records, (size_t)record_count, sizeof(Record), record_cmp);\n"
"}\n"
"\n"
"int aif_order_count(void) { return record_count; }\n"
"const char* aif_order_symbol(int i) { return (i < 0 || i >= record_count) ? \"\" : aif_str(records[i].symbol); }\n"
"int aif_order_site(int i) { return (i < 0 || i >= record_count) ? -1 : records[i].site; }\n"
"\n"
"// ============================================================================\n"
"// Reset\n"
"//\n"
"// A compiler run analyses one program, but the test harness and any future\n"
"// per-module invocation want a clean slate. Interned names are deliberately\n"
"// kept: they cost nothing and nothing outside this file holds an id across a\n"
"// reset.\n"
"// ============================================================================\n"
"\n"
"void aif_reset(void) {\n"
"    for (int i = 0; i < pt_len; i++) bits_free(&pt[i]);\n"
"    for (int i = 0; i < holders_len; i++) bits_free(&holders[i]);\n"
"    for (int i = 0; i < holders_len; i++) bits_free(&container_of[i]);\n"
"    free(pt);\n"
"    free(holders);\n"
"    free(container_of);\n"
"    pt = NULL;\n"
"    holders = NULL;\n"
"    container_of = NULL;\n"
"    pt_len = 0;\n"
"    holders_len = 0;\n"
"\n"
"    bits_free(&in_released_field);\n"
"    in_released_field_done = 0;\n"
"    free(type_releases);\n"
"    type_releases = NULL;\n"
"    type_releases_cap = 0;\n"
"    free(type_reclaimed);\n"
"    type_reclaimed = NULL;\n"
"    type_reclaimed_cache_valid = 0;\n"
"\n"
"    free(deriv_e);\n"
"    free(deriv_a);\n"
"    deriv_e = NULL;\n"
"    deriv_a = NULL;\n"
"    cause_len = 0;\n"
"    cur_con = -1;\n"
"    synth_rule = -1;\n"
"\n"
"    for (int i = 0; i < vs_count; i++) free(vsets[i].items);\n"
"    vs_count = 0;\n"
"\n"
"    for (int i = 0; i < nominal_count; i++) {\n"
"        bits_free(&nominals[i].reaches);\n"
"        free(nominals[i].field_name);\n"
"        free(nominals[i].field_type);\n"
"        free(nominals[i].field_bytes);\n"
"        free(nominals[i].field_acc);\n"
"        free(nominals[i].order);\n"
"    }\n"
"    nominal_count = 0;\n"
"    for (int i = 0; i < nominal_by_name_cap; i++) nominal_by_name[i] = -1;\n"
"\n"
"    for (int i = 0; i < fn_by_symbol_cap; i++) fn_by_symbol[i] = -1;\n"
"    fn_count = 0;\n"
"\n"
"    free(var_scope);\n"
"    var_scope = NULL;\n"
"    var_scope_cap = 0;\n"
"\n"
"    free(extern_contract);\n"
"    extern_contract = NULL;\n"
"    extern_contract_cap = 0;\n"
"\n"
"    for (int i = 0; i < AIF_NODE_BUCKETS; i++) {\n"
"        NodeSite* n = node_buckets[i];\n"
"        while (n) {\n"
"            NodeSite* next = n->next;\n"
"            free(n);\n"
"            n = next;\n"
"        }\n"
"        node_buckets[i] = NULL;\n"
"    }\n"
"\n"
"    for (int i = 0; i < AIF_NODE_BUCKETS; i++) {\n"
"        NodeCall* n = call_buckets[i];\n"
"        while (n) {\n"
"            NodeCall* next = n->next;\n"
"            free(n);\n"
"            n = next;\n"
"        }\n"
"        call_buckets[i] = NULL;\n"
"    }\n"
"\n"
"    site_count = 0;\n"
"    scope_count = 0;\n"
"    con_count = 0;\n"
"    record_count = 0;\n"
"    orphan_sites = 0;\n"
"    solve_rounds = 0;\n"
"    owned_collections = 0;\n"
"\n"
"    bits_free(&scratch_val);\n"
"    bits_free(&scratch_own);\n"
"    bits_free(&query_scratch);\n"
"    free(vec_val.v);\n"
"    free(vec_own.v);\n"
"    free(argv.v);\n"
"    vec_val.v = NULL; vec_val.len = 0; vec_val.cap = 0;\n"
"    vec_own.v = NULL; vec_own.len = 0; vec_own.cap = 0;\n"
"    argv.v = NULL; argv.len = 0; argv.cap = 0;\n"
"\n"
"    for (int i = 0; i < AIF_KEY_BUCKETS; i++) {\n"
"        KeyNode* n = key_buckets[i];\n"
"        while (n) {\n"
"            KeyNode* next = n->next;\n"
"            free(n);\n"
"            n = next;\n"
"        }\n"
"        key_buckets[i] = NULL;\n"
"    }\n"
"    key_count = 0;\n"
"}\n"
;

static const char prismio_embedded_diagnostics_c[] =
"// Source-level diagnostics: the file registry, span rendering and error\n"
"// accounting behind every message the compiler prints.\n"
"//\n"
"// Compiler-only (backend.lib). A compiled Prismio program never reports a\n"
"// diagnostic, so none of this belongs in runtime.lib.\n"
"//\n"
"// Why this lives in C rather than in Prismio: rendering a diagnostic needs the\n"
"// *original source text* of whichever file the node came from, long after the\n"
"// parser has thrown the text away and `resolve_imports` has flattened every\n"
"// module into one AST. A registry keyed by an integer id is the smallest thing\n"
"// that survives both. Prismio also has no varargs, so the frontend composes the\n"
"// message with str_concat and hands over a finished string.\n"
"//\n"
"// Output goes to stderr, unconditionally and without colour. stderr because a\n"
"// diagnostic is not program output; without colour because the compiler cannot\n"
"// know whether the receiving console decodes ANSI (Windows consoles do not\n"
"// enable VT processing for a plain console application by default), and a\n"
"// half-decoded escape is worse than none.\n"
"\n"
"// stdio/stdlib/string arrive through this; including them again here would only\n"
"// let the two lists drift.\n"
"#include \"prismio_platform.h\"\n"
"\n"
"#define DIAG_MAX_FILES 256\n"
"\n"
"// Past this many errors the compiler stops rather than continuing to recover.\n"
"// Beyond roughly this point the output is cascade, not information, and every\n"
"// further recovery step is another chance to walk a half-built AST.\n"
"#define DIAG_ERROR_LIMIT 25\n"
"\n"
"typedef struct {\n"
"    char* path;\n"
"    char* content;\n"
"} DiagFile;\n"
"\n"
"static DiagFile g_files[DIAG_MAX_FILES];\n"
"static int g_file_count = 0;\n"
"static int g_error_count = 0;\n"
"static int g_warning_count = 0;\n"
"\n"
"static char* diag_strdup(const char* s) {\n"
"    if (!s) s = \"\";\n"
"    size_t n = strlen(s) + 1;\n"
"    char* out = (char*)malloc(n);\n"
"    if (!out) return NULL;\n"
"    memcpy(out, s, n);\n"
"    return out;\n"
"}\n"
"\n"
"// Registers a source file and returns the id to stamp onto every token and AST\n"
"// node produced from it. The content is copied: the caller's buffer belongs to\n"
"// the frontend, which is free to reuse or release it once parsing is done.\n"
"//\n"
"// Re-registering a path returns the existing id instead of a second entry, so\n"
"// the diamond-shaped import graph in src/ does not consume four slots for\n"
"// utils.psm.\n"
"int diag_add_file(const char* path, const char* content) {\n"
"    if (!path) path = \"<unknown>\";\n"
"\n"
"    for (int i = 0; i < g_file_count; i++) {\n"
"        if (strcmp(g_files[i].path, path) == 0) return i;\n"
"    }\n"
"\n"
"    if (g_file_count >= DIAG_MAX_FILES) return -1;\n"
"\n"
"    char* p = diag_strdup(path);\n"
"    char* c = diag_strdup(content);\n"
"    if (!p || !c) {\n"
"        free(p);\n"
"        free(c);\n"
"        return -1;\n"
"    }\n"
"\n"
"    g_files[g_file_count].path = p;\n"
"    g_files[g_file_count].content = c;\n"
"    return g_file_count++;\n"
"}\n"
"\n"
"const char* diag_file_path(int file) {\n"
"    if (file < 0 || file >= g_file_count) return \"<unknown>\";\n"
"    return g_files[file].path;\n"
"}\n"
"\n"
"// Start of the 1-based `line` within `text`, or NULL if the file has fewer\n"
"// lines than that -- which happens whenever a span is stale or synthesised, and\n"
"// must degrade to \"no snippet\" rather than reading past the buffer.\n"
"static const char* diag_line_start(const char* text, int line) {\n"
"    if (!text || line <= 0) return NULL;\n"
"\n"
"    const char* p = text;\n"
"    int current = 1;\n"
"    while (current < line && *p) {\n"
"        if (*p == '\\n') current++;\n"
"        p++;\n"
"    }\n"
"    return (current == line) ? p : NULL;\n"
"}\n"
"\n"
"static int diag_line_length(const char* start) {\n"
"    const char* end = start;\n"
"    while (*end && *end != '\\n') end++;\n"
"    int len = (int)(end - start);\n"
"    // A CRLF file would otherwise put a stray carriage return in the middle of\n"
"    // the rendered snippet, pushing the caret line back to column zero.\n"
"    if (len > 0 && start[len - 1] == '\\r') len--;\n"
"    return len;\n"
"}\n"
"\n"
"static int diag_digits(int value) {\n"
"    int n = 1;\n"
"    while (value >= 10) {\n"
"        value /= 10;\n"
"        n++;\n"
"    }\n"
"    return n;\n"
"}\n"
"\n"
"static void diag_spaces(int n) {\n"
"    for (int i = 0; i < n; i++) fputc(' ', stderr);\n"
"}\n"
"\n"
"// The snippet block, in the rustc shape:\n"
"//\n"
"//      --> src/foo.psm:12:5\n"
"//       |\n"
"//    12 |     x = 6\n"
"//       |     ^\n"
"//\n"
"// `gutter` is the width of the line number, so the vertical bars line up no\n"
"// matter how long the file is.\n"
"static void diag_render_span(int file, int line, int col, int len) {\n"
"    if (file < 0 || file >= g_file_count || line <= 0) return;\n"
"\n"
"    const char* path = g_files[file].path;\n"
"    const char* text = g_files[file].content;\n"
"    const char* start = diag_line_start(text, line);\n"
"\n"
"    if (col < 1) col = 1;\n"
"\n"
"    if (!start) {\n"
"        // No snippet available, but the location itself is still worth having.\n"
"        fprintf(stderr, \" --> %s:%d:%d\\n\", path, line, col);\n"
"        return;\n"
"    }\n"
"\n"
"    int line_len = diag_line_length(start);\n"
"    int gutter = diag_digits(line);\n"
"\n"
"    diag_spaces(gutter);\n"
"    fprintf(stderr, \"--> %s:%d:%d\\n\", path, line, col);\n"
"\n"
"    diag_spaces(gutter + 1);\n"
"    fprintf(stderr, \"|\\n\");\n"
"\n"
"    fprintf(stderr, \"%d | %.*s\\n\", line, line_len, start);\n"
"\n"
"    diag_spaces(gutter + 1);\n"
"    fprintf(stderr, \"| \");\n"
"\n"
"    // Pad with the source's own whitespace so a tab-indented line keeps the\n"
"    // caret under the right character instead of drifting by seven columns.\n"
"    int pad = col - 1;\n"
"    if (pad > line_len) pad = line_len;\n"
"    for (int i = 0; i < pad; i++) fputc(start[i] == '\\t' ? '\\t' : ' ', stderr);\n"
"\n"
"    int carets = len > 0 ? len : 1;\n"
"    if (pad + carets > line_len) carets = line_len - pad;\n"
"    if (carets < 1) carets = 1;\n"
"    for (int i = 0; i < carets; i++) fputc('^', stderr);\n"
"    fputc('\\n', stderr);\n"
"}\n"
"\n"
"static void diag_emit(const char* severity, int file, int line, int col, int len, const char* message) {\n"
"    fprintf(stderr, \"%s: %s\\n\", severity, message ? message : \"\");\n"
"    diag_render_span(file, line, col, len);\n"
"    fflush(stderr);\n"
"}\n"
"\n"
"void diag_error_at(int file, int line, int col, int len, const char* message) {\n"
"    g_error_count++;\n"
"\n"
"    if (g_error_count > DIAG_ERROR_LIMIT) {\n"
"        fprintf(stderr, \"error: too many errors; stopping after %d\\n\", DIAG_ERROR_LIMIT);\n"
"        fflush(stderr);\n"
"        exit(1);\n"
"    }\n"
"\n"
"    diag_emit(\"error\", file, line, col, len, message);\n"
"}\n"
"\n"
"void diag_error(const char* message) {\n"
"    diag_error_at(-1, 0, 0, 0, message);\n"
"}\n"
"\n"
"void diag_warning_at(int file, int line, int col, int len, const char* message) {\n"
"    g_warning_count++;\n"
"    diag_emit(\"warning\", file, line, col, len, message);\n"
"}\n"
"\n"
"// A secondary span belonging to the diagnostic just reported -- \"the first\n"
"// declaration is here\", \"the loop starts here\". Indented so it reads as\n"
"// subordinate rather than as a second, unrelated error.\n"
"void diag_note_at(int file, int line, int col, int len, const char* message) {\n"
"    fprintf(stderr, \"  note: %s\\n\", message ? message : \"\");\n"
"    diag_render_span(file, line, col, len);\n"
"    fflush(stderr);\n"
"}\n"
"\n"
"void diag_note(const char* message) {\n"
"    fprintf(stderr, \"  note: %s\\n\", message ? message : \"\");\n"
"    fflush(stderr);\n"
"}\n"
"\n"
"int diag_error_count(void) {\n"
"    return g_error_count;\n"
"}\n"
"\n"
"int diag_warning_count(void) {\n"
"    return g_warning_count;\n"
"}\n"
"\n"
"// The closing line, printed once when compilation gives up. Its wording is the\n"
"// contract the negative tests match on: a test passes because the compiler\n"
"// *rejected* the program, which a crash or a linker failure must not be able to\n"
"// impersonate.\n"
"void diag_finish(void) {\n"
"    if (g_error_count <= 0) return;\n"
"\n"
"    if (g_error_count == 1) {\n"
"        fprintf(stderr, \"error: aborting due to 1 previous error\\n\");\n"
"    } else {\n"
"        fprintf(stderr, \"error: aborting due to %d previous errors\\n\", g_error_count);\n"
"    }\n"
"    fflush(stderr);\n"
"}\n"
"\n"
"void diag_reset(void) {\n"
"    for (int i = 0; i < g_file_count; i++) {\n"
"        free(g_files[i].path);\n"
"        free(g_files[i].content);\n"
"        g_files[i].path = NULL;\n"
"        g_files[i].content = NULL;\n"
"    }\n"
"    g_file_count = 0;\n"
"    g_error_count = 0;\n"
"    g_warning_count = 0;\n"
"}\n"
;

static const char prismio_embedded_llvm_api_backend_c[] =
"// ============================================================================\n"
"// Prismio backend built on the real LLVM C API.\n"
"//\n"
"// This is the replacement for llvm-bridge.c, which assembled LLVM IR as text in\n"
"// fixed-size buffers. Both implement the same ir_* surface declared in\n"
"// src/bridge.psm, so exactly one is linked into the compiler and the frontend\n"
"// does not know which. Select this one with:\n"
"//\n"
"//     clang -DPRISMIO_BACKEND_LLVM_API ...   (and link LLVM-C)\n"
"//\n"
"// Why this exists at all, beyond tidiness: the text emitter could only be\n"
"// checked by llc's parser after the fact, so a malformed instruction surfaced as\n"
"// a parse error pointing at generated IR rather than at the code that built it.\n"
"// Here LLVMVerifyModule runs before anything is written, the IRBuilder refuses\n"
"// to construct type-incorrect instructions in the first place, and constants are\n"
"// folded as they are built. It is also the prerequisite for a custom memory\n"
"// model: allocation is a policy hook here (see \"memory model\" below) instead of\n"
"// a hardcoded `call ptr @malloc` spelled out in the frontend.\n"
"//\n"
"// ---------------------------------------------------------------------------\n"
"// How values cross the FFI\n"
"//\n"
"// Prismio has no pointer type, so the frontend passes everything as String. The\n"
"// compiler already relies on this for AST nodes (ptr_to_node/node_to_ptr). Here\n"
"// a value is a *handle string*, and every function that accepts a value resolves\n"
"// it through resolve_value():\n"
"//\n"
"//     \"$$v12\"      -> g_values[12], an LLVMValueRef produced by an earlier call\n"
"//     \"%p_argc\"    -> a parameter of the function being built, looked up by name\n"
"//     \"%x\"         -> a named alloca in the current function\n"
"//     anything else -> a literal constant, parsed according to the type argument\n"
"//\n"
"// The literal case is what lets the existing frontend keep passing \"0\", \"42\",\n"
"// \"true\" and \"null\" straight through without being rewritten first. '$' cannot\n"
"// appear in a Prismio identifier, so a handle can never collide with user text.\n"
"//\n"
"// ---------------------------------------------------------------------------\n"
"// Status: this is the only backend. llvm-bridge.c has been deleted.\n"
"//\n"
"// The compiler self-hosts on this backend to a fixed point and passes the full\n"
"// test suite. src/ir.psm no longer emits any IR text -- struct literals, member\n"
"// access, array literals, indexing, string literals and struct type definitions\n"
"// all go through the typed builders below.\n"
"//\n"
"// ir_append() is kept as a loud failure rather than removed. Nothing calls it,\n"
"// and nothing should: it is the guard that stops raw text creeping back in,\n"
"// where it would silently produce a module with instructions missing.\n"
"// ============================================================================\n"
"\n"
"#include <stdio.h>\n"
"#include <stdlib.h>\n"
"#include <string.h>\n"
"\n"
"#include \"prismio_llvm.h\"\n"
"\n"
"// ============================================================================\n"
"// Module state\n"
"// ============================================================================\n"
"\n"
"#define MAX_VALUES 65536\n"
"#define MAX_LABELS 16384\n"
"#define MAX_NAMED 4096\n"
"#define MAX_CALL_DEPTH 64\n"
"#define MAX_CALL_ARGS 64\n"
"#define MAX_PENDING_PARAMS 64\n"
"#define NAME_LEN 128\n"
"\n"
"static LLVMContextRef g_ctx;\n"
"static LLVMModuleRef g_module;\n"
"static LLVMBuilderRef g_builder;\n"
"// Second builder, used only for allocas. They must land in the entry block no\n"
"// matter where codegen currently is, or a `let` inside a loop body would grow\n"
"// the stack on every iteration.\n"
"static LLVMBuilderRef g_alloca_builder;\n"
"static LLVMBasicBlockRef g_entry_block;\n"
"static int g_initialized;\n"
"\n"
"static LLVMValueRef g_values[MAX_VALUES];\n"
"static int g_value_count;\n"
"\n"
"// Blocks are reserved before they are created: the frontend asks for a label\n"
"// number, branches to it, and only later says \"the block starts here\". So a slot\n"
"// is handed out immediately and the LLVMBasicBlockRef is materialised on first\n"
"// use.\n"
"static LLVMBasicBlockRef g_blocks[MAX_LABELS];\n"
"static int g_label_count;\n"
"\n"
"typedef struct {\n"
"    char name[NAME_LEN];\n"
"    LLVMValueRef value;\n"
"    LLVMTypeRef type; // allocated type, for load/GEP\n"
"} NamedValue;\n"
"\n"
"static NamedValue g_allocas[MAX_NAMED];\n"
"static int g_alloca_count;\n"
"static NamedValue g_params[MAX_PENDING_PARAMS];\n"
"static int g_param_count;\n"
"\n"
"// Function currently being built.\n"
"static LLVMValueRef g_function;\n"
"static char g_pending_fn_name[NAME_LEN];\n"
"static LLVMTypeRef g_pending_ret;\n"
"static LLVMTypeRef g_pending_params[MAX_PENDING_PARAMS];\n"
"static char g_pending_param_names[MAX_PENDING_PARAMS][NAME_LEN];\n"
"static int g_pending_param_count;\n"
"static int g_declaring; // 1 while building a `declare`, 0 for a definition\n"
"\n"
"// Call being assembled.\n"
"typedef struct {\n"
"    LLVMValueRef args[MAX_CALL_ARGS];\n"
"    int count;\n"
"} CallFrame;\n"
"static CallFrame g_calls[MAX_CALL_DEPTH];\n"
"static int g_call_depth;\n"
"\n"
"static int g_has_returned;\n"
"\n"
"// ============================================================================\n"
"// Memory model policy\n"
"//\n"
"// Object allocation is deliberately indirect. The frontend asks for \"an object\n"
"// of this struct type\" and this layer decides what that means, so swapping\n"
"// malloc for an arena, a refcounting allocator, or anything else is a change\n"
"// here and not a change to codegen. Defaults keep today's behaviour exactly.\n"
"// ============================================================================\n"
"\n"
"static char g_alloc_fn[NAME_LEN] = \"malloc\";\n"
"static char g_free_fn[NAME_LEN] = \"free\";\n"
"\n"
"// Pointer-sized integer for the current target: i64 natively, i32 on wasm32.\n"
"// Determines the width of the size argument passed to the allocator.\n"
"static char g_ptr_int[16] = \"i64\";\n"
"\n"
"void ir_set_pointer_int_type(const char *t) {\n"
"    if (t && *t) {\n"
"        strncpy(g_ptr_int, t, sizeof(g_ptr_int) - 1);\n"
"        g_ptr_int[sizeof(g_ptr_int) - 1] = '\\0';\n"
"    }\n"
"}\n"
"\n"
"void ir_set_alloc_function(const char *name) {\n"
"    if (name && *name) {\n"
"        strncpy(g_alloc_fn, name, NAME_LEN - 1);\n"
"        g_alloc_fn[NAME_LEN - 1] = '\\0';\n"
"    }\n"
"}\n"
"\n"
"void ir_set_free_function(const char *name) {\n"
"    if (name && *name) {\n"
"        strncpy(g_free_fn, name, NAME_LEN - 1);\n"
"        g_free_fn[NAME_LEN - 1] = '\\0';\n"
"    }\n"
"}\n"
"\n"
"const char *ir_get_alloc_function(void) { return g_alloc_fn; }\n"
"const char *ir_get_free_function(void) { return g_free_fn; }\n"
"\n"
"// The LLVM actually loaded, for `prismio --version`. Reported rather than\n"
"// hardcoded so a version mismatch is visible without having to trigger it.\n"
"const char *ir_llvm_version(void) {\n"
"    static char buf[32];\n"
"    unsigned major = 0, minor = 0, patch = 0;\n"
"    LLVMGetVersion(&major, &minor, &patch);\n"
"    snprintf(buf, sizeof(buf), \"%u.%u.%u\", major, minor, patch);\n"
"    return buf;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Diagnostics\n"
"// ============================================================================\n"
"\n"
"static void backend_fail(const char *what, const char *detail) {\n"
"    fprintf(stderr, \"internal backend error: %s\", what);\n"
"    if (detail) fprintf(stderr, \" (%s)\", detail);\n"
"    fprintf(stderr, \"\\n\");\n"
"    exit(1);\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Value table\n"
"// ============================================================================\n"
"\n"
"static int intern_value(LLVMValueRef v) {\n"
"    if (g_value_count >= MAX_VALUES) backend_fail(\"value table exhausted\", NULL);\n"
"    g_values[g_value_count] = v;\n"
"    return g_value_count++;\n"
"}\n"
"\n"
"const char *ir_get_temp_name(int id) {\n"
"    char *out = (char *)malloc(32);\n"
"    snprintf(out, 32, \"$$v%d\", id);\n"
"    return out;\n"
"}\n"
"\n"
"const char *ir_get_label_name(int id) {\n"
"    char *out = (char *)malloc(32);\n"
"    snprintf(out, 32, \"label_%d\", id);\n"
"    return out;\n"
"}\n"
"\n"
"// Reserves a slot without an instruction behind it yet.\n"
"int ir_get_temp(void) { return intern_value(NULL); }\n"
"\n"
"// ============================================================================\n"
"// Types\n"
"// ============================================================================\n"
"\n"
"static LLVMTypeRef named_struct(const char *name);\n"
"\n"
"// Maps the frontend's type keys (\"i32\", \"double\", \"ptr\", \"struct:Foo\") onto\n"
"// LLVM types. Unknown keys are a hard error rather than a silent i32, which is\n"
"// what the text backend defaulted to.\n"
"static LLVMTypeRef type_from_key(const char *t) {\n"
"    if (!t || !*t) return LLVMVoidTypeInContext(g_ctx);\n"
"    if (strcmp(t, \"void\") == 0) return LLVMVoidTypeInContext(g_ctx);\n"
"    if (strcmp(t, \"i1\") == 0) return LLVMInt1TypeInContext(g_ctx);\n"
"    if (strcmp(t, \"i8\") == 0) return LLVMInt8TypeInContext(g_ctx);\n"
"    if (strcmp(t, \"i16\") == 0) return LLVMInt16TypeInContext(g_ctx);\n"
"    if (strcmp(t, \"i32\") == 0) return LLVMInt32TypeInContext(g_ctx);\n"
"    if (strcmp(t, \"i64\") == 0) return LLVMInt64TypeInContext(g_ctx);\n"
"    if (strcmp(t, \"double\") == 0) return LLVMDoubleTypeInContext(g_ctx);\n"
"    if (strcmp(t, \"ptr\") == 0 || strcmp(t, \"ptrptr\") == 0)\n"
"        return LLVMPointerTypeInContext(g_ctx, 0);\n"
"    if (strncmp(t, \"struct:\", 7) == 0) return named_struct(t + 7);\n"
"    if (t[0] == '%') return named_struct(t + 1);\n"
"    backend_fail(\"unknown type key\", t);\n"
"    return NULL;\n"
"}\n"
"\n"
"// --- named struct types -----------------------------------------------------\n"
"\n"
"typedef struct {\n"
"    char name[NAME_LEN];\n"
"    LLVMTypeRef type;\n"
"} StructType;\n"
"\n"
"static StructType g_structs[256];\n"
"static int g_struct_count;\n"
"\n"
"static LLVMTypeRef named_struct(const char *name) {\n"
"    for (int i = 0; i < g_struct_count; i++) {\n"
"        if (strcmp(g_structs[i].name, name) == 0) return g_structs[i].type;\n"
"    }\n"
"    if (g_struct_count >= 256) backend_fail(\"too many struct types\", name);\n"
"    // Created opaque; the body is set by ir_struct_type_end().\n"
"    LLVMTypeRef ty = LLVMStructCreateNamed(g_ctx, name);\n"
"    strncpy(g_structs[g_struct_count].name, name, NAME_LEN - 1);\n"
"    g_structs[g_struct_count].name[NAME_LEN - 1] = '\\0';\n"
"    g_structs[g_struct_count].type = ty;\n"
"    g_struct_count++;\n"
"    return ty;\n"
"}\n"
"\n"
"static LLVMTypeRef g_struct_fields[64];\n"
"static int g_struct_field_count;\n"
"static char g_struct_building[NAME_LEN];\n"
"\n"
"void ir_struct_type_begin(const char *name) {\n"
"    strncpy(g_struct_building, name, NAME_LEN - 1);\n"
"    g_struct_building[NAME_LEN - 1] = '\\0';\n"
"    g_struct_field_count = 0;\n"
"}\n"
"\n"
"void ir_struct_type_field(const char *field_type) {\n"
"    if (g_struct_field_count >= 64) backend_fail(\"too many struct fields\", g_struct_building);\n"
"    g_struct_fields[g_struct_field_count++] = type_from_key(field_type);\n"
"}\n"
"\n"
"void ir_struct_type_end(void) {\n"
"    LLVMTypeRef ty = named_struct(g_struct_building);\n"
"    LLVMStructSetBody(ty, g_struct_fields, (unsigned)g_struct_field_count, 0);\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Value resolution\n"
"// ============================================================================\n"
"\n"
"static LLVMValueRef lookup_named(NamedValue *table, int count, const char *name,\n"
"                                 LLVMTypeRef *out_type) {\n"
"    for (int i = 0; i < count; i++) {\n"
"        if (strcmp(table[i].name, name) == 0) {\n"
"            if (out_type) *out_type = table[i].type;\n"
"            return table[i].value;\n"
"        }\n"
"    }\n"
"    return NULL;\n"
"}\n"
"\n"
"static LLVMValueRef const_from_text(const char *s, LLVMTypeRef ty) {\n"
"    if (!ty) backend_fail(\"constant with no type\", s);\n"
"    if (ty == LLVMDoubleTypeInContext(g_ctx)) return LLVMConstReal(ty, atof(s));\n"
"    if (ty == LLVMPointerTypeInContext(g_ctx, 0)) {\n"
"        if (strcmp(s, \"null\") == 0 || strcmp(s, \"0\") == 0) return LLVMConstPointerNull(ty);\n"
"        backend_fail(\"non-null pointer constant\", s);\n"
"    }\n"
"    if (strcmp(s, \"true\") == 0) return LLVMConstInt(ty, 1, 0);\n"
"    if (strcmp(s, \"false\") == 0) return LLVMConstInt(ty, 0, 0);\n"
"    return LLVMConstInt(ty, (unsigned long long)strtoll(s, NULL, 10), 1);\n"
"}\n"
"\n"
"// The single place that turns a frontend string into an LLVMValueRef.\n"
"static LLVMValueRef resolve_value(const char *s, const char *type_key) {\n"
"    if (!s) backend_fail(\"null value\", NULL);\n"
"\n"
"    if (s[0] == '$' && s[1] == '$' && s[2] == 'v') {\n"
"        int idx = atoi(s + 3);\n"
"        if (idx < 0 || idx >= g_value_count) backend_fail(\"value handle out of range\", s);\n"
"        LLVMValueRef v = g_values[idx];\n"
"        if (!v) backend_fail(\"value handle refers to an unset slot\", s);\n"
"        return v;\n"
"    }\n"
"\n"
"    if (s[0] == '%') {\n"
"        const char *name = s + 1;\n"
"        LLVMValueRef v = lookup_named(g_params, g_param_count, name, NULL);\n"
"        if (v) return v;\n"
"        v = lookup_named(g_allocas, g_alloca_count, name, NULL);\n"
"        if (v) return v;\n"
"        backend_fail(\"unknown local name\", s);\n"
"    }\n"
"\n"
"    return const_from_text(s, type_from_key(type_key));\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Module lifecycle\n"
"// ============================================================================\n"
"\n"
"static void reset_state(void) {\n"
"    g_value_count = 0;\n"
"    g_label_count = 0;\n"
"    g_alloca_count = 0;\n"
"    g_param_count = 0;\n"
"    g_struct_count = 0;\n"
"    g_call_depth = 0;\n"
"    g_has_returned = 0;\n"
"    g_function = NULL;\n"
"    g_pending_param_count = 0;\n"
"}\n"
"\n"
"void ir_reset(void) {\n"
"    if (g_module) {\n"
"        LLVMDisposeModule(g_module);\n"
"        g_module = NULL;\n"
"    }\n"
"    reset_state();\n"
"}\n"
"\n"
"// Refuses to run against an LLVM whose major version is not the pinned one.\n"
"//\n"
"// Checked here rather than only at build time because the dangerous mismatch is\n"
"// between the headers this was compiled against and the LLVM-C library actually\n"
"// loaded: that links cleanly and then misbehaves in ways that look like compiler\n"
"// bugs. On Windows in particular, any LLVM-C.dll earlier on PATH wins.\n"
"static void check_llvm_version(void) {\n"
"    unsigned major = 0, minor = 0, patch = 0;\n"
"    LLVMGetVersion(&major, &minor, &patch);\n"
"    if ((int)major != PRISMIO_LLVM_EXPECTED_MAJOR) {\n"
"        fprintf(stderr,\n"
"                \"error: this Prismio was built for LLVM %d, but LLVM %u.%u.%u is loaded.\\n\"\n"
"                \"  The LLVM C API is only stable within a major version.\\n\"\n"
"                \"  Run: python tools/setup_llvm.py\\n\",\n"
"                PRISMIO_LLVM_EXPECTED_MAJOR, major, minor, patch);\n"
"        exit(1);\n"
"    }\n"
"}\n"
"\n"
"static void ensure_context(void) {\n"
"    if (g_initialized) return;\n"
"    check_llvm_version();\n"
"    g_ctx = LLVMContextCreate();\n"
"    g_builder = LLVMCreateBuilderInContext(g_ctx);\n"
"    g_alloca_builder = LLVMCreateBuilderInContext(g_ctx);\n"
"    g_initialized = 1;\n"
"}\n"
"\n"
"void ir_module_start(const char *module_name) {\n"
"    ensure_context();\n"
"    reset_state();\n"
"    g_module = LLVMModuleCreateWithNameInContext(module_name, g_ctx);\n"
"    LLVMSetSourceFileName(g_module, \"prismio_generated\", strlen(\"prismio_generated\"));\n"
"#ifdef _WIN32\n"
"    // Pinned only on Windows, where msvc and mingw are a real fork and msvc is\n"
"    // the configuration that is actually verified. Elsewhere LLVM's own host\n"
"    // triple is a better answer than a guess. Matches the text backend.\n"
"    LLVMSetTarget(g_module, \"x86_64-pc-windows-msvc\");\n"
"#endif\n"
"}\n"
"\n"
"void ir_module_start_wasm(const char *module_name) {\n"
"    ensure_context();\n"
"    reset_state();\n"
"    g_module = LLVMModuleCreateWithNameInContext(module_name, g_ctx);\n"
"    LLVMSetSourceFileName(g_module, \"prismio_generated\", strlen(\"prismio_generated\"));\n"
"    LLVMSetTarget(g_module, \"wasm32-unknown-unknown\");\n"
"    LLVMSetDataLayout(g_module, \"e-m:e-p:32:32-i64:64-n32:64-S128\");\n"
"}\n"
"\n"
"void ir_module_end(void) { /* nothing to flush -- the module is already built */ }\n"
"\n"
"// ============================================================================\n"
"// Functions\n"
"// ============================================================================\n"
"\n"
"void ir_function_begin(const char *name, const char *ret_type) {\n"
"    strncpy(g_pending_fn_name, name, NAME_LEN - 1);\n"
"    g_pending_fn_name[NAME_LEN - 1] = '\\0';\n"
"    g_pending_ret = type_from_key(ret_type);\n"
"    g_pending_param_count = 0;\n"
"    g_declaring = 0;\n"
"}\n"
"\n"
"void ir_declare_function_begin(const char *name, const char *ret_type) {\n"
"    ir_function_begin(name, ret_type);\n"
"    g_declaring = 1;\n"
"}\n"
"\n"
"void ir_function_param(const char *param_type, const char *param_name) {\n"
"    if (g_pending_param_count >= MAX_PENDING_PARAMS)\n"
"        backend_fail(\"too many parameters\", g_pending_fn_name);\n"
"    g_pending_params[g_pending_param_count] = type_from_key(param_type);\n"
"    strncpy(g_pending_param_names[g_pending_param_count], param_name ? param_name : \"\",\n"
"            NAME_LEN - 1);\n"
"    g_pending_param_names[g_pending_param_count][NAME_LEN - 1] = '\\0';\n"
"    g_pending_param_count++;\n"
"}\n"
"\n"
"void ir_declare_function_param(const char *param_type) {\n"
"    ir_function_param(param_type, \"\");\n"
"}\n"
"\n"
"static LLVMValueRef materialize_function(void) {\n"
"    LLVMTypeRef fnty = LLVMFunctionType(g_pending_ret, g_pending_params,\n"
"                                        (unsigned)g_pending_param_count, 0);\n"
"    LLVMValueRef existing = LLVMGetNamedFunction(g_module, g_pending_fn_name);\n"
"    if (existing) return existing; // a forward `declare` already created it\n"
"    return LLVMAddFunction(g_module, g_pending_fn_name, fnty);\n"
"}\n"
"\n"
"void ir_declare_function_end(void) { materialize_function(); }\n"
"\n"
"void ir_function_body_start(void) {\n"
"    g_function = materialize_function();\n"
"    g_alloca_count = 0;\n"
"    g_param_count = 0;\n"
"    g_has_returned = 0;\n"
"\n"
"    g_entry_block = LLVMAppendBasicBlockInContext(g_ctx, g_function, \"entry\");\n"
"    LLVMPositionBuilderAtEnd(g_builder, g_entry_block);\n"
"\n"
"    for (int i = 0; i < g_pending_param_count; i++) {\n"
"        if (!g_pending_param_names[i][0]) continue;\n"
"        strncpy(g_params[g_param_count].name, g_pending_param_names[i], NAME_LEN - 1);\n"
"        g_params[g_param_count].name[NAME_LEN - 1] = '\\0';\n"
"        g_params[g_param_count].value = LLVMGetParam(g_function, (unsigned)i);\n"
"        g_params[g_param_count].type = g_pending_params[i];\n"
"        g_param_count++;\n"
"    }\n"
"}\n"
"\n"
"void ir_function_end(void) {\n"
"    // A function whose last block has no terminator is invalid. The frontend is\n"
"    // responsible for the return, but guard anyway so the verifier reports\n"
"    // something more useful than a malformed block.\n"
"    LLVMBasicBlockRef bb = LLVMGetInsertBlock(g_builder);\n"
"    if (bb && !LLVMGetBasicBlockTerminator(bb)) LLVMBuildUnreachable(g_builder);\n"
"    g_function = NULL;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Basic blocks\n"
"// ============================================================================\n"
"\n"
"int ir_get_label(void) {\n"
"    if (g_label_count >= MAX_LABELS) backend_fail(\"too many labels\", NULL);\n"
"    g_blocks[g_label_count] = NULL;\n"
"    return g_label_count++;\n"
"}\n"
"\n"
"static LLVMBasicBlockRef block_for(int id) {\n"
"    if (id < 0 || id >= g_label_count) backend_fail(\"label out of range\", NULL);\n"
"    if (!g_blocks[id]) {\n"
"        char name[32];\n"
"        snprintf(name, sizeof(name), \"label_%d\", id);\n"
"        g_blocks[id] = LLVMAppendBasicBlockInContext(g_ctx, g_function, name);\n"
"    }\n"
"    return g_blocks[id];\n"
"}\n"
"\n"
"// True when the block being written already ends in a terminator, meaning any\n"
"// further instruction would be unreachable. The text backend happily wrote past\n"
"// this point and produced invalid IR; here the write is dropped instead, so a\n"
"// stray statement after `return` cannot corrupt the module.\n"
"static int block_done(void) {\n"
"    LLVMBasicBlockRef bb = LLVMGetInsertBlock(g_builder);\n"
"    return !bb || LLVMGetBasicBlockTerminator(bb) != NULL;\n"
"}\n"
"\n"
"void ir_label_numbered(int id) { LLVMPositionBuilderAtEnd(g_builder, block_for(id)); }\n"
"\n"
"void ir_label(const char *name) { (void)name; /* numbered labels only */ }\n"
"\n"
"void ir_br_numbered(int target) {\n"
"    if (block_done()) return;\n"
"    LLVMBuildBr(g_builder, block_for(target));\n"
"}\n"
"\n"
"void ir_cond_br_numbered(const char *cond, int t, int f) {\n"
"    if (block_done()) return;\n"
"    LLVMBuildCondBr(g_builder, resolve_value(cond, \"i1\"), block_for(t), block_for(f));\n"
"}\n"
"\n"
"void ir_br(const char *label) { (void)label; backend_fail(\"named branches are not supported\", label); }\n"
"void ir_cond_br(const char *c, const char *t, const char *f) {\n"
"    (void)c; (void)t; (void)f;\n"
"    backend_fail(\"named branches are not supported\", NULL);\n"
"}\n"
"\n"
"void ir_ret(const char *type, const char *value) {\n"
"    if (block_done()) return;\n"
"    LLVMBuildRet(g_builder, resolve_value(value, type));\n"
"}\n"
"\n"
"void ir_ret_void(void) {\n"
"    if (block_done()) return;\n"
"    LLVMBuildRetVoid(g_builder);\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Memory\n"
"// ============================================================================\n"
"\n"
"int ir_alloca(const char *type, const char *name) {\n"
"    for (int i = 0; i < g_alloca_count; i++) {\n"
"        if (strcmp(g_allocas[i].name, name) == 0) return -1; // already allocated\n"
"    }\n"
"    if (g_alloca_count >= MAX_NAMED) backend_fail(\"too many locals\", name);\n"
"\n"
"    LLVMTypeRef ty = type_from_key(type);\n"
"\n"
"    // Always emitted in the entry block, wherever codegen currently is. The\n"
"    // frontend now creates each local at its declaration, which for a `let`\n"
"    // inside a loop body would otherwise allocate again on every iteration.\n"
"    // Inserted before the entry block's terminator once it has one, so the\n"
"    // alloca cannot end up after a branch.\n"
"    LLVMValueRef entry_term = LLVMGetBasicBlockTerminator(g_entry_block);\n"
"    if (entry_term) {\n"
"        LLVMPositionBuilderBefore(g_alloca_builder, entry_term);\n"
"    } else {\n"
"        LLVMPositionBuilderAtEnd(g_alloca_builder, g_entry_block);\n"
"    }\n"
"    LLVMValueRef slot = LLVMBuildAlloca(g_alloca_builder, ty, name);\n"
"\n"
"    strncpy(g_allocas[g_alloca_count].name, name, NAME_LEN - 1);\n"
"    g_allocas[g_alloca_count].name[NAME_LEN - 1] = '\\0';\n"
"    g_allocas[g_alloca_count].value = slot;\n"
"    g_allocas[g_alloca_count].type = ty;\n"
"    g_alloca_count++;\n"
"    return intern_value(slot);\n"
"}\n"
"\n"
"int ir_load(const char *type, const char *ptr_name) {\n"
"    LLVMTypeRef ty = NULL;\n"
"    LLVMValueRef ptr = lookup_named(g_allocas, g_alloca_count, ptr_name, &ty);\n"
"    if (!ptr) {\n"
"        ptr = lookup_named(g_params, g_param_count, ptr_name, &ty);\n"
"    }\n"
"    if (!ptr) backend_fail(\"load from unknown local\", ptr_name);\n"
"    return intern_value(LLVMBuildLoad2(g_builder, type_from_key(type), ptr, \"\"));\n"
"}\n"
"\n"
"void ir_store(const char *type, const char *value, const char *ptr_name) {\n"
"    LLVMValueRef ptr = lookup_named(g_allocas, g_alloca_count, ptr_name, NULL);\n"
"    if (!ptr) ptr = lookup_named(g_params, g_param_count, ptr_name, NULL);\n"
"    if (!ptr) backend_fail(\"store to unknown local\", ptr_name);\n"
"    if (block_done()) return;\n"
"    LLVMBuildStore(g_builder, resolve_value(value, type), ptr);\n"
"}\n"
"\n"
"// Load/store through a pointer *value* rather than a named local. Struct fields\n"
"// and array elements are addresses produced by a GEP, so they have no name to\n"
"// look up -- the text backend reached them by emitting `store ... ptr %tN`\n"
"// directly, which is one of the things ir_append was being used for.\n"
"int ir_load_ptr(const char *type, const char *ptr_value) {\n"
"    return intern_value(\n"
"        LLVMBuildLoad2(g_builder, type_from_key(type), resolve_value(ptr_value, \"ptr\"), \"\"));\n"
"}\n"
"\n"
"void ir_store_ptr(const char *type, const char *value, const char *ptr_value) {\n"
"    if (block_done()) return;\n"
"    LLVMBuildStore(g_builder, resolve_value(value, type), resolve_value(ptr_value, \"ptr\"));\n"
"}\n"
"\n"
"static LLVMValueRef global_named(const char *name, LLVMTypeRef ty) {\n"
"    LLVMValueRef g = LLVMGetNamedGlobal(g_module, name);\n"
"    if (!g) {\n"
"        g = LLVMAddGlobal(g_module, ty, name);\n"
"        LLVMSetInitializer(g, LLVMConstNull(ty));\n"
"    }\n"
"    return g;\n"
"}\n"
"\n"
"int ir_load_global(const char *type, const char *name) {\n"
"    LLVMTypeRef ty = type_from_key(type);\n"
"    return intern_value(LLVMBuildLoad2(g_builder, ty, global_named(name, ty), \"\"));\n"
"}\n"
"\n"
"void ir_store_global(const char *type, const char *value, const char *name) {\n"
"    if (block_done()) return;\n"
"    LLVMTypeRef ty = type_from_key(type);\n"
"    LLVMBuildStore(g_builder, resolve_value(value, type), global_named(name, ty));\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Object allocation -- the memory-model seam\n"
"// ============================================================================\n"
"\n"
"// Allocates one object of a struct type through the configured allocator.\n"
"// Replaces the hand-written getelementptr-null / ptrtoint / call malloc text\n"
"// the frontend used to emit, and is the single place a different memory model\n"
"// needs to change.\n"
"// AIF T0: the value does not outlive the activation record that creates it, so\n"
"// it needs a stack slot and no allocation call at all (SPEC 3, T0 row).\n"
"//\n"
"// Hoisted to the entry block, like every other alloca here, because a literal\n"
"// inside a loop would otherwise allocate a fresh slot per iteration and grow the\n"
"// frame without bound. That means **one slot per site, reused by every\n"
"// iteration** -- which is only correct because T0 requires the value's escape to\n"
"// bottom at its own defining scope, i.e. nothing from one iteration is still\n"
"// reachable in the next. The escape module has to be right about that; when it\n"
"// was not, this was a miscompile rather than a slowdown (see aif_var_scope in\n"
"// aif_support.c).\n"
"//\n"
"// Unnamed and never deduplicated, unlike ir_alloca: two struct literals of the\n"
"// same type in one function are two values and need two slots.\n"
"int ir_alloc_stack(const char *struct_name) {\n"
"    LLVMTypeRef sty = named_struct(struct_name);\n"
"\n"
"    LLVMValueRef entry_term = LLVMGetBasicBlockTerminator(g_entry_block);\n"
"    if (entry_term) {\n"
"        LLVMPositionBuilderBefore(g_alloca_builder, entry_term);\n"
"    } else {\n"
"        LLVMPositionBuilderAtEnd(g_alloca_builder, g_entry_block);\n"
"    }\n"
"\n"
"    return intern_value(LLVMBuildAlloca(g_alloca_builder, sty, \"\"));\n"
"}\n"
"\n"
"int ir_alloc_object(const char *struct_name) {\n"
"    LLVMTypeRef sty = named_struct(struct_name);\n"
"    LLVMTypeRef size_ty = type_from_key(g_ptr_int);\n"
"    LLVMTypeRef ptr = LLVMPointerTypeInContext(g_ctx, 0);\n"
"\n"
"    // LLVMSizeOf yields an i64; narrow it when the target's size argument is\n"
"    // smaller, so the call matches the allocator's declared signature.\n"
"    LLVMValueRef size = LLVMSizeOf(sty);\n"
"    if (size_ty != LLVMInt64TypeInContext(g_ctx)) {\n"
"        size = LLVMBuildTrunc(g_builder, size, size_ty, \"\");\n"
"    }\n"
"\n"
"    LLVMTypeRef alloc_ty = LLVMFunctionType(ptr, &size_ty, 1, 0);\n"
"    LLVMValueRef alloc_fn = LLVMGetNamedFunction(g_module, g_alloc_fn);\n"
"    if (!alloc_fn) alloc_fn = LLVMAddFunction(g_module, g_alloc_fn, alloc_ty);\n"
"\n"
"    LLVMValueRef args[1] = {size};\n"
"    return intern_value(LLVMBuildCall2(g_builder, alloc_ty, alloc_fn, args, 1, \"\"));\n"
"}\n"
"\n"
"// The third hook COMPILER-AUDIT 3 asked for. It expected `fn(arena, size) -> ptr`\n"
"// with the handle threaded from the enclosing region; the arena is dynamically\n"
"// scoped instead (see runtime/lang_runtime.c), so the signature stays\n"
"// `fn(size) -> ptr` and no frontend plumbing is needed to reach it.\n"
"//\n"
"// Unlike ir_alloc_object this does not read g_alloc_fn: a region allocation is a\n"
"// different obligation, not a different allocator, and routing it through the\n"
"// name swap would mean a verify build tried to account for memory the arena\n"
"// releases in bulk.\n"
"int ir_alloc_region(const char *struct_name) {\n"
"    LLVMTypeRef sty = named_struct(struct_name);\n"
"    LLVMTypeRef size_ty = type_from_key(g_ptr_int);\n"
"    LLVMTypeRef ptr = LLVMPointerTypeInContext(g_ctx, 0);\n"
"\n"
"    LLVMValueRef size = LLVMSizeOf(sty);\n"
"    if (size_ty != LLVMInt64TypeInContext(g_ctx)) {\n"
"        size = LLVMBuildTrunc(g_builder, size, size_ty, \"\");\n"
"    }\n"
"\n"
"    LLVMTypeRef alloc_ty = LLVMFunctionType(ptr, &size_ty, 1, 0);\n"
"    LLVMValueRef alloc_fn = LLVMGetNamedFunction(g_module, \"arena_alloc\");\n"
"    if (!alloc_fn) alloc_fn = LLVMAddFunction(g_module, \"arena_alloc\", alloc_ty);\n"
"\n"
"    LLVMValueRef args[1] = {size};\n"
"    return intern_value(LLVMBuildCall2(g_builder, alloc_ty, alloc_fn, args, 1, \"\"));\n"
"}\n"
"\n"
"// AIF Level 5, and the fourth hook. COMPILER-AUDIT 3 rated T3 only \"partly\"\n"
"// expressible through the seam because a count word changes struct layout, which\n"
"// named_struct and every ir_struct_field_ptr index would have to account for. A\n"
"// *prefix* header avoids that entirely -- the count sits in front of the pointer,\n"
"// the LLVM struct type is untouched, and what is left really is just a name.\n"
"//\n"
"// Like ir_alloc_region, this does not read g_alloc_fn. rc_alloc reaches the verify\n"
"// shim through the runtime's own rt_base_alloc, so both ends of the pairing swap\n"
"// together when the runtime is compiled -- the same arrangement Level 4 needed for\n"
"// strings, and for the same reason.\n"
"int ir_alloc_rc(const char *struct_name) {\n"
"    LLVMTypeRef sty = named_struct(struct_name);\n"
"    LLVMTypeRef size_ty = type_from_key(g_ptr_int);\n"
"    LLVMTypeRef ptr = LLVMPointerTypeInContext(g_ctx, 0);\n"
"\n"
"    LLVMValueRef size = LLVMSizeOf(sty);\n"
"    if (size_ty != LLVMInt64TypeInContext(g_ctx)) {\n"
"        size = LLVMBuildTrunc(g_builder, size, size_ty, \"\");\n"
"    }\n"
"\n"
"    LLVMTypeRef alloc_ty = LLVMFunctionType(ptr, &size_ty, 1, 0);\n"
"    LLVMValueRef alloc_fn = LLVMGetNamedFunction(g_module, \"rc_alloc\");\n"
"    if (!alloc_fn) alloc_fn = LLVMAddFunction(g_module, \"rc_alloc\", alloc_ty);\n"
"\n"
"    LLVMValueRef args[1] = {size};\n"
"    return intern_value(LLVMBuildCall2(g_builder, alloc_ty, alloc_fn, args, 1, \"\"));\n"
"}\n"
"\n"
"// Region entry and exit. Emitted at every exit from the block, like the drops --\n"
"// a `return` out of a region that did not pop would leave the arena live for the\n"
"// rest of the program.\n"
"static void ir_arena_call(const char *name) {\n"
"    if (block_done()) return;\n"
"    LLVMTypeRef voidty = LLVMVoidTypeInContext(g_ctx);\n"
"    LLVMTypeRef fn_ty = LLVMFunctionType(voidty, NULL, 0, 0);\n"
"    LLVMValueRef fn = LLVMGetNamedFunction(g_module, name);\n"
"    if (!fn) fn = LLVMAddFunction(g_module, name, fn_ty);\n"
"    LLVMBuildCall2(g_builder, fn_ty, fn, NULL, 0, \"\");\n"
"}\n"
"\n"
"void ir_region_begin(void) { ir_arena_call(\"arena_push\"); }\n"
"void ir_region_end(void)   { ir_arena_call(\"arena_pop\"); }\n"
"\n"
"// AIF Level 4. A string or a list is allocated inside the runtime, not through\n"
"// ir_alloc_region, so the site cannot pick the arena for itself. Bracketing the\n"
"// producing call says \"the allocation this one makes belongs to the region\", and\n"
"// the runtime bumps rather than calling malloc. Emitted around the call only;\n"
"// the arguments are already evaluated by then.\n"
"void ir_arena_hint_begin(void) { ir_arena_call(\"rt_arena_hint_push\"); }\n"
"void ir_arena_hint_end(void)   { ir_arena_call(\"rt_arena_hint_pop\"); }\n"
"\n"
"static void ir_release_call(const char *value, const char *fn_name) {\n"
"    if (block_done()) return;\n"
"    LLVMTypeRef voidty = LLVMVoidTypeInContext(g_ctx);\n"
"    LLVMTypeRef ptr = LLVMPointerTypeInContext(g_ctx, 0);\n"
"\n"
"    LLVMTypeRef free_ty = LLVMFunctionType(voidty, &ptr, 1, 0);\n"
"    LLVMValueRef free_fn = LLVMGetNamedFunction(g_module, fn_name);\n"
"    if (!free_fn) free_fn = LLVMAddFunction(g_module, fn_name, free_ty);\n"
"\n"
"    LLVMValueRef args[1] = {resolve_value(value, \"ptr\")};\n"
"    LLVMBuildCall2(g_builder, free_ty, free_fn, args, 1, \"\");\n"
"}\n"
"\n"
"void ir_free_object(const char *value) { ir_release_call(value, g_free_fn); }\n"
"\n"
"// AIF Level 4. A list is a handle plus an element block, so the one-pointer\n"
"// deallocator the seam names cannot reclaim it. `list_release` is the runtime's\n"
"// own -- it frees both through the same allocator the list came from, which is\n"
"// what keeps a verify build's accounting balanced.\n"
"void ir_free_list(const char *value) { ir_release_call(value, \"list_release\"); }\n"
"\n"
"// Struct-field ownership. A struct that owns its fields is reclaimed by a\n"
"// function generated for its type, so the callee is named by the caller rather\n"
"// than fixed. It is still behind the seam: what that generated function frees,\n"
"// it frees through ir_free_object and its siblings.\n"
"void ir_free_typed(const char *value, const char *fn_name) { ir_release_call(value, fn_name); }\n"
"\n"
"// AIF Level 5. The decrement half, for a counted value held in a struct field.\n"
"void ir_free_rc(const char *value) { ir_release_call(value, \"rc_release\"); }\n"
"\n"
"// AIF T4b. The fifth allocator hook, and a `fn(size) -> ptr` like the other\n"
"// four: the colour and the per-type descriptor go in front of the pointer, so\n"
"// the LLVM struct type is untouched and cyc_set_type fills them in afterwards --\n"
"// the same shape as list_set_elem_owner, and for the same reason.\n"
"int ir_alloc_cycle(const char *struct_name) {\n"
"    LLVMTypeRef sty = named_struct(struct_name);\n"
"    LLVMTypeRef size_ty = type_from_key(g_ptr_int);\n"
"    LLVMTypeRef ptr = LLVMPointerTypeInContext(g_ctx, 0);\n"
"\n"
"    LLVMValueRef size = LLVMSizeOf(sty);\n"
"    if (size_ty != LLVMInt64TypeInContext(g_ctx)) {\n"
"        size = LLVMBuildTrunc(g_builder, size, size_ty, \"\");\n"
"    }\n"
"\n"
"    LLVMTypeRef alloc_ty = LLVMFunctionType(ptr, &size_ty, 1, 0);\n"
"    LLVMValueRef alloc_fn = LLVMGetNamedFunction(g_module, \"cyc_alloc\");\n"
"    if (!alloc_fn) alloc_fn = LLVMAddFunction(g_module, \"cyc_alloc\", alloc_ty);\n"
"\n"
"    LLVMValueRef args[1] = {size};\n"
"    return intern_value(LLVMBuildCall2(g_builder, alloc_ty, alloc_fn, args, 1, \"\"));\n"
"}\n"
"\n"
"// An indirect call to a `fn(ptr) -> void` through a function pointer.\n"
"//\n"
"// The collector's visitor is a value rather than a name: the children function\n"
"// is generated per type, and the visitor differs per traversal phase, so the\n"
"// callee cannot be baked into the call.\n"
"void ir_call_indirect_ptr(const char *fn_value, const char *arg) {\n"
"    if (block_done()) return;\n"
"    LLVMTypeRef voidty = LLVMVoidTypeInContext(g_ctx);\n"
"    LLVMTypeRef ptr = LLVMPointerTypeInContext(g_ctx, 0);\n"
"    LLVMTypeRef fn_ty = LLVMFunctionType(voidty, &ptr, 1, 0);\n"
"    LLVMValueRef args[1] = {resolve_value(arg, \"ptr\")};\n"
"    LLVMBuildCall2(g_builder, fn_ty, resolve_value(fn_value, \"ptr\"), args, 1, \"\");\n"
"}\n"
"\n"
"// The address of a named function, as a value.\n"
"//\n"
"// Needed because a container of structs-with-owned-fields cannot be told its\n"
"// disposition with an int: the release differs per element *type*, and the\n"
"// runtime has no way to name a type. So it is told the function instead, which\n"
"// is the same \"the container is told, it cannot ask\" rule the int modes follow.\n"
"int ir_func_addr(const char *name) {\n"
"    LLVMValueRef fn = LLVMGetNamedFunction(g_module, name);\n"
"    if (!fn) backend_fail(\"address of unknown function\", name);\n"
"    return intern_value(fn);\n"
"}\n"
"\n"
"// Field address within a struct object. Replaces emitted getelementptr text.\n"
"int ir_struct_field_ptr(const char *struct_name, const char *object, int field_index) {\n"
"    LLVMTypeRef sty = named_struct(struct_name);\n"
"    LLVMValueRef obj = resolve_value(object, \"ptr\");\n"
"    if (field_index < 0) backend_fail(\"negative struct field index\", struct_name);\n"
"    return intern_value(\n"
"        LLVMBuildStructGEP2(g_builder, sty, obj, (unsigned)field_index, \"\"));\n"
"}\n"
"\n"
"// Address of element `index` in a flat array of `elem_type`.\n"
"int ir_elem_ptr(const char *elem_type, const char *base, const char *index) {\n"
"    LLVMTypeRef ety = type_from_key(elem_type);\n"
"    LLVMValueRef idx[1] = {resolve_value(index, \"i32\")};\n"
"    return intern_value(\n"
"        LLVMBuildInBoundsGEP2(g_builder, ety, resolve_value(base, \"ptr\"), idx, 1, \"\"));\n"
"}\n"
"\n"
"// Stack array of `count` elements, yielding a pointer to the first element.\n"
"int ir_array_alloca(const char *elem_type, int count) {\n"
"    LLVMTypeRef ety = type_from_key(elem_type);\n"
"    LLVMTypeRef arr = LLVMArrayType2(ety, (uint64_t)count);\n"
"    LLVMValueRef slot = LLVMBuildAlloca(g_builder, arr, \"\");\n"
"    LLVMTypeRef i32 = LLVMInt32TypeInContext(g_ctx);\n"
"    LLVMValueRef idx[2] = {LLVMConstInt(i32, 0, 0), LLVMConstInt(i32, 0, 0)};\n"
"    return intern_value(LLVMBuildInBoundsGEP2(g_builder, arr, slot, idx, 2, \"\"));\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Arithmetic, comparison, conversion\n"
"// ============================================================================\n"
"\n"
"#define BINOP(fn_name, builder_call)                                                   \\\n"
"    int fn_name(const char *type, const char *lhs, const char *rhs) {                  \\\n"
"        LLVMValueRef l = resolve_value(lhs, type);                                     \\\n"
"        LLVMValueRef r = resolve_value(rhs, type);                                     \\\n"
"        return intern_value(builder_call(g_builder, l, r, \"\"));                        \\\n"
"    }\n"
"\n"
"BINOP(ir_add, LLVMBuildAdd)\n"
"BINOP(ir_sub, LLVMBuildSub)\n"
"BINOP(ir_mul, LLVMBuildMul)\n"
"BINOP(ir_sdiv, LLVMBuildSDiv)\n"
"BINOP(ir_udiv, LLVMBuildUDiv)\n"
"BINOP(ir_srem, LLVMBuildSRem)\n"
"BINOP(ir_urem, LLVMBuildURem)\n"
"BINOP(ir_fadd, LLVMBuildFAdd)\n"
"BINOP(ir_fsub, LLVMBuildFSub)\n"
"BINOP(ir_fmul, LLVMBuildFMul)\n"
"BINOP(ir_fdiv, LLVMBuildFDiv)\n"
"BINOP(ir_and, LLVMBuildAnd)\n"
"BINOP(ir_or, LLVMBuildOr)\n"
"BINOP(ir_xor, LLVMBuildXor)\n"
"BINOP(ir_shl, LLVMBuildShl)\n"
"BINOP(ir_lshr, LLVMBuildLShr)\n"
"BINOP(ir_ashr, LLVMBuildAShr)\n"
"\n"
"int ir_neg(const char *type, const char *value) {\n"
"    return intern_value(LLVMBuildNeg(g_builder, resolve_value(value, type), \"\"));\n"
"}\n"
"\n"
"int ir_fneg(const char *type, const char *value) {\n"
"    return intern_value(LLVMBuildFNeg(g_builder, resolve_value(value, type), \"\"));\n"
"}\n"
"\n"
"int ir_not(const char *type, const char *value) {\n"
"    return intern_value(LLVMBuildNot(g_builder, resolve_value(value, type), \"\"));\n"
"}\n"
"\n"
"#define ICMP(fn_name, pred)                                                            \\\n"
"    int fn_name(const char *type, const char *lhs, const char *rhs) {                  \\\n"
"        LLVMValueRef l = resolve_value(lhs, type);                                     \\\n"
"        LLVMValueRef r = resolve_value(rhs, type);                                     \\\n"
"        return intern_value(LLVMBuildICmp(g_builder, pred, l, r, \"\"));                 \\\n"
"    }\n"
"\n"
"ICMP(ir_icmp_eq, LLVMIntEQ)\n"
"ICMP(ir_icmp_ne, LLVMIntNE)\n"
"ICMP(ir_icmp_slt, LLVMIntSLT)\n"
"ICMP(ir_icmp_sle, LLVMIntSLE)\n"
"ICMP(ir_icmp_sgt, LLVMIntSGT)\n"
"ICMP(ir_icmp_sge, LLVMIntSGE)\n"
"ICMP(ir_icmp_ult, LLVMIntULT)\n"
"ICMP(ir_icmp_ule, LLVMIntULE)\n"
"ICMP(ir_icmp_ugt, LLVMIntUGT)\n"
"ICMP(ir_icmp_uge, LLVMIntUGE)\n"
"\n"
"#define FCMP(fn_name, pred)                                                            \\\n"
"    int fn_name(const char *type, const char *lhs, const char *rhs) {                  \\\n"
"        LLVMValueRef l = resolve_value(lhs, type);                                     \\\n"
"        LLVMValueRef r = resolve_value(rhs, type);                                     \\\n"
"        return intern_value(LLVMBuildFCmp(g_builder, pred, l, r, \"\"));                 \\\n"
"    }\n"
"\n"
"FCMP(ir_fcmp_oeq, LLVMRealOEQ)\n"
"FCMP(ir_fcmp_one, LLVMRealONE)\n"
"FCMP(ir_fcmp_olt, LLVMRealOLT)\n"
"FCMP(ir_fcmp_ole, LLVMRealOLE)\n"
"FCMP(ir_fcmp_ogt, LLVMRealOGT)\n"
"FCMP(ir_fcmp_oge, LLVMRealOGE)\n"
"\n"
"int ir_zext(const char *from_type, const char *value, const char *to_type) {\n"
"    return intern_value(LLVMBuildZExt(g_builder, resolve_value(value, from_type),\n"
"                                      type_from_key(to_type), \"\"));\n"
"}\n"
"\n"
"int ir_sext(const char *from_type, const char *value, const char *to_type) {\n"
"    return intern_value(LLVMBuildSExt(g_builder, resolve_value(value, from_type),\n"
"                                      type_from_key(to_type), \"\"));\n"
"}\n"
"\n"
"int ir_trunc(const char *from_type, const char *value, const char *to_type) {\n"
"    return intern_value(LLVMBuildTrunc(g_builder, resolve_value(value, from_type),\n"
"                                       type_from_key(to_type), \"\"));\n"
"}\n"
"\n"
"// REQUIREMENTS 20. A `List<T>` stores pointer-sized slots, so a scalar element\n"
"// rides in one rather than being boxed. Boxing would cost an allocation per\n"
"// element *and* give the container something to own, which is the opposite of\n"
"// what a scalar element is: nothing allocates, so there is no site and nothing\n"
"// to release.\n"
"int ir_int_to_ptr(const char *from_type, const char *value) {\n"
"    LLVMTypeRef ptr = LLVMPointerTypeInContext(g_ctx, 0);\n"
"    return intern_value(LLVMBuildIntToPtr(g_builder, resolve_value(value, from_type),\n"
"                                          ptr, \"\"));\n"
"}\n"
"\n"
"int ir_ptr_to_int(const char *value, const char *to_type) {\n"
"    return intern_value(LLVMBuildPtrToInt(g_builder, resolve_value(value, \"ptr\"),\n"
"                                          type_from_key(to_type), \"\"));\n"
"}\n"
"\n"
"// The float half of the same round trip: a double is 64 bits of payload, not a\n"
"// number to convert, so this reinterprets rather than rounding.\n"
"int ir_bitcast(const char *from_type, const char *value, const char *to_type) {\n"
"    return intern_value(LLVMBuildBitCast(g_builder, resolve_value(value, from_type),\n"
"                                         type_from_key(to_type), \"\"));\n"
"}\n"
"\n"
"// Integer <-> floating point. Needed by `as`; the signed and unsigned forms are\n"
"// distinct instructions, so the frontend picks based on the source/target type.\n"
"int ir_sitofp(const char *from_type, const char *value, const char *to_type) {\n"
"    return intern_value(LLVMBuildSIToFP(g_builder, resolve_value(value, from_type),\n"
"                                        type_from_key(to_type), \"\"));\n"
"}\n"
"\n"
"int ir_uitofp(const char *from_type, const char *value, const char *to_type) {\n"
"    return intern_value(LLVMBuildUIToFP(g_builder, resolve_value(value, from_type),\n"
"                                        type_from_key(to_type), \"\"));\n"
"}\n"
"\n"
"int ir_fptosi(const char *from_type, const char *value, const char *to_type) {\n"
"    return intern_value(LLVMBuildFPToSI(g_builder, resolve_value(value, from_type),\n"
"                                        type_from_key(to_type), \"\"));\n"
"}\n"
"\n"
"int ir_fptoui(const char *from_type, const char *value, const char *to_type) {\n"
"    return intern_value(LLVMBuildFPToUI(g_builder, resolve_value(value, from_type),\n"
"                                        type_from_key(to_type), \"\"));\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Calls\n"
"// ============================================================================\n"
"\n"
"void ir_call_begin(void) {\n"
"    if (g_call_depth >= MAX_CALL_DEPTH) backend_fail(\"call nesting too deep\", NULL);\n"
"    g_calls[g_call_depth].count = 0;\n"
"    g_call_depth++;\n"
"}\n"
"\n"
"void ir_call_arg(const char *arg_type, const char *arg_value) {\n"
"    if (g_call_depth <= 0) backend_fail(\"call argument outside a call\", arg_value);\n"
"    CallFrame *f = &g_calls[g_call_depth - 1];\n"
"    if (f->count >= MAX_CALL_ARGS) backend_fail(\"too many call arguments\", NULL);\n"
"    f->args[f->count++] = resolve_value(arg_value, arg_type);\n"
"}\n"
"\n"
"int ir_call_end(const char *ret_type, const char *func_name) {\n"
"    if (g_call_depth <= 0) backend_fail(\"call end without begin\", func_name);\n"
"    CallFrame *f = &g_calls[--g_call_depth];\n"
"\n"
"    int is_void = (!ret_type || !*ret_type || strcmp(ret_type, \"void\") == 0);\n"
"\n"
"    LLVMValueRef fn = LLVMGetNamedFunction(g_module, func_name);\n"
"    if (!fn) {\n"
"        // Forward reference. Functions are emitted in a second pass, so a call\n"
"        // can precede its definition, and generate_module deliberately skips\n"
"        // the `declare` for any function the module also defines -- that is the\n"
"        // forward-declaration idiom the compiler's own sources rely on\n"
"        // (parser.psm, sema.psm and ir.psm all `extern fn` something they then\n"
"        // define). The text backend never noticed because it wrote the call as\n"
"        // text and left resolution to the assembler.\n"
"        //\n"
"        // Synthesise the declaration from the call site. The frontend has\n"
"        // already type-checked the call, so the argument types are the\n"
"        // definition's parameter types, and materialize_function() reuses this\n"
"        // same LLVMValueRef when the definition is finally built.\n"
"        LLVMTypeRef param_types[MAX_CALL_ARGS];\n"
"        for (int i = 0; i < f->count; i++) param_types[i] = LLVMTypeOf(f->args[i]);\n"
"        LLVMTypeRef rty = is_void ? LLVMVoidTypeInContext(g_ctx) : type_from_key(ret_type);\n"
"        LLVMTypeRef synth = LLVMFunctionType(rty, param_types, (unsigned)f->count, 0);\n"
"        fn = LLVMAddFunction(g_module, func_name, synth);\n"
"    }\n"
"\n"
"    LLVMTypeRef fnty = LLVMGlobalGetValueType(fn);\n"
"    LLVMValueRef call = LLVMBuildCall2(g_builder, fnty, fn, f->args, (unsigned)f->count, \"\");\n"
"\n"
"    return is_void ? -1 : intern_value(call);\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Globals and string constants\n"
"// ============================================================================\n"
"\n"
"void ir_global_var(const char *name, const char *type, const char *init_value,\n"
"                   int is_const) {\n"
"    LLVMTypeRef ty = type_from_key(type);\n"
"    LLVMValueRef g = LLVMGetNamedGlobal(g_module, name);\n"
"    if (!g) g = LLVMAddGlobal(g_module, ty, name);\n"
"\n"
"    // An initializer naming another global (a string constant) arrives as \"@name\".\n"
"    if (init_value && init_value[0] == '@') {\n"
"        LLVMValueRef target = LLVMGetNamedGlobal(g_module, init_value + 1);\n"
"        if (!target) backend_fail(\"global initializer names an unknown global\", init_value);\n"
"        LLVMSetInitializer(g, target);\n"
"    } else if (init_value && *init_value) {\n"
"        LLVMSetInitializer(g, const_from_text(init_value, ty));\n"
"    } else {\n"
"        LLVMSetInitializer(g, LLVMConstNull(ty));\n"
"    }\n"
"    if (is_const) LLVMSetGlobalConstant(g, 1);\n"
"}\n"
"\n"
"void ir_global_string(const char *name, const char *content) {\n"
"    unsigned len = (unsigned)strlen(content);\n"
"    LLVMValueRef str = LLVMConstStringInContext(g_ctx, content, len, 0); // NUL-terminated\n"
"    LLVMTypeRef arr = LLVMArrayType2(LLVMInt8TypeInContext(g_ctx), (uint64_t)len + 1);\n"
"    LLVMValueRef g = LLVMAddGlobal(g_module, arr, name);\n"
"    LLVMSetInitializer(g, str);\n"
"    LLVMSetLinkage(g, LLVMPrivateLinkage);\n"
"    LLVMSetGlobalConstant(g, 1);\n"
"    LLVMSetUnnamedAddr(g, 1);\n"
"}\n"
"\n"
"// Pointer to the first byte of a previously created string global.\n"
"int ir_string_ptr(const char *global_name) {\n"
"    LLVMValueRef g = LLVMGetNamedGlobal(g_module, global_name);\n"
"    if (!g) backend_fail(\"unknown string global\", global_name);\n"
"    // With opaque pointers the global's address already is the pointer we want.\n"
"    return intern_value(g);\n"
"}\n"
"\n"
"// Return tracking, the struct/enum/global registries, var types and move/borrow\n"
"// state all live in ir_symbols.c -- they are compiler bookkeeping shared by both\n"
"// backends, not emission state.\n"
"\n"
"// ============================================================================\n"
"// Raw text: deliberately unsupported\n"
"// ============================================================================\n"
"\n"
"// The text backend let the frontend splice arbitrary IR text into the output,\n"
"// which is how struct literals, GEPs and array indexing were emitted. There is\n"
"// no way to honour that here, and quietly ignoring it would produce a module\n"
"// missing whole instructions. Fail loudly instead: every remaining caller is a\n"
"// site that still needs migrating to a typed builder above.\n"
"void ir_append(const char *text) {\n"
"    backend_fail(\"ir_append() has no meaning in the LLVM API backend; \"\n"
"                 \"migrate this call site to a typed builder\",\n"
"                 text);\n"
"}\n"
"\n"
"void ir_append_line(const char *text) { ir_append(text); }\n"
"\n"
"void ir_comment(const char *text) { (void)text; /* comments have no IR representation */ }\n"
"void ir_blank_line(void) { /* formatting only */ }\n"
"\n"
"// ============================================================================\n"
"// Output\n"
"// ============================================================================\n"
"\n"
"// Verifies before writing. This is the check the text backend never had: a\n"
"// malformed module is reported here, against the code that built it, instead of\n"
"// surfacing later as an llc parse error pointing at generated text.\n"
"// -O level, 0 by default -- unoptimized, which is what shipped before this\n"
"// existed: no pass pipeline was ever run over the generated module.\n"
"static int g_opt_level = 0;\n"
"\n"
"void ir_set_opt_level(int level) {\n"
"    if (level < 0) level = 0;\n"
"    if (level > 3) level = 3;\n"
"    g_opt_level = level;\n"
"}\n"
"\n"
"// Runs LLVM's standard pipeline over the module before it is written.\n"
"//\n"
"// The frontend emits a load/store through a stack slot for every binding, so\n"
"// even -O1 (which includes mem2reg/SROA) is a large improvement over the raw\n"
"// output. No TargetMachine is passed: these are the target-independent passes,\n"
"// and llc still does target-specific work afterwards.\n"
"static int run_optimization(void) {\n"
"    if (g_opt_level == 0) return 0;\n"
"\n"
"    char pipeline[32];\n"
"    snprintf(pipeline, sizeof(pipeline), \"default<O%d>\", g_opt_level);\n"
"\n"
"    LLVMPassBuilderOptionsRef options = LLVMCreatePassBuilderOptions();\n"
"    LLVMErrorRef err = LLVMRunPasses(g_module, pipeline, NULL, options);\n"
"    LLVMDisposePassBuilderOptions(options);\n"
"\n"
"    if (err) {\n"
"        char *msg = LLVMGetErrorMessage(err);\n"
"        fprintf(stderr, \"error: optimization pipeline failed: %s\\n\", msg ? msg : \"?\");\n"
"        return 1;\n"
"    }\n"
"    return 0;\n"
"}\n"
"\n"
"int ir_write_file(const char *filename) {\n"
"    char *err = NULL;\n"
"\n"
"    // Verify first: optimizing an already-invalid module produces far worse\n"
"    // diagnostics than reporting the original problem.\n"
"    if (LLVMVerifyModule(g_module, LLVMReturnStatusAction, &err)) {\n"
"        fprintf(stderr, \"error: generated module failed verification\\n\");\n"
"        if (err) fprintf(stderr, \"%s\\n\", err);\n"
"        if (err) LLVMDisposeMessage(err);\n"
"        return 1;\n"
"    }\n"
"    if (err) { LLVMDisposeMessage(err); err = NULL; }\n"
"\n"
"    if (run_optimization() != 0) return 1;\n"
"    if (LLVMVerifyModule(g_module, LLVMReturnStatusAction, &err)) {\n"
"        fprintf(stderr, \"error: generated module failed verification\\n\");\n"
"        if (err) fprintf(stderr, \"%s\\n\", err);\n"
"        if (err) LLVMDisposeMessage(err);\n"
"        return 1;\n"
"    }\n"
"    if (err) LLVMDisposeMessage(err);\n"
"\n"
"    char *werr = NULL;\n"
"    if (LLVMPrintModuleToFile(g_module, filename, &werr)) {\n"
"        fprintf(stderr, \"error: could not write %s: %s\\n\", filename, werr ? werr : \"?\");\n"
"        if (werr) LLVMDisposeMessage(werr);\n"
"        return 1;\n"
"    }\n"
"    return 0;\n"
"}\n"
"\n"
"void ir_print(void) {\n"
"    char *s = LLVMPrintModuleToString(g_module);\n"
"    if (s) {\n"
"        printf(\"%s\", s);\n"
"        LLVMDisposeMessage(s);\n"
"    }\n"
"}\n"
;

#endif
